impl AgentsWorkspaceTabCloseScope {
    fn action_value(self) -> u8 {
        match self {
            Self::Close => 0,
            Self::CloseLeft => 1,
            Self::CloseOthers => 2,
            Self::CloseRight => 3,
        }
    }

    fn from_action_value(value: u8) -> Option<Self> {
        match value {
            0 => Some(Self::Close),
            1 => Some(Self::CloseLeft),
            2 => Some(Self::CloseOthers),
            3 => Some(Self::CloseRight),
            _ => None,
        }
    }
}

