#[derive(Clone, Copy, PartialEq, Eq)]
struct ProjectEditorPlaceholderSignature {
    mode: TitlebarMode,
    title: &'static str,
    message: &'static str,
    color_identity: ProjectEditorPlaceholderColorIdentity,
}

impl ProjectEditorPlaceholderSignature {
    fn for_mode(mode: TitlebarMode) -> Option<Self> {
        let color_identity = match mode {
            TitlebarMode::Source => ProjectEditorPlaceholderColorIdentity::SourceTeal,
            TitlebarMode::Kanban => ProjectEditorPlaceholderColorIdentity::KanbanPurple,
            TitlebarMode::Manage => ProjectEditorPlaceholderColorIdentity::ManagePink,
            TitlebarMode::Agents | TitlebarMode::Browser => return None,
        };

        Some(Self {
            mode,
            title: mode.placeholder_title(),
            message: mode.placeholder_message(),
            color_identity,
        })
    }

    fn for_source_code_server_launch_state(
        state: SourceCodeServerRuntimeLaunchState,
    ) -> Option<Self> {
        let signature = Self::for_mode(TitlebarMode::Source)?;
        let (title, message) = match state {
            SourceCodeServerRuntimeLaunchState::Launching => (
                "Source is loading",
                "Source is preparing the editor. The workspace stays selected while the editor surface is not ready.",
            ),
            SourceCodeServerRuntimeLaunchState::Failed => (
                "Source load failed",
                "Source could not load. The workspace stays selected so the editor state can be retried later.",
            ),
            _ => return Some(signature),
        };

        Some(Self {
            title,
            message,
            ..signature
        })
    }
}

