fn workspace_close_focus_replacement_leaf_id(
    node: &WorkspaceNode,
    pane_id: WorkspacePaneId,
) -> Option<WorkspacePaneId> {
    match node {
        WorkspaceNode::Leaf(_) => None,
        WorkspaceNode::Split(split) => {
            if workspace_node_contains_pane(&split.first, pane_id) {
                workspace_close_focus_replacement_leaf_id(&split.first, pane_id).or_else(|| {
                    let edge = match split.axis {
                        WorkspaceSplitAxis::Horizontal => WorkspaceCollapseFocusEdge::Left,
                        WorkspaceSplitAxis::Vertical => WorkspaceCollapseFocusEdge::Top,
                    };
                    workspace_leaf_id_on_collapse_edge(&split.second, edge)
                })
            } else if workspace_node_contains_pane(&split.second, pane_id) {
                workspace_close_focus_replacement_leaf_id(&split.second, pane_id).or_else(|| {
                    let edge = match split.axis {
                        WorkspaceSplitAxis::Horizontal => WorkspaceCollapseFocusEdge::Right,
                        WorkspaceSplitAxis::Vertical => WorkspaceCollapseFocusEdge::Bottom,
                    };
                    workspace_leaf_id_on_collapse_edge(&split.first, edge)
                })
            } else {
                None
            }
        }
    }
}

fn workspace_leaf_id_on_collapse_edge(
    node: &WorkspaceNode,
    edge: WorkspaceCollapseFocusEdge,
) -> Option<WorkspacePaneId> {
    match node {
        WorkspaceNode::Leaf(leaf) if !leaf.tab_group.tabs.is_empty() => Some(leaf.pane_id),
        WorkspaceNode::Leaf(_) => None,
        WorkspaceNode::Split(split) => {
            let (primary, secondary) = if matches!(
                edge,
                WorkspaceCollapseFocusEdge::Left | WorkspaceCollapseFocusEdge::Top
            ) {
                (&split.first, &split.second)
            } else {
                (&split.second, &split.first)
            };
            workspace_leaf_id_on_collapse_edge(primary, edge)
                .or_else(|| workspace_leaf_id_on_collapse_edge(secondary, edge))
        }
    }
}

fn insert_workspace_leaf_split(
    node: &mut WorkspaceNode,
    target_pane_id: WorkspacePaneId,
    new_leaf: WorkspaceLeaf,
    axis: WorkspaceSplitAxis,
    dragged_first: bool,
    split_id: WorkspaceSplitId,
) -> bool {
    match node {
        WorkspaceNode::Leaf(leaf) if leaf.pane_id == target_pane_id => {
            let existing = std::mem::replace(node, workspace_dummy_node());
            let new_node = WorkspaceNode::Leaf(new_leaf);
            let (first, second) = if dragged_first {
                (new_node, existing)
            } else {
                (existing, new_node)
            };

            *node = WorkspaceNode::Split(WorkspaceSplit {
                id: split_id,
                axis,
                ratio: 0.5,
                first: Box::new(first),
                second: Box::new(second),
            });
            true
        }
        WorkspaceNode::Leaf(_) => false,
        WorkspaceNode::Split(split) => {
            if workspace_node_contains_pane(&split.first, target_pane_id) {
                insert_workspace_leaf_split(
                    &mut split.first,
                    target_pane_id,
                    new_leaf,
                    axis,
                    dragged_first,
                    split_id,
                )
            } else {
                insert_workspace_leaf_split(
                    &mut split.second,
                    target_pane_id,
                    new_leaf,
                    axis,
                    dragged_first,
                    split_id,
                )
            }
        }
    }
}

fn collapse_empty_workspace_leaf(node: &mut WorkspaceNode, pane_id: WorkspacePaneId) -> bool {
    let mut replacement = None;
    let is_empty = match node {
        WorkspaceNode::Leaf(leaf) => leaf.pane_id == pane_id && leaf.tab_group.tabs.is_empty(),
        WorkspaceNode::Split(split) => {
            if collapse_empty_workspace_leaf(&mut split.first, pane_id) {
                replacement = Some(take_workspace_node(&mut split.second));
            } else if collapse_empty_workspace_leaf(&mut split.second, pane_id) {
                replacement = Some(take_workspace_node(&mut split.first));
            }
            false
        }
    };

    if let Some(replacement) = replacement {
        *node = replacement;
        false
    } else {
        is_empty
    }
}

fn take_workspace_node(node: &mut Box<WorkspaceNode>) -> WorkspaceNode {
    let mut replacement = Box::new(workspace_dummy_node());
    std::mem::swap(node, &mut replacement);
    *replacement
}

fn workspace_dummy_node() -> WorkspaceNode {
    workspace_empty_leaf_node(WorkspacePaneId(0))
}

fn workspace_empty_leaf_node(pane_id: WorkspacePaneId) -> WorkspaceNode {
    WorkspaceNode::Leaf(WorkspaceLeaf {
        pane_id,
        tab_group: WorkspaceTabGroup {
            tabs: Vec::new(),
            active_tab: TerminalSessionId(0),
        },
    })
}

struct GpuiShellLayoutState {
    active_mode: TitlebarMode,
    shell_focus: ShellFocusTarget,
    previous_non_command_focus: Option<ShellFocusTarget>,
    pet_overlay_activities_visible: bool,
    agents_workspace: WorkspaceModel,
    command_pane: CommandPaneModel,
    command_startup_activity_restore_intents: Vec<GpuiCommandStartupActivityRestoreIntent>,
    command_delayed_send_restore_timers: Vec<GpuiCommandDelayedSendRestoreTimer>,
    project_editor_shell: ProjectEditorShellModel,
    browser_profiles: BrowserProfileModel,
    browser_tabs: BrowserTabModel,
}

impl GpuiShellLayoutState {
    fn shell_default_from_shared_settings(
        content_height: f32,
        settings: &shared_settings::SharedSidebarSettingsSnapshot,
    ) -> Self {
        Self::shell_default_with_command_default_height_px(
            content_height,
            command_pane_default_height_px_from_shared_settings(settings),
        )
    }

    fn shell_default_with_command_default_height_px(
        content_height: f32,
        command_default_height_px: f32,
    ) -> Self {
        let agents_workspace = WorkspaceModel::first_slice_default();
        let shell_focus = ShellFocusTarget::AgentsPane(agents_workspace.focused_pane);
        let browser_profiles = BrowserProfileModel::shell_default();
        let browser_tabs =
            BrowserTabModel::shell_default_with_profile(browser_profiles.active_profile_id());
        Self {
            active_mode: TitlebarMode::Agents,
            shell_focus,
            previous_non_command_focus: Some(shell_focus),
            pet_overlay_activities_visible: true,
            agents_workspace,
            command_pane: CommandPaneModel::shell_default_with_default_height_px(
                content_height,
                command_default_height_px,
            ),
            command_startup_activity_restore_intents: Vec::new(),
            command_delayed_send_restore_timers: Vec::new(),
            project_editor_shell: ProjectEditorShellModel::shell_default(),
            browser_profiles,
            browser_tabs,
        }
    }

    fn load_or_default(
        content_height: f32,
        fallback_availability: ProjectScopedWorkareaAvailability,
        settings: &shared_settings::SharedSidebarSettingsSnapshot,
    ) -> Self {
        read_json_object(&gpui_workspace_shell_state_path())
            .and_then(|object| {
                Self::from_json_object_with_shared_settings(
                    &object,
                    content_height,
                    fallback_availability,
                    settings,
                )
            })
            .unwrap_or_else(|| Self::shell_default_from_shared_settings(content_height, settings))
    }

    fn from_json_object_with_shared_settings(
        object: &serde_json::Map<String, serde_json::Value>,
        content_height: f32,
        fallback_availability: ProjectScopedWorkareaAvailability,
        settings: &shared_settings::SharedSidebarSettingsSnapshot,
    ) -> Option<Self> {
        Self::from_json_object_with_command_default_height_px(
            object,
            content_height,
            fallback_availability,
            command_pane_default_height_px_from_shared_settings(settings),
        )
    }

    fn from_json_object_with_command_default_height_px(
        object: &serde_json::Map<String, serde_json::Value>,
        content_height: f32,
        fallback_availability: ProjectScopedWorkareaAvailability,
        command_default_height_px: f32,
    ) -> Option<Self> {
        /*
        CDXC:GPUIWorkspacePersistence 2026-06-22-06:29:
        GPUI layout persistence is scoped to placeholder shell state only: titlebar mode, tab/split ids, active selections, focus/Focus mode, command pane mode/height/tree, Browser tab shell ids with sanitized URLs, project-editor companion sizing, project-editor awake/sleeping recency state, and the single `petOverlayActivitiesVisible` boolean. Do not persist pet activity payloads, titles, session/project ids, paths, raw settings JSON, terminal content, command text, stdout/stderr, user paths, project paths, tokens, cookies, secrets, raw page titles, favicon URLs, raw browser query strings, or private user content.

        CDXC:GPUIWorkspacePersistence 2026-06-22-06:29:
        Restoring corrupted or absent GPUI shell state should use the current placeholder defaults because the persisted file is optional app state. This fallback is limited to invalid state-file input and should not mask runtime errors in live layout mutation code.

        CDXC:GPUIWorkspacePersistence 2026-06-22-07:54:
        Command-pane focus restoration persists only the previous non-command focus enum and stable pane/mode id, sharing the same validation path as shellFocus so stale panes, hidden companions, and inactive project-editor modes fall back to the current mode's default surface.

        CDXC:GPUIProjectSidebarBridge 2026-06-23-08:23:
        Restored active mode coercion uses caller-supplied availability derived from the initial sidebar runtime settings snapshot, so a persisted Manage mode cannot bypass the same debuggingMode/showBetaFeatures gate that will be installed into the sidebar CEF bridge.

        CDXC:GPUIBrowserProfiles 2026-06-23-11:14:
        Restored GPUI Browser profile state is limited to generated profile ids plus the active id. Browser tabs restored from shell state receive that active generated profile id without persisting per-tab profile names, local profile directories, cookies, credentials, imported history, page titles, query strings, fragments, command text, or user browser data.

        CDXC:GPUIWorkspaceStateMigration 2026-06-23-13:04:
        Phase 10 cleanup must migrate the original unversioned GPUI shell-state shape instead of dropping safe user layout state. Accept only that known layout object shape, keep Browser profiles defaulted when the old file has no profile block, and continue rejecting unknown future versions so migration cannot become fallback parsing for arbitrary or private data.

        CDXC:GPUIWorkspaceStateMigration 2026-06-23-13:11:
        Current-version shell state must match the current writer-owned schema instead of partially defaulting missing or malformed sections. The optional state-file fallback still happens at `load_or_default`, but v1 restore itself now fails closed unless the explicit legacy migration path applies.
        */
        let restore_version = gpui_workspace_shell_state_restore_version(object)?;
        let is_legacy_unversioned =
            restore_version == GpuiWorkspaceShellStateRestoreVersion::LegacyUnversioned;
        if restore_version == GpuiWorkspaceShellStateRestoreVersion::Current
            && !gpui_workspace_shell_state_has_current_required_fields(object)
        {
            return None;
        }
        if is_legacy_unversioned && !gpui_workspace_shell_state_is_legacy_unversioned_object(object)
        {
            return None;
        }

        let persisted_active_mode =
            json_string_field(object, "activeMode").and_then(TitlebarMode::from_slug)?;
        let active_mode =
            fallback_availability.available_titlebar_mode_or_agents(persisted_active_mode);
        let agents_workspace = object
            .get("agentsWorkspace")
            .and_then(workspace_model_from_shell_state)?;
        let command_pane_value = object.get("commandPane")?;
        let command_pane = command_pane_model_from_shell_state_with_default_height_px(
            command_pane_value,
            content_height,
            command_default_height_px,
        )?;
        let command_startup_activity_restore_intents =
            command_startup_activity_restore_intents_from_shell_state(
                command_pane_value,
                &command_pane,
            );
        let command_delayed_send_restore_timers =
            command_delayed_send_restore_timers_from_shell_state(command_pane_value, &command_pane);
        let project_editor_shell = object
            .get("projectEditorShell")
            .and_then(|value| project_editor_shell_from_shell_state(value, active_mode))?;
        let browser_profiles = match object.get("browserProfiles") {
            Some(value) => browser_profile_model_from_shell_state(value)?,
            None if is_legacy_unversioned => BrowserProfileModel::shell_default(),
            None => return None,
        };
        let browser_tabs = object.get("browserTabs").and_then(|value| {
            browser_tab_model_from_shell_state(value, browser_profiles.active_profile_id())
        })?;
        let shell_focus = valid_shell_focus_or_default_with_browser_tabs(
            shell_focus_from_shell_state(object.get("shellFocus")?)?,
            active_mode,
            &agents_workspace,
            &command_pane,
            &project_editor_shell,
            &browser_tabs,
        );
        let default_non_command_focus =
            default_shell_focus_for_mode(active_mode, &agents_workspace, &project_editor_shell);
        let restored_previous_non_command_focus = match object.get("previousNonCommandFocus") {
            Some(value) if value.is_null() => None,
            Some(value) => Some(shell_focus_from_shell_state(value)?),
            None => None,
        };
        let previous_non_command_focus = restored_previous_non_command_focus
            .and_then(|focus| {
                valid_non_command_shell_focus_with_browser_tabs(
                    focus,
                    active_mode,
                    &agents_workspace,
                    &project_editor_shell,
                    &browser_tabs,
                )
            })
            .or_else(|| {
                valid_non_command_shell_focus_with_browser_tabs(
                    shell_focus,
                    active_mode,
                    &agents_workspace,
                    &project_editor_shell,
                    &browser_tabs,
                )
            })
            .or(Some(default_non_command_focus));
        let pet_overlay_activities_visible = object
            .get("petOverlayActivitiesVisible")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(true);

        Some(Self {
            active_mode,
            shell_focus,
            previous_non_command_focus,
            pet_overlay_activities_visible,
            agents_workspace,
            command_pane,
            command_startup_activity_restore_intents,
            command_delayed_send_restore_timers,
            project_editor_shell,
            browser_profiles,
            browser_tabs,
        })
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum GpuiWorkspaceShellStateRestoreVersion {
    Current,
    LegacyUnversioned,
}

fn gpui_workspace_shell_state_restore_version(
    object: &serde_json::Map<String, serde_json::Value>,
) -> Option<GpuiWorkspaceShellStateRestoreVersion> {
    if let Some(version) = object.get("version") {
        return matches!(
            version,
            serde_json::Value::Number(number)
                if number.as_u64() == Some(GPUI_WORKSPACE_SHELL_STATE_VERSION)
        )
        .then_some(GpuiWorkspaceShellStateRestoreVersion::Current);
    }

    gpui_workspace_shell_state_is_legacy_unversioned_object(object)
        .then_some(GpuiWorkspaceShellStateRestoreVersion::LegacyUnversioned)
}

fn gpui_workspace_shell_state_has_current_required_fields(
    object: &serde_json::Map<String, serde_json::Value>,
) -> bool {
    json_string_field(object, "activeMode")
        .and_then(TitlebarMode::from_slug)
        .is_some()
        && object
            .get("shellFocus")
            .is_some_and(|value| value.is_object())
        && object
            .get("previousNonCommandFocus")
            .is_some_and(|value| value.is_null() || value.is_object())
        && object
            .get("agentsWorkspace")
            .is_some_and(|value| value.is_object())
        && object
            .get("commandPane")
            .is_some_and(|value| value.is_object())
        && object
            .get("browserProfiles")
            .is_some_and(|value| value.is_object())
        && object
            .get("browserTabs")
            .is_some_and(|value| value.is_object())
        && object
            .get("projectEditorShell")
            .is_some_and(|value| value.is_object())
}

fn gpui_workspace_shell_state_is_legacy_unversioned_object(
    object: &serde_json::Map<String, serde_json::Value>,
) -> bool {
    json_string_field(object, "activeMode")
        .and_then(TitlebarMode::from_slug)
        .is_some()
        && object
            .get("shellFocus")
            .is_some_and(|value| value.is_object())
        && object
            .get("agentsWorkspace")
            .is_some_and(|value| value.is_object())
        && object
            .get("commandPane")
            .is_some_and(|value| value.is_object())
        && object
            .get("browserTabs")
            .is_some_and(|value| value.is_object())
        && object
            .get("projectEditorShell")
            .is_some_and(|value| value.is_object())
}

fn gpui_workspace_shell_state_json(app: &GhostexGpuiApp) -> serde_json::Value {
    let active_mode = app.available_titlebar_mode_or_agents(app.active_mode);
    serde_json::json!({
        "version": GPUI_WORKSPACE_SHELL_STATE_VERSION,
        "activeMode": active_mode.element_slug(),
        "shellFocus": shell_focus_to_shell_state_json(app.shell_focus),
        "previousNonCommandFocus": app
            .previous_non_command_focus
            .map(shell_focus_to_shell_state_json),
        "petOverlayActivitiesVisible": app.gpui_pet_overlay_activities_visible,
        "agentsWorkspace": workspace_model_to_shell_state_json(&app.agents_workspace),
        "commandPane": command_pane_model_to_shell_state_json_with_delayed_send_timers(
            &app.command_pane,
            &app.command_delayed_send_timers,
            SystemTime::now(),
        ),
        "browserProfiles": browser_profile_model_to_shell_state_json(&app.browser_profiles),
        "browserTabs": browser_tab_model_to_shell_state_json(&app.browser_tabs),
        "projectEditorShell": project_editor_shell_to_shell_state_json(&app.project_editor_shell),
    })
}

fn persist_gpui_workspace_shell_state(app: &GhostexGpuiApp) {
    /*
    CDXC:GPUIPrivacyAudit 2026-06-23-13:18:
    Phase 10 persistence re-audit keeps this as the only GPUI-owned workspace shell-state writer. It may write writer-owned layout/focus/tab/profile/lifecycle metadata plus the `petOverlayActivitiesVisible` UI boolean only; pet activity payloads, pet titles, pet session/project ids, raw settings JSON, terminal content, command text, stdout/stderr, project paths, file paths, raw URLs/query/fragment, page titles, profile paths, cookies, credentials, tokens, raw payloads, private user content, and runtime surface data must stay out at the serializer boundary.
    */
    let path = gpui_workspace_shell_state_path();
    if let Some(parent) = path.parent() {
        let _ = fs::create_dir_all(parent);
    }
    if let Ok(data) = serde_json::to_vec_pretty(&gpui_workspace_shell_state_json(app)) {
        let _ = fs::write(path, data);
    }
}

fn workspace_model_to_shell_state_json(model: &WorkspaceModel) -> serde_json::Value {
    /*
    CDXC:GPUIAgentsTabStatus 2026-06-22-16:27:
    Agents tab status persistence is intentionally limited to enum/boolean shell metadata so restored placeholder tabs keep their semantic dots without storing delayed-send deadlines, labels, commands, terminal output, paths, tokens, private titles, or user content.
    */
    serde_json::json!({
        "terminalSessions": model
            .terminal_sessions
            .iter()
            .map(|session| {
                serde_json::json!({
                    "id": session.id.0,
                    "presentationState": session.presentation_state.element_slug(),
                    "activity": session.activity.element_slug(),
                    "delayedSendActive": session.delayed_send_active,
                })
            })
            .collect::<Vec<_>>(),
        "root": workspace_node_to_shell_state_json(&model.root),
        "focusedPaneId": model.focused_pane.0,
        "focusModePaneId": model
            .focus_mode_pane
            .map(|pane_id| serde_json::json!(pane_id.0))
            .unwrap_or(serde_json::Value::Null),
        "nextPaneId": model.next_pane_id,
        "nextSplitId": model.next_split_id,
        "nextSessionId": model.next_session_id,
    })
}

fn workspace_node_to_shell_state_json(node: &WorkspaceNode) -> serde_json::Value {
    match node {
        WorkspaceNode::Leaf(leaf) => serde_json::json!({
            "type": "leaf",
            "paneId": leaf.pane_id.0,
            "activeSessionId": leaf.tab_group.active_tab.0,
            "tabs": leaf
                .tab_group
                .tabs
                .iter()
                .map(|tab| serde_json::json!(tab.session_id.0))
                .collect::<Vec<_>>(),
        }),
        WorkspaceNode::Split(split) => serde_json::json!({
            "type": "split",
            "splitId": split.id.0,
            "axis": split.axis.element_slug(),
            "ratio": json_number_f32(workspace_split_ratio(split.ratio)),
            "first": workspace_node_to_shell_state_json(&split.first),
            "second": workspace_node_to_shell_state_json(&split.second),
        }),
    }
}

fn workspace_model_from_shell_state(value: &serde_json::Value) -> Option<WorkspaceModel> {
    let object = value.as_object()?;
    let sessions = json_array_field(object, "terminalSessions")?
        .iter()
        .map(terminal_session_from_shell_state)
        .collect::<Option<Vec<_>>>()?;
    if has_duplicate_u64(
        &sessions
            .iter()
            .map(|session| session.id.0)
            .collect::<Vec<_>>(),
    ) {
        return None;
    }

    let session_ids = sessions
        .iter()
        .map(|session| session.id)
        .collect::<Vec<_>>();
    let root = workspace_node_from_shell_state(object.get("root")?, &session_ids)?;
    let empty_root_pane_id = workspace_empty_root_leaf_id(&root);
    let workspace_is_empty = sessions.is_empty() && empty_root_pane_id.is_some();
    /*
    CDXC:GPUIWorkspacePersistence 2026-06-26-05:23:
    The macOS workspace can close the last visible terminal and keep the project open. GPUI shell-state restore therefore accepts only the exact empty Agents root-leaf shape with zero terminal sessions, while split layouts and non-empty session lists must still reference real terminal tabs.
    */
    if sessions.is_empty() != workspace_is_empty {
        return None;
    }
    let mut pane_ids = Vec::new();
    collect_workspace_leaf_ids(&root, &mut pane_ids);
    let mut all_pane_ids = Vec::new();
    collect_workspace_all_leaf_ids(&root, &mut all_pane_ids);
    if (!workspace_is_empty && pane_ids.is_empty())
        || all_pane_ids.is_empty()
        || has_duplicate_u64(
            &all_pane_ids
                .iter()
                .map(|pane_id| pane_id.0)
                .collect::<Vec<_>>(),
        )
    {
        return None;
    }

    let mut referenced_session_ids = Vec::new();
    collect_workspace_node_session_ids(&root, &mut referenced_session_ids);
    if (!workspace_is_empty && referenced_session_ids.is_empty())
        || has_duplicate_u64(
            &referenced_session_ids
                .iter()
                .map(|session_id| session_id.0)
                .collect::<Vec<_>>(),
        )
    {
        return None;
    }

    let terminal_sessions = if workspace_is_empty {
        Vec::new()
    } else {
        sessions
            .into_iter()
            .filter(|session| referenced_session_ids.contains(&session.id))
            .collect::<Vec<_>>()
    };
    if !workspace_is_empty && terminal_sessions.is_empty() {
        return None;
    }

    let first_pane_id = pane_ids.first().copied().or(empty_root_pane_id)?;
    let focused_pane = json_u64_field(object, "focusedPaneId")
        .map(WorkspacePaneId)
        .filter(|pane_id| all_pane_ids.contains(pane_id))
        .unwrap_or(first_pane_id);
    let next_pane_id = json_u64_field(object, "nextPaneId").unwrap_or(0).max(
        all_pane_ids
            .iter()
            .map(|pane_id| pane_id.0)
            .max()
            .unwrap_or(0)
            + 1,
    );
    let mut split_ids = Vec::new();
    collect_workspace_split_ids(&root, &mut split_ids);
    if has_duplicate_u64(
        &split_ids
            .iter()
            .map(|split_id| split_id.0)
            .collect::<Vec<_>>(),
    ) {
        return None;
    }
    let next_split_id = json_u64_field(object, "nextSplitId").unwrap_or(0).max(
        split_ids
            .iter()
            .map(|split_id| split_id.0)
            .max()
            .unwrap_or(0)
            + 1,
    );
    let next_session_id = json_u64_field(object, "nextSessionId").unwrap_or(0).max(
        referenced_session_ids
            .iter()
            .map(|session_id| session_id.0)
            .max()
            .unwrap_or(0)
            + 1,
    );

    let mut model = WorkspaceModel {
        terminal_sessions,
        root,
        focused_pane,
        focus_mode_pane: None,
        next_pane_id,
        next_split_id,
        next_session_id,
    };
    if let Some(focus_mode_pane) = object
        .get("focusModePaneId")
        .and_then(json_u64_value)
        .map(WorkspacePaneId)
        .filter(|pane_id| model.find_leaf(*pane_id).is_some())
    {
        model.focus_mode_pane = Some(focus_mode_pane);
        if model.focus_mode_eligible_leaf_count() <= 1
            || !model.leaf_is_focus_mode_eligible(focus_mode_pane)
        {
            model.focus_mode_pane = None;
        }
    }
    Some(model)
}

fn terminal_session_from_shell_state(value: &serde_json::Value) -> Option<TerminalSession> {
    let object = value.as_object()?;
    let id = TerminalSessionId(json_u64_field(object, "id")?);
    if id.0 == 0 {
        return None;
    }
    let presentation_state = json_string_field(object, "presentationState")
        .and_then(TerminalSessionPresentationState::from_slug)
        .unwrap_or(TerminalSessionPresentationState::Running);
    let activity = json_string_field(object, "activity")
        .and_then(AgentTerminalActivity::from_slug)
        .unwrap_or_default();
    let delayed_send_active = json_bool_field(object, "delayedSendActive").unwrap_or(false);
    let mut session =
        TerminalSession::placeholder(id, terminal_session_title_for_id(id), presentation_state)
            .with_activity(activity)
            .with_delayed_send_active(delayed_send_active);
    if presentation_state == TerminalSessionPresentationState::Mounting {
        /*
        CDXC:GPUITerminalActivationRuntimeGuard 2026-06-23-18:00:
        Shell-state JSON intentionally stores only the visible `mounting` presentation, not whether that Mounting tab came from a new startup, failed retry, wake, materialize, or reattach action. Restored Mounting sessions therefore come back as non-startup-eligible placeholders so a pre-restart wake/reattach state cannot create a new Ghostty process or claim a parked runtime owner that no longer exists.

        CDXC:GPUITerminalActivationRuntimeGuard 2026-06-23-18:12:
        Slice 229 keeps restored `presentationState:"mounting"` out of startup eligibility at the restore boundary itself. New Mounting terminal creation and in-process failed-startup retry set eligibility through runtime-only transitions after restore, not through persisted shell state.
        */
        session.set_presentation_state_with_startup_eligibility(presentation_state, false);
    }
    Some(session)
}

fn workspace_node_from_shell_state(
    value: &serde_json::Value,
    session_ids: &[TerminalSessionId],
) -> Option<WorkspaceNode> {
    let object = value.as_object()?;
    match json_string_field(object, "type")? {
        "leaf" => {
            let pane_id = WorkspacePaneId(json_u64_field(object, "paneId")?);
            if pane_id.0 == 0 {
                return None;
            }
            let tabs = json_array_field(object, "tabs")?
                .iter()
                .map(json_u64_value)
                .collect::<Option<Vec<_>>>()?
                .into_iter()
                .map(TerminalSessionId)
                .collect::<Vec<_>>();
            if tabs.is_empty() {
                if session_ids.is_empty() {
                    return Some(WorkspaceNode::Leaf(WorkspaceLeaf {
                        pane_id,
                        tab_group: WorkspaceTabGroup {
                            tabs: Vec::new(),
                            active_tab: TerminalSessionId(0),
                        },
                    }));
                }
                return None;
            }
            if has_duplicate_u64(
                &tabs
                    .iter()
                    .map(|session_id| session_id.0)
                    .collect::<Vec<_>>(),
            ) || tabs
                .iter()
                .any(|session_id| !session_ids.contains(session_id))
            {
                return None;
            }
            let active_tab = json_u64_field(object, "activeSessionId")
                .map(TerminalSessionId)
                .filter(|session_id| tabs.contains(session_id))
                .unwrap_or(tabs[0]);
            Some(WorkspaceNode::Leaf(WorkspaceLeaf {
                pane_id,
                tab_group: WorkspaceTabGroup {
                    tabs: tabs
                        .into_iter()
                        .map(|session_id| WorkspaceTab { session_id })
                        .collect(),
                    active_tab,
                },
            }))
        }
        "split" => {
            let split_id = WorkspaceSplitId(json_u64_field(object, "splitId")?);
            if split_id.0 == 0 {
                return None;
            }
            Some(WorkspaceNode::Split(WorkspaceSplit {
                id: split_id,
                axis: json_string_field(object, "axis").and_then(WorkspaceSplitAxis::from_slug)?,
                ratio: json_f32_field(object, "ratio")
                    .map(workspace_split_ratio)
                    .unwrap_or(0.5),
                first: Box::new(workspace_node_from_shell_state(
                    object.get("first")?,
                    session_ids,
                )?),
                second: Box::new(workspace_node_from_shell_state(
                    object.get("second")?,
                    session_ids,
                )?),
            }))
        }
        _ => None,
    }
}

fn collect_workspace_node_session_ids(
    node: &WorkspaceNode,
    session_ids: &mut Vec<TerminalSessionId>,
) {
    match node {
        WorkspaceNode::Leaf(leaf) => {
            session_ids.extend(leaf.tab_group.tabs.iter().map(|tab| tab.session_id));
        }
        WorkspaceNode::Split(split) => {
            collect_workspace_node_session_ids(&split.first, session_ids);
            collect_workspace_node_session_ids(&split.second, session_ids);
        }
    }
}

fn collect_workspace_split_ids(node: &WorkspaceNode, split_ids: &mut Vec<WorkspaceSplitId>) {
    match node {
        WorkspaceNode::Leaf(_) => {}
        WorkspaceNode::Split(split) => {
            split_ids.push(split.id);
            collect_workspace_split_ids(&split.first, split_ids);
            collect_workspace_split_ids(&split.second, split_ids);
        }
    }
}

fn command_pane_model_to_shell_state_json(model: &CommandPaneModel) -> serde_json::Value {
    command_pane_model_to_shell_state_json_with_optional_delayed_send_timers(model, None, None)
}

fn command_pane_model_to_shell_state_json_with_delayed_send_timers(
    model: &CommandPaneModel,
    delayed_send_timers: &HashMap<CommandSessionId, GpuiCommandDelayedSendTimer>,
    now: SystemTime,
) -> serde_json::Value {
    command_pane_model_to_shell_state_json_with_optional_delayed_send_timers(
        model,
        Some(delayed_send_timers),
        Some(now),
    )
}

