fn terminal_session_title_for_id(id: TerminalSessionId) -> String {
    match id.0 {
        1 => "Agent".to_string(),
        2 => "Build".to_string(),
        3 => "Shell".to_string(),
        4 => "Restored".to_string(),
        5 => "Detached".to_string(),
        _ => format!("Terminal {}", id.0),
    }
}

fn command_session_title_for_id(_id: CommandSessionId) -> String {
    /*
    CDXC:GPUICommandPane 2026-06-25-11:56:
    Restored GPUI command placeholders must use the same generic `Command Terminal` fallback as newly created macOS command-pane terminals. Do not derive fallback titles from command ids or persist visible/private command titles, because shell-state JSON is layout metadata rather than command-content storage.
    */
    COMMAND_PANE_DEFAULT_SESSION_TITLE.to_string()
}

fn gpui_command_pane_sidebar_indicator_text(value: &str) -> Option<String> {
    let normalized = value.split_whitespace().collect::<Vec<_>>().join(" ");
    (!normalized.is_empty()
        && normalized.chars().count() <= GPUI_PROJECT_CONTRACT_STRING_MAX_CHARS
        && !normalized.chars().any(char::is_control))
    .then_some(normalized)
}

fn sanitize_browser_tab_url_for_state(url: &str) -> Option<String> {
    let trimmed = url.trim();
    if trimmed.is_empty() || trimmed.eq_ignore_ascii_case(BROWSER_ADDRESS_ONLY_CEF_URL) {
        return None;
    }
    let (scheme, rest) = trimmed.split_once("://")?;
    let scheme = scheme.to_ascii_lowercase();
    if scheme != "http" && scheme != "https" {
        return None;
    }
    let content_end = rest.find(['?', '#']).unwrap_or(rest.len());
    let without_query = &rest[..content_end];
    let authority_end = without_query.find('/').unwrap_or(without_query.len());
    let authority = &without_query[..authority_end];
    let path = &without_query[authority_end..];
    let authority = authority.rsplit('@').next().unwrap_or(authority).trim();
    if authority.is_empty() {
        return None;
    }
    Some(format!("{scheme}://{authority}{path}"))
}

fn browser_placeholder_safe_origin_url(sanitized_url: &str) -> Option<String> {
    let (scheme, rest) = sanitized_url.trim().split_once("://")?;
    let scheme = scheme.to_ascii_lowercase();
    if scheme != "http" && scheme != "https" {
        return None;
    }

    let authority_end = rest.find(['/', '?', '#']).unwrap_or(rest.len());
    let authority = rest[..authority_end]
        .rsplit('@')
        .next()
        .unwrap_or("")
        .trim();
    if authority.is_empty() {
        return None;
    }

    Some(format!("{scheme}://{authority}"))
}

fn project_editor_companion_width_ratio(ratio: f32) -> f32 {
    ratio.clamp(0.10, 0.85)
}

fn project_editor_companion_width_ratio_for_span(ratio: f32, content_span: f32) -> f32 {
    let content_span = content_span.max(1.0);
    let companion_min_ratio = (PROJECT_EDITOR_COMPANION_MIN_WIDTH / content_span).clamp(0.10, 0.85);
    let editor_max_ratio = ((content_span - WORKSPACE_MIN_WIDTH) / content_span).clamp(0.10, 0.85);
    let ratio = project_editor_companion_width_ratio(ratio);

    if companion_min_ratio <= editor_max_ratio {
        ratio.clamp(companion_min_ratio, editor_max_ratio)
    } else {
        companion_min_ratio
    }
}

fn json_string_field<'a>(
    object: &'a serde_json::Map<String, serde_json::Value>,
    key: &str,
) -> Option<&'a str> {
    object.get(key)?.as_str()
}

fn json_bool_field(object: &serde_json::Map<String, serde_json::Value>, key: &str) -> Option<bool> {
    object.get(key)?.as_bool()
}

fn json_array_field<'a>(
    object: &'a serde_json::Map<String, serde_json::Value>,
    key: &str,
) -> Option<&'a Vec<serde_json::Value>> {
    object.get(key)?.as_array()
}

fn json_u64_field(object: &serde_json::Map<String, serde_json::Value>, key: &str) -> Option<u64> {
    object.get(key).and_then(json_u64_value)
}

fn json_u64_value(value: &serde_json::Value) -> Option<u64> {
    match value {
        serde_json::Value::Number(number) => number.as_u64(),
        serde_json::Value::String(text) => text.parse::<u64>().ok(),
        _ => None,
    }
}

fn json_f32_field(object: &serde_json::Map<String, serde_json::Value>, key: &str) -> Option<f32> {
    object.get(key).and_then(json_value_to_f32)
}

fn json_number_f32(value: f32) -> serde_json::Value {
    serde_json::Value::Number(
        serde_json::Number::from_f64(value as f64).unwrap_or_else(|| serde_json::Number::from(0)),
    )
}

fn has_duplicate_u64(values: &[u64]) -> bool {
    values
        .iter()
        .enumerate()
        .any(|(index, value)| values.iter().skip(index + 1).any(|other| other == value))
}

fn workspace_tab_insertion_index(
    bounds: Bounds<Pixels>,
    position: gpui::Point<Pixels>,
    tab_index: usize,
) -> usize {
    let relative_x = position.x.as_f32() - bounds.origin.x.as_f32();
    let half_width = bounds.size.width.as_f32() / 2.0;

    if relative_x > half_width {
        tab_index + 1
    } else {
        tab_index
    }
}

fn workspace_pane_body_drop_zone(
    bounds: Bounds<Pixels>,
    position: gpui::Point<Pixels>,
) -> WorkspaceDropZone {
    let width = bounds.size.width.as_f32();
    let height = bounds.size.height.as_f32();
    if width <= 0.0 || height <= 0.0 {
        return WorkspaceDropZone::Center;
    }

    let x = position.x.as_f32() - bounds.origin.x.as_f32();
    let y = position.y.as_f32() - bounds.origin.y.as_f32();
    let horizontal_band = (width * WORKSPACE_DROP_EDGE_BAND_FRACTION)
        .clamp(WORKSPACE_DROP_EDGE_BAND_MIN, WORKSPACE_DROP_EDGE_BAND_MAX)
        .min(width / 2.0);
    let vertical_band = (height * WORKSPACE_DROP_EDGE_BAND_FRACTION)
        .clamp(WORKSPACE_DROP_EDGE_BAND_MIN, WORKSPACE_DROP_EDGE_BAND_MAX)
        .min(height / 2.0);

    let mut best_zone = WorkspaceDropZone::Center;
    let mut best_score = f32::INFINITY;
    let mut consider = |zone: WorkspaceDropZone, distance: f32, band: f32| {
        if band > 0.0 {
            let score = distance / band;
            if score <= 1.0 && score < best_score {
                best_score = score;
                best_zone = zone;
            }
        }
    };

    consider(WorkspaceDropZone::Left, x, horizontal_band);
    consider(WorkspaceDropZone::Right, width - x, horizontal_band);
    consider(WorkspaceDropZone::Top, y, vertical_band);
    consider(WorkspaceDropZone::Bottom, height - y, vertical_band);

    best_zone
}

fn command_pane_body_drop_zone(
    bounds: Bounds<Pixels>,
    position: gpui::Point<Pixels>,
) -> WorkspaceDropZone {
    /*
    CDXC:GPUICommandPane 2026-06-22-06:13:
    Command-pane drag/drop supports horizontal edge split intent while enforcing command-only layout rules. Left and right edge zones split command tab groups horizontally; center, top, and bottom all group into the target command group so vertical command splits are not created.

    CDXC:GPUICommandPaneDragDrop 2026-06-25-19:44:
    Native `commandPaneDropPlacement` uses only command-body horizontal geometry: widths at or below one pixel return center, local X <= 24% splits left, local X >= 76% splits right, and every vertical position stays a center group drop. Do not route through workspace pane drop math here because its min/max edge-band clamp and top/bottom competition are workspace-only behavior.
    */
    let width = bounds.size.width.as_f32();
    if !width.is_finite() || width <= 1.0 {
        return WorkspaceDropZone::Center;
    }

    let local_x = (position.x.as_f32() - bounds.origin.x.as_f32()) / width;
    if local_x <= COMMAND_PANE_BODY_DROP_EDGE_BAND_FRACTION {
        return WorkspaceDropZone::Left;
    }
    if local_x >= 1.0 - COMMAND_PANE_BODY_DROP_EDGE_BAND_FRACTION {
        return WorkspaceDropZone::Right;
    }
    WorkspaceDropZone::Center
}

