    fn refresh_gpui_remote_gxserver_presentation_in_background(
        &mut self,
        remote_machine_id: String,
        mark_failed_on_error: bool,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(target) = self.gpui_remote_gxserver_request_target(&remote_machine_id) else {
            return;
        };
        let refresh_stream_generation = self
            .remote_gxserver_connections
            .get(&remote_machine_id)
            .and_then(|connection| connection.presentation_stream_generation);
        let background = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let result = background
                .spawn(async move {
                    gpui_remote_gxserver_rpc_result(
                        &target,
                        "/api/readPresentationSnapshot",
                        &serde_json::json!({}),
                        Duration::from_secs(15),
                    )
                })
                .await;
            let _ = this.update(cx, |this, cx| {
                if !refresh_stream_generation.is_some_and(|generation| {
                    !this.gpui_remote_gxserver_presentation_stream_is_current(
                        remote_machine_id.as_str(),
                        generation,
                    )
                }) {
                    match result {
                        Ok(result) => {
                            if let Some(snapshot) = result.get("snapshot").cloned() {
                                this.dispatch_gpui_sidebar_remote_event(
                                    serde_json::json!({
                                        "payload": {
                                            "snapshot": snapshot,
                                            "type": "presentationSnapshot",
                                        },
                                        "remoteMachineId": remote_machine_id.as_str(),
                                        "type": "remoteGxserverPresentation",
                                    }),
                                    cx,
                                );
                            } else if mark_failed_on_error {
                                this.dispatch_gpui_remote_machine_status(
                                    remote_machine_id.as_str(),
                                    "failed",
                                    cx,
                                );
                            }
                        }
                        Err(_) if mark_failed_on_error => {
                            this.dispatch_gpui_remote_machine_status(
                                remote_machine_id.as_str(),
                                "failed",
                                cx,
                            );
                        }
                        Err(_) => {}
                    }
                }
            });
        })
        .detach();
    }

    fn next_gpui_remote_gxserver_presentation_stream_generation(&mut self) -> u64 {
        self.remote_gxserver_presentation_stream_generation = self
            .remote_gxserver_presentation_stream_generation
            .wrapping_add(1);
        if self.remote_gxserver_presentation_stream_generation == 0 {
            self.remote_gxserver_presentation_stream_generation = 1;
        }
        self.remote_gxserver_presentation_stream_generation
    }

    fn gpui_remote_gxserver_presentation_stream_is_current(
        &self,
        remote_machine_id: &str,
        generation: u64,
    ) -> bool {
        self.remote_gxserver_connections
            .get(remote_machine_id)
            .and_then(|connection| connection.presentation_stream_generation)
            == Some(generation)
    }

    fn start_gpui_remote_gxserver_presentation_stream(
        &mut self,
        remote_machine_id: String,
        target: GpuiRemoteGxserverRequestTarget,
        generation: u64,
        cancel: Arc<AtomicBool>,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUIRemotePresentationStreaming 2026-06-24-19:54:
        A connected remote machine needs the same live gxserver presentation contract as local GPUI, but CEF must not receive remote base URLs or bearer tokens. Rust opens `/api/events` through the localhost SSH tunnel, subscribes with the shared sidebar client id, forwards only sanitized snapshot/delta payloads, and fails the machine after bounded reconnect attempts instead of fabricating state.
        */
        let (tx, mut rx) = mpsc::unbounded::<GpuiRemoteGxserverPresentationStreamMessage>();
        let background = cx.background_executor().clone();
        background
            .spawn(async move {
                gpui_remote_gxserver_presentation_stream_loop(target, cancel, tx);
            })
            .detach();
        cx.spawn(async move |this, cx| {
            while let Some(message) = rx.next().await {
                let should_continue = this
                    .update(cx, |this, cx| {
                        if !this.gpui_remote_gxserver_presentation_stream_is_current(
                            remote_machine_id.as_str(),
                            generation,
                        ) {
                            return false;
                        }
                        match message {
                            GpuiRemoteGxserverPresentationStreamMessage::Event(payload) => {
                                this.dispatch_gpui_sidebar_remote_event(
                                    serde_json::json!({
                                        "payload": payload,
                                        "remoteMachineId": remote_machine_id.as_str(),
                                        "type": "remoteGxserverPresentation",
                                    }),
                                    cx,
                                );
                                true
                            }
                            GpuiRemoteGxserverPresentationStreamMessage::Failed => {
                                this.stop_gpui_remote_gxserver_connection(
                                    remote_machine_id.as_str(),
                                );
                                this.dispatch_gpui_remote_machine_status(
                                    remote_machine_id.as_str(),
                                    "failed",
                                    cx,
                                );
                                false
                            }
                        }
                    })
                    .unwrap_or(false);
                if !should_continue {
                    break;
                }
            }
        })
        .detach();
    }

    fn stop_gpui_remote_gxserver_connection(&mut self, remote_machine_id: &str) {
        if let Some(mut connection) = self.remote_gxserver_connections.remove(remote_machine_id) {
            connection.terminate();
        }
    }

    fn stop_all_gpui_remote_gxserver_connections(&mut self) {
        for (_, mut connection) in self.remote_gxserver_connections.drain() {
            connection.terminate();
        }
    }

    fn sync_gpui_ghostty_config_file_after_settings_save(
        &mut self,
        ghostty_config_backed_settings_changed: bool,
        settings_snapshot: &shared_settings::SharedSidebarSettingsSnapshot,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUISettingsGhosttyConfig 2026-06-24-12:24:
        Normal GPUI `updateSettings` saves should write generated Ghostty managed terminal settings only when a config-backed terminal value changed. The current GPUI GhosttyKit wrapper has load/create surface FFI but no safe live reload/update API, so this write affects Ghostty's config file, external Ghostty reloads, and future/recreated GPUI surfaces without claiming live embedded terminal reload.
        */
        if !ghostty_config_backed_settings_changed {
            return;
        }
        if shared_settings::write_ghostty_terminal_config_from_settings_object(
            settings_snapshot.object(),
        )
        .is_ok()
        {
            return;
        }
        let message = "Settings were saved, but GPUI could not write the managed Ghostty config file. Existing embedded terminals were not live reloaded.";
        self.dispatch_gpui_settings_action_status("ghosttySettings", false, message, cx);
        self.dispatch_gpui_app_modal_toast(
            "warning",
            "Could not update Ghostty config",
            message,
            cx,
        );
    }

    fn sync_gpui_gxserver_agent_settings_after_save(
        &mut self,
        previous_agent_settings: shared_settings::SharedGxserverAgentSettings,
        next_agent_settings: shared_settings::SharedGxserverAgentSettings,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUISettingsGxserverAgentPolicy 2026-06-24-11:39:
        GPUI matches macOS for agent launch policy: shared Settings is the local render cache, while local gxserver owns inherited Accept All and Default Prompt Agent behavior for launchers across clients. After a successful Settings save, post the current two gxserver-owned values only when either changed, and keep token/network/parser failures silent so unavailable gxserver never creates fake daemon state or rolls back the saved local cache.
        */
        if previous_agent_settings == next_agent_settings {
            return;
        }

        let background = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let canonical_agent_settings = background
                .spawn(async move { update_gpui_gxserver_agent_settings(&next_agent_settings) })
                .await
                .ok();
            let Some(canonical_agent_settings) = canonical_agent_settings else {
                return;
            };
            let _ = this.update(cx, |this, cx| {
                this.apply_gpui_gxserver_agent_settings_to_local_settings(
                    canonical_agent_settings,
                    cx,
                );
            });
        })
        .detach();
    }

    fn reconcile_gpui_gxserver_agent_settings_in_background(
        &mut self,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUISettingsGxserverAgentPolicy 2026-06-24-12:14:
        GPUI startup/open-time hydration must match macOS migration semantics for gxserver-owned agent policy. Read `/api/readAgentSettings`; if gxserver has no persisted row, seed it once from current shared Settings, otherwise treat daemon values as canonical and refresh the local render cache through the central settings service without logging tokens, response bodies, paths, commands, or user content.
        */
        if self.gxserver_agent_settings_reconciliation_in_flight {
            return;
        }
        self.gxserver_agent_settings_reconciliation_in_flight = true;

        let background = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let hydration_result = background
                .spawn(async move { reconcile_gpui_gxserver_agent_settings_with_daemon() })
                .await
                .ok()
                .flatten();
            let _ = this.update(cx, |this, cx| {
                this.gxserver_agent_settings_reconciliation_in_flight = false;
                if let Some(hydration_result) = hydration_result {
                    this.apply_gpui_gxserver_agent_settings_hydration_result(hydration_result, cx);
                }
            });
        })
        .detach();
    }

    fn gpui_app_modal_sidebar_state_message_for_open(
        &mut self,
        modal: GpuiAppModalKind,
        cx: &mut gpui::Context<Self>,
    ) -> serde_json::Value {
        /*
        CDXC:GPUISettingsEntryModals 2026-06-24-12:22:
        Any shared Settings entry point can show agent-owned controls after the React host selects its initial tab. Reconcile gxserver-owned agent policy before hydrating Settings, Hotkeys, Configure Agents, Configure Actions, and Open Targets so entry-specific modal ids do not drift from the canonical Settings route.
        */
        if modal.is_settings_modal_entry() {
            self.reconcile_gpui_gxserver_agent_settings_in_background(cx);
        }
        self.gpui_app_modal_sidebar_state_message()
    }

    fn gpui_app_modal_sidebar_state_message(&self) -> serde_json::Value {
        self.with_gpui_command_pane_sidebar_indicators(gpui_app_modal_sidebar_state_message(
            self.latest_sidebar_project_snapshot.as_ref(),
        ))
    }

    fn gpui_app_modal_sidebar_state_message_from_settings_snapshot(
        &self,
        settings_snapshot: &shared_settings::SharedSidebarSettingsSnapshot,
    ) -> serde_json::Value {
        self.with_gpui_command_pane_sidebar_indicators(
            gpui_app_modal_sidebar_state_message_from_settings_snapshot(
                settings_snapshot,
                self.latest_sidebar_project_snapshot.as_ref(),
            ),
        )
    }

    fn with_gpui_command_pane_sidebar_indicators(
        &self,
        mut message: serde_json::Value,
    ) -> serde_json::Value {
        /*
        CDXC:GPUICommandPane 2026-06-25-10:50:
        App-modal sidebar hydrates must carry the same command-session indicators as the live GPUI sidebar HUD. Reuse the sanitized command-pane summary and gxserver command rows; never compute from command text, paths, status-file paths, terminal output, logs, or persisted shell-state JSON.
        */
        let commands = message
            .get("hud")
            .and_then(|hud| hud.get("commands"))
            .cloned()
            .unwrap_or_else(|| serde_json::Value::Array(Vec::new()));
        let sessions = self.command_pane.sidebar_command_session_sources(
            self.shell_focus == ShellFocusTarget::CommandPane,
            &self.command_delayed_send_timers,
            &self.command_close_after_done_timers,
            SystemTime::now(),
        );
        message["hud"]["commandSessionIndicators"] =
            gpui_sidebar_command_session_indicators_from_command_pane_sources(&commands, &sessions);
        message
    }

    fn apply_gpui_gxserver_agent_settings_hydration_result(
        &mut self,
        hydration_result: GpuiGxserverAgentSettingsHydrationResult,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUISettingsGxserverAgentPolicy 2026-06-24-12:14:
        Startup/open hydration may finish after the user saves Settings. Apply daemon canonical values only if the shared render cache still matches the local values used for the read/seed decision; a newer save uses the existing save-time gxserver sync path instead of being overwritten by a stale startup response.
        */
        if shared_settings::shared_sidebar_settings_snapshot().gxserver_agent_settings()
            != hydration_result.expected_local_settings
        {
            return;
        }
        self.apply_gpui_gxserver_agent_settings_to_local_settings(
            hydration_result.canonical_settings,
            cx,
        );
    }

    fn apply_gpui_gxserver_agent_settings_to_local_settings(
        &mut self,
        canonical_agent_settings: shared_settings::SharedGxserverAgentSettings,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUISettingsGxserverAgentPolicy 2026-06-24-11:39:
        gxserver read/update responses are canonical for inherited agent launch policy. If the daemon reports either agent setting differently than the current GPUI render cache, persist those canonical values through the central shared Settings service and refresh the modal/sidebar runtime state again instead of writing a separate cache or logging private daemon details.
        */
        let latest_settings_snapshot = shared_settings::shared_sidebar_settings_snapshot();
        if latest_settings_snapshot.gxserver_agent_settings() == canonical_agent_settings {
            return;
        }

        let mut settings_object = latest_settings_snapshot.object().clone();
        canonical_agent_settings.write_to_settings_object(&mut settings_object);
        let Ok(write_result) =
            shared_settings::write_shared_sidebar_settings_object(settings_object)
        else {
            return;
        };
        self.refresh_gpui_shared_settings_consumers_after_save(&write_result.snapshot, cx);
    }

    fn refresh_gpui_shared_settings_consumers_after_save(
        &mut self,
        settings_snapshot: &shared_settings::SharedSidebarSettingsSnapshot,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUISettingsPersistence 2026-06-24-11:19:
        After a successful Settings save or gxserver startup/open canonical sync, GPUI refreshes only the settings-dependent runtime state it owns today: app-modal hydrate/sidebarState, sidebar debug/beta booleans through the existing CEF runtime-settings path, Manage availability fallback and CEF visibility, project-editor auto-sleep scheduling, supported embedded Ghostty request-map settings, gxserver-owned agent-policy reconciliation, and central-service render reads such as the Browser feedback/profile toolbar controls. This is not full settings fan-out; many action bridges, code-server sync, live Ghostty config reloads, and broad future side effects remain outside this path.
        */
        self.reschedule_project_editor_auto_sleep_if_policy_changed_from_shared_settings(
            settings_snapshot,
            cx,
        );
        self.apply_gpui_sidebar_side_from_saved_settings(settings_snapshot);
        self.refresh_sidebar_runtime_settings_from_shared_settings(settings_snapshot, cx);
        #[cfg(target_os = "macos")]
        self.refresh_terminal_ghostty_surface_config_requests_from_shared_settings(
            settings_snapshot,
        );
        let sidebar_state_message =
            self.gpui_app_modal_sidebar_state_message_from_settings_snapshot(settings_snapshot);
        self.refresh_open_gpui_app_modal_sidebar_state(sidebar_state_message, cx);
        // Newly saved hotkey chords bind immediately (later bindings win
        // conflicts). Chords removed or remapped away stay registered until
        // relaunch: clearing the keymap would also drop gpui-component's own
        // bindings, so a full rebuild is not safe here.
        cx.bind_keys(gpui_configured_hotkey_key_bindings_from_settings());
        cx.notify();
    }

    #[cfg(target_os = "macos")]
    fn refresh_terminal_ghostty_surface_config_requests_from_shared_settings(
        &mut self,
        settings_snapshot: &shared_settings::SharedSidebarSettingsSnapshot,
    ) {
        /*
        CDXC:GPUITerminalSettings 2026-06-24-11:27:
        `updateSettings` fan-out refreshes the GPUI-owned Ghostty request maps so subsequent Agents, command, and startup surface creations use the saved supported terminal settings. Existing live Ghostty surfaces are not reloaded here because this runtime path does not yet expose a safe config-reload/apply contract; do not fake reload by dropping running terminals or logging raw settings.
        */
        let terminal_config =
            gpui_terminal_ghostty_surface_config_from_shared_settings(settings_snapshot);
        for request in self
            .agents_terminal_ghostty_surface_config_requests
            .values_mut()
        {
            request.set_terminal_config(terminal_config);
        }
        for request in self
            .command_terminal_ghostty_surface_config_requests
            .values_mut()
        {
            request.set_terminal_config(terminal_config);
        }
        for request in self
            .agents_terminal_startup_ghostty_surface_config_requests
            .values_mut()
        {
            request.set_terminal_config(terminal_config);
        }
    }

    fn refresh_open_gpui_app_modal_sidebar_state(
        &mut self,
        sidebar_state_message: serde_json::Value,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(handle) = self.app_modal_window.clone() else {
            return;
        };
        let update_result = handle.update(cx, |host, modal_window, cx| {
            host.refresh_sidebar_state_message(sidebar_state_message.clone(), cx);
            modal_window.refresh();
        });
        if update_result.is_err() {
            self.clear_lost_gpui_app_modal_window_handle();
        }
    }

    fn dispatch_open_gpui_app_modal_sidebar_state_payload(
        &mut self,
        payload: serde_json::Value,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUISettingsStatusBridge 2026-06-24-11:36:
        Settings status/action responses are transient `sidebarState` messages to the shared React modal host. They must clear modal loading states without replacing the stored full hydrate snapshot used when the app-modal host becomes ready or a Settings save rehydrates the modal.
        */
        let Some(handle) = self.app_modal_window.clone() else {
            return;
        };
        let update_result = handle.update(cx, |host, modal_window, cx| {
            host.dispatch_transient_sidebar_state_message(payload, cx);
            modal_window.refresh();
        });
        if update_result.is_err() {
            self.clear_lost_gpui_app_modal_window_handle();
        }
    }

    fn dispatch_gpui_titlebar_tips_project_state_update(
        &mut self,
        project_state_update: serde_json::Value,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(panel) = self.titlebar_tips_panel.clone() else {
            return;
        };
        panel.update(cx, |panel, cx| {
            panel.dispatch_project_state_update(project_state_update.clone(), cx);
        });
    }

    fn dispatch_gpui_titlebar_tips_sidebar_state_payload(
        &mut self,
        payload: &serde_json::Value,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(project_state_update) =
            gpui_titlebar_project_state_update_from_sidebar_state_payload(payload)
        else {
            return;
        };
        self.dispatch_gpui_titlebar_tips_project_state_update(project_state_update, cx);
    }

    fn dispatch_open_gpui_app_modal_message(
        &mut self,
        message: serde_json::Value,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(handle) = self.app_modal_window.clone() else {
            return;
        };
        let update_result = handle.update(cx, |host, modal_window, cx| {
            host.dispatch_transient_message(message.clone(), cx);
            modal_window.refresh();
        });
        if update_result.is_err() {
            self.clear_lost_gpui_app_modal_window_handle();
        }
    }

    fn dispatch_gpui_app_modal_toast(
        &mut self,
        level: &str,
        title: &str,
        description: &str,
        cx: &mut gpui::Context<Self>,
    ) {
        self.dispatch_open_gpui_app_modal_message(
            serde_json::json!({
                "description": description,
                "level": level,
                "title": title,
                "type": "toast",
            }),
            cx,
        );
    }

    /// App toasts from the sidebar bridge (git/worktree/sync/clone progress)
    /// render in a dedicated bottom-center popup window, mirroring the macOS
    /// native toast panels. An in-window layer cannot work here: the workspace
    /// area is covered by native Ghostty/CEF child views that draw above all
    /// GPUI content.
    fn receive_gpui_app_toast_bridge_message(
        &mut self,
        message: &serde_json::Value,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        self.app_toast_id_counter = self.app_toast_id_counter.wrapping_add(1);
        let generated_id = format!("gpui-app-toast-{}", self.app_toast_id_counter);
        let Some(toast) = gpui_app_toast_from_bridge_message(message, generated_id) else {
            return;
        };
        self.upsert_gpui_app_toast(toast, window, cx);
    }

    fn upsert_gpui_app_toast(
        &mut self,
        mut toast: GpuiAppToast,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        let main_window_bounds = window.bounds();
        self.app_toast_anchor = Some(point(
            main_window_bounds.origin.x + main_window_bounds.size.width / 2.0,
            main_window_bounds.origin.y + main_window_bounds.size.height,
        ));
        self.app_toast_epoch = self.app_toast_epoch.wrapping_add(1);
        toast.epoch = self.app_toast_epoch;
        let auto_dismiss =
            (!toast.persistent).then(|| (toast.id.clone(), toast.epoch, toast.duration_ms));
        if let Some(existing) = self
            .app_toasts
            .iter_mut()
            .find(|existing| existing.id == toast.id)
        {
            *existing = toast;
        } else {
            self.app_toasts.push(toast);
            while self.app_toasts.len() > GPUI_APP_TOAST_MAX_VISIBLE {
                self.app_toasts.remove(0);
            }
        }
        if let Some((toast_id, epoch, duration_ms)) = auto_dismiss {
            self.schedule_gpui_app_toast_auto_dismiss(toast_id, epoch, duration_ms, cx);
        }
        self.sync_gpui_app_toast_window(cx);
    }

    fn show_gpui_gxserver_bootstrap_toast(
        &mut self,
        level: &str,
        title: &str,
        description: &str,
        persistent: bool,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        self.upsert_gpui_app_toast(
            GpuiAppToast {
                id: GPUI_GXSERVER_DAEMON_TOAST_ID.to_string(),
                level: GpuiAppToastLevel::from_raw(Some(level)),
                title: title.to_string(),
                description: (!description.is_empty()).then(|| description.to_string()),
                persistent,
                duration_ms: GPUI_APP_TOAST_DEFAULT_DURATION_MS,
                epoch: 0,
            },
            window,
            cx,
        );
    }

    /// Starts the loopback CLI bridge (port 58743 + per-launch token file)
    /// that the installed `ghostex` CLI's Ctrl+G prompt-editor flow connects
    /// to. On bind failure — usually the macOS Ghostex app already owning the
    /// port — GPUI surfaces one honest toast and stays without a bridge; the
    /// CLI then keeps using the machine editor because Monaco capability is
    /// only advertised at attach while the bridge is running.
    fn start_gpui_cli_bridge_server(&mut self, cx: &mut gpui::Context<Self>) {
        let (tx, mut rx) =
            mpsc::unbounded::<cli_bridge::GpuiCliBridgeOpenFloatingEditorCommand>();
        if cli_bridge::start_gpui_cli_bridge_server(ghostex_home_root().join("cli"), tx).is_err() {
            cx.spawn(async move |this, cx| {
                let _ = this.update_in(cx, |this, window, cx| {
                    this.upsert_gpui_app_toast(
                        GpuiAppToast {
                            id: "gpui-cli-bridge-unavailable".to_string(),
                            level: GpuiAppToastLevel::from_raw(Some("warning")),
                            title: "Ghostex CLI bridge unavailable".to_string(),
                            description: Some(
                                "Another Ghostex app may already own the CLI bridge port. Ctrl+G prompt editing uses the terminal editor while this app has no bridge."
                                    .to_string(),
                            ),
                            persistent: false,
                            duration_ms: GPUI_APP_TOAST_DEFAULT_DURATION_MS,
                            epoch: 0,
                        },
                        window,
                        cx,
                    );
                });
            })
            .detach();
            return;
        }
        cx.spawn(async move |this, cx| {
            while let Some(command) = rx.next().await {
                let _ = this.update(cx, |this, cx| {
                    this.receive_gpui_cli_bridge_open_floating_editor(command, cx);
                });
            }
        })
        .detach();
    }

    /// GPUI port of the macOS sidebar-mount first-run block
    /// (`openTipsAndTricksOnFirstLaunch` + `showOSIntegrationOnboardingOnFirstLaunch`,
    /// native-sidebar.tsx): current shipped macOS consumes the legacy tips and
    /// Highlighted Features markers WITHOUT opening those surfaces (the
    /// Discover→firstLaunchSetup auto chain was superseded 2026-06-18), opens
    /// the tutorial video modal once per first-launch-setup revision, and shows
    /// a once-forever OS Integration toast.
    fn start_gpui_first_run_onboarding(&mut self, cx: &mut gpui::Context<Self>) {
        let active_project_id = self.gpui_app_modal_active_project_id();
        let background = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let (show_os_integration_toast, tutorial_video_sidebar_state) = background
                .spawn(async move {
                    let mut state = load_gpui_first_run_onboarding_state();
                    let mut changed = false;
                    if !state.tips_and_tricks_seen {
                        state.tips_and_tricks_seen = true;
                        changed = true;
                    }
                    if state.highlighted_features_seen_revision.as_deref()
                        != Some(GPUI_HIGHLIGHTED_FEATURES_SEEN_REVISION)
                    {
                        state.highlighted_features_seen_revision =
                            Some(GPUI_HIGHLIGHTED_FEATURES_SEEN_REVISION.to_string());
                        changed = true;
                    }
                    let open_tutorial_video = state.first_launch_setup_seen_revision.as_deref()
                        != Some(GPUI_FIRST_LAUNCH_SETUP_SEEN_REVISION);
                    if open_tutorial_video {
                        state.first_launch_setup_seen_revision =
                            Some(GPUI_FIRST_LAUNCH_SETUP_SEEN_REVISION.to_string());
                        changed = true;
                    }
                    let show_os_integration_toast = !state.os_integration_onboarding_seen;
                    if show_os_integration_toast {
                        state.os_integration_onboarding_seen = true;
                        changed = true;
                    }
                    if changed {
                        persist_gpui_first_run_onboarding_state(&state);
                    }
                    let tutorial_video_sidebar_state = open_tutorial_video.then(|| {
                        gpui_app_modal_sidebar_state_message_for_active_project_id(
                            active_project_id.as_deref(),
                        )
                    });
                    (show_os_integration_toast, tutorial_video_sidebar_state)
                })
                .await;
            if !show_os_integration_toast && tutorial_video_sidebar_state.is_none() {
                return;
            }
            let _ = this.update_in(cx, |this, window, cx| {
                if show_os_integration_toast {
                    this.upsert_gpui_app_toast(
                        GpuiAppToast {
                            id: "gpui-os-integration-onboarding".to_string(),
                            level: GpuiAppToastLevel::from_raw(Some("info")),
                            title: "OS Integration available".to_string(),
                            description: Some(
                                "Open Settings > OS Integration to set Ghostex as your editor or terminal target."
                                    .to_string(),
                            ),
                            persistent: false,
                            duration_ms: GPUI_APP_TOAST_DEFAULT_DURATION_MS,
                            epoch: 0,
                        },
                        window,
                        cx,
                    );
                }
                if let Some(base_sidebar_state) = tutorial_video_sidebar_state {
                    let modal = GpuiAppModalKind::WatchGhostexVideo;
                    let sidebar_state_message =
                        this.with_gpui_command_pane_sidebar_indicators(base_sidebar_state);
                    this.open_gpui_app_modal_window(
                        modal,
                        modal.open_message(),
                        sidebar_state_message,
                        None,
                        cx,
                    );
                }
            });
        })
        .detach();
    }

    /// Startup daemon bootstrap, mirroring the macOS GxserverClient contract:
    /// reuse a healthy protocol-matched daemon silently, surface protocol and
    /// toolchain problems honestly, and otherwise launch the bundled daemon
    /// (app-independent; quitting Ghostex never stops it) while a persistent
    /// status toast tracks progress. Unlike macOS this does not gate window
    /// creation; the shell shows its normal disconnected state until healthy.
    fn start_gpui_local_gxserver_bootstrap(&mut self, cx: &mut gpui::Context<Self>) {
        cx.spawn(async move |this, cx| {
            let health = cx
                .background_executor()
                .spawn(async { gpui_probe_local_gxserver_health() })
                .await;
            match health {
                GpuiLocalGxserverHealthState::Healthy {
                    tools_available: true,
                } => {
                    let _ = this.update(cx, |this, cx| {
                        this.start_gpui_portless_setup_prompt_check(cx);
                    });
                    return;
                }
                GpuiLocalGxserverHealthState::Healthy {
                    tools_available: false,
                } => {
                    let _ = this.update_in(cx, |this, window, cx| {
                        this.show_gpui_gxserver_bootstrap_toast(
                            "warning",
                            "gxserver toolchain unavailable",
                            "gxserver is running, but its bundled zmx/zehn/bd tools are unavailable. Restart gxserver from the current Ghostex build.",
                            true,
                            window,
                            cx,
                        );
                        this.start_gpui_portless_setup_prompt_check(cx);
                    });
                    return;
                }
                GpuiLocalGxserverHealthState::ProtocolMismatch { reported } => {
                    let message = gpui_gxserver_protocol_mismatch_message(reported);
                    let _ = this.update_in(cx, |this, window, cx| {
                        this.show_gpui_gxserver_bootstrap_toast(
                            "error",
                            "gxserver protocol mismatch",
                            &message,
                            true,
                            window,
                            cx,
                        );
                    });
                    return;
                }
                GpuiLocalGxserverHealthState::Unreachable => {}
            }

            let Some(binary) = gpui_resolve_local_gxserver_binary() else {
                let _ = this.update_in(cx, |this, window, cx| {
                    this.show_gpui_gxserver_bootstrap_toast(
                        "error",
                        "gxserver unavailable",
                        "Bundled gxserver binary is missing. Run `bun run build` for development, or reinstall Ghostex so Web/gxserver is present.",
                        true,
                        window,
                        cx,
                    );
                });
                return;
            };
            let _ = this.update_in(cx, |this, window, cx| {
                this.show_gpui_gxserver_bootstrap_toast(
                    "info",
                    "Starting gxserver",
                    "Checking local daemon status.",
                    true,
                    window,
                    cx,
                );
            });
            let spawn_result = cx
                .background_executor()
                .spawn(async move { gpui_spawn_local_gxserver_daemon(&binary) })
                .await;
            if let Err(message) = spawn_result {
                let _ = this.update_in(cx, |this, window, cx| {
                    this.show_gpui_gxserver_bootstrap_toast(
                        "error",
                        "gxserver failed",
                        &message,
                        true,
                        window,
                        cx,
                    );
                });
                return;
            }
            for _ in 0..40 {
                cx.background_executor()
                    .timer(Duration::from_millis(500))
                    .await;
                let health = cx
                    .background_executor()
                    .spawn(async { gpui_probe_local_gxserver_health() })
                    .await;
                match health {
                    GpuiLocalGxserverHealthState::Healthy { tools_available } => {
                        let _ = this.update_in(cx, |this, window, cx| {
                            this.remove_gpui_app_toast(GPUI_GXSERVER_DAEMON_TOAST_ID, cx);
                            if !tools_available {
                                this.show_gpui_gxserver_bootstrap_toast(
                                    "warning",
                                    "gxserver toolchain unavailable",
                                    "gxserver is running, but its bundled zmx/zehn/bd tools are unavailable. Restart gxserver from the current Ghostex build.",
                                    true,
                                    window,
                                    cx,
                                );
                            }
                            let _ = this.refresh_sidebar_gxserver_bootstrap_if_changed(cx);
                            this.start_gpui_portless_setup_prompt_check(cx);
                        });
                        return;
                    }
                    GpuiLocalGxserverHealthState::ProtocolMismatch { reported } => {
                        let message = gpui_gxserver_protocol_mismatch_message(reported);
                        let _ = this.update_in(cx, |this, window, cx| {
                            this.show_gpui_gxserver_bootstrap_toast(
                                "error",
                                "gxserver protocol mismatch",
                                &message,
                                true,
                                window,
                                cx,
                            );
                        });
                        return;
                    }
                    GpuiLocalGxserverHealthState::Unreachable => {}
                }
            }
            let launch_output = cx
                .background_executor()
                .spawn(async { gpui_recent_gxserver_launch_output() })
                .await;
            let description = launch_output
                .unwrap_or_else(|| "The daemon did not become healthy in time.".to_string());
            let _ = this.update_in(cx, |this, window, cx| {
                this.show_gpui_gxserver_bootstrap_toast(
                    "error",
                    "gxserver failed to start",
                    &description,
                    true,
                    window,
                    cx,
                );
            });
        })
        .detach();
    }

    fn start_gpui_workspace_open_target_availability_scan(&mut self, cx: &mut gpui::Context<Self>) {
        // macOS detects installed Open In targets once when the native sidebar
        // starts (refreshWorkspaceOpenTargetAvailabilityAtStartup) and persists
        // the result into workspaceOpenTargetAvailability; the manual titlebar
        // refresh command exists in the host protocol but has no live sender in
        // shipped macOS, so the startup scan is the whole parity surface.
        cx.spawn(async move |this, cx| {
            let detected = cx
                .background_executor()
                .spawn(async { gpui_detect_workspace_open_target_availability() })
                .await;
            let Some(detected) = detected else {
                return;
            };
            let _ = this.update(cx, |this, cx| {
                this.apply_gpui_workspace_open_target_availability_scan(detected, cx);
            });
        })
        .detach();
    }

    fn apply_gpui_workspace_open_target_availability_scan(
        &mut self,
        detected: GpuiDetectedOpenTargetAvailability,
        cx: &mut gpui::Context<Self>,
    ) {
        let mut settings_object = shared_settings::shared_sidebar_settings_snapshot()
            .object()
            .clone();
        let stored =
            gpui_open_target_availability(settings_object.get("workspaceOpenTargetAvailability"));
        if gpui_detected_open_target_availability_matches_stored(&detected, &stored) {
            return;
        }
        settings_object.insert(
            "workspaceOpenTargetAvailability".to_string(),
            gpui_workspace_open_target_availability_settings_value(&detected),
        );
        let Ok(write_result) =
            shared_settings::write_shared_sidebar_settings_object(settings_object)
        else {
            return;
        };
        self.refresh_gpui_shared_settings_consumers_after_save(&write_result.snapshot, cx);
    }

    fn schedule_gpui_app_toast_auto_dismiss(
        &mut self,
        toast_id: String,
        epoch: u64,
        duration_ms: u64,
        cx: &mut gpui::Context<Self>,
    ) {
        cx.spawn(async move |this, cx| {
            cx.background_executor()
                .timer(std::time::Duration::from_millis(duration_ms))
                .await;
            let _ = this.update(cx, |this, cx| {
                // The epoch guard keeps an update-in-place (same toastId) from
                // being dismissed by the superseded toast's timer.
                if this
                    .app_toasts
                    .iter()
                    .any(|toast| toast.id == toast_id && toast.epoch == epoch)
                {
                    this.remove_gpui_app_toast(&toast_id, cx);
                }
            });
        })
        .detach();
    }

    fn remove_gpui_app_toast(&mut self, toast_id: &str, cx: &mut gpui::Context<Self>) {
        let previous_len = self.app_toasts.len();
        self.app_toasts.retain(|toast| toast.id != toast_id);
        if self.app_toasts.len() != previous_len {
            self.sync_gpui_app_toast_window(cx);
        }
    }

    fn sync_gpui_app_toast_window(&mut self, cx: &mut gpui::Context<Self>) {
        if self.app_toasts.is_empty() {
            self.app_toast_window_height = px(0.0);
            if let Some(handle) = self.app_toast_window.take() {
                let _ = handle.update(cx, |_, toast_window, _| {
                    toast_window.remove_window();
                });
            }
            return;
        }
        let Some(anchor) = self.app_toast_anchor else {
            return;
        };
        let stack_height = px(gpui_app_toast_stack_height(&self.app_toasts));
        let toasts = self.app_toasts.clone();
        if let Some(handle) = self.app_toast_window.clone() {
            if self.app_toast_window_height == stack_height {
                let update_result = handle.update(cx, |toast_window_entity, toast_window, cx| {
                    toast_window_entity.set_toasts(toasts.clone(), cx);
                    toast_window.refresh();
                });
                if update_result.is_ok() {
                    return;
                }
                self.app_toast_window = None;
            } else {
                // The popup is exact-sized and bottom-anchored; gpui windows can
                // resize but not move, so a height change recreates the window at
                // the new bottom-anchored bounds.
                let _ = handle.update(cx, |_, toast_window, _| {
                    toast_window.remove_window();
                });
                self.app_toast_window = None;
            }
        }
        let bounds = Bounds {
            origin: point(
                anchor.x - px(GPUI_APP_TOAST_WIDTH / 2.0),
                anchor.y - stack_height - px(GPUI_APP_TOAST_BOTTOM_MARGIN),
            ),
            size: size(px(GPUI_APP_TOAST_WIDTH), stack_height),
        };
        let app = cx.entity().downgrade();
        let options = WindowOptions {
            window_bounds: Some(WindowBounds::Windowed(bounds)),
            focus: false,
            show: true,
            kind: WindowKind::PopUp,
            is_movable: false,
            is_resizable: false,
            is_minimizable: false,
            titlebar: None,
            window_background: WindowBackgroundAppearance::Transparent,
            ..Default::default()
        };
        self.app_toast_window = cx
            .open_window(options, move |_, cx| {
                cx.new(|_| GpuiAppToastWindow { app, toasts })
            })
            .ok();
        self.app_toast_window_height = stack_height;
    }

    fn dispatch_gpui_sidebar_remote_event(
        &mut self,
        message: serde_json::Value,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUIRemoteMachines 2026-06-24-16:48:
        GPUI remote-machine status and presentation events are Rust-owned sidebar-only messages. Send only sanitized state enums, machine ids, and gxserver presentation snapshots/deltas into SidebarApp; remote auth tokens, SSH host/user/key data, paths from Settings commands, URLs, daemon response bodies, stdout/stderr, and command text must stay out of CEF globals and logs.

        CDXC:GPUIRemoteSessions 2026-06-24-17:19:
        Response-capable remote session requests may dispatch only request ids, success state, generic errors, and explicit safe metadata results such as previous-session search rows. Mutating remote session responses must be sanitized before this event boundary so renderer code never receives launch commands, tokens, SSH details, raw daemon bodies, or provider internals.
        */
        let Some(sidebar) = self.sidebar.clone() else {
            return;
        };
        let script = format!(
            "window.dispatchEvent(new CustomEvent('{GPUI_SIDEBAR_REMOTE_EVENT_NAME}', {{ detail: {} }})); undefined;",
            message
        );
        sidebar.update(cx, |surface, _| {
            surface.execute_app_owned_script(&script);
        });
    }

