    fn handle_workspace_split_resize_drag_move(
        &mut self,
        event: &MouseMoveEvent,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(drag) = self.workspace_split_drag else {
            return;
        };

        if !event.dragging() {
            self.finish_workspace_split_resize_drag(cx);
            return;
        }

        window.prevent_default();
        cx.stop_propagation();

        let next_ratio = drag.start_ratio
            + (split_resize_event_position(drag.axis, event.position) - drag.start_position)
                / drag.content_span.max(1.0);
        if self
            .agents_workspace
            .set_split_ratio(drag.split_id, next_ratio)
        {
            cx.notify();
        }
    }

