fn gpui_open_url(url: &'static str) -> Result<(), String> {
    /*
    CDXC:GPUISettingsActionBridge 2026-06-24-11:59:
    Settings URL actions in GPUI are bounded to hardcoded product URLs from Rust. Do not accept React-provided URLs, shell commands, environment values, or user paths for docs/System Settings opens.
    */
    gpui_spawn_os_open(std::ffi::OsStr::new(url))
}

/// Terminal link clicks (Ghostty OPEN_URL actions) carry runtime-provided URLs,
/// so unlike Settings actions the scheme is restricted instead of trusted.
fn gpui_open_terminal_action_url(url: &str) -> Result<(), String> {
    let trimmed = url.trim();
    let lowered = trimmed.to_ascii_lowercase();
    if !(lowered.starts_with("http://") || lowered.starts_with("https://")) {
        return Err("Unsupported terminal link scheme.".to_string());
    }
    if trimmed.len() > 2048 {
        return Err("Terminal link is too long.".to_string());
    }
    gpui_spawn_os_open(std::ffi::OsStr::new(trimmed))
}

/// Per-terminal runtime state reported by Ghostty OSC sequences and runtime
/// actions (window title, working directory, bell, hovered link, search).
/// Runtime-only: keyed by runtime session identity and never persisted into
/// shell-layout state.
#[derive(Clone, Debug, Default)]
struct GpuiTerminalRuntimeOscState {
    title: Option<String>,
    pwd: Option<String>,
    bell_count: u64,
    hovered_link_url: Option<String>,
    search: Option<GpuiTerminalSearchState>,
}

/// Mirrors the macOS host's per-surface `GhostexGhosttySearchState`: created by
/// START_SEARCH, updated by SEARCH_TOTAL/SEARCH_SELECTED, cleared by
/// END_SEARCH. Negative totals/selections from Ghostty mean "unknown".
#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct GpuiTerminalSearchState {
    needle: String,
    total: Option<u64>,
    selected: Option<u64>,
}

fn apply_gpui_terminal_runtime_action_events(
    osc_states: &mut HashMap<AgentsTerminalRuntimeSessionId, GpuiTerminalRuntimeOscState>,
    runtime_session_id: AgentsTerminalRuntimeSessionId,
    events: Vec<terminal_ghostty_surface::GhosttyRuntimeActionEvent>,
) -> bool {
    use terminal_ghostty_surface::GhosttyRuntimeActionEvent;

    let mut runtime_state_changed = false;
    for event in events {
        match event {
            GhosttyRuntimeActionEvent::OpenUrl { url } => {
                let _ = gpui_open_terminal_action_url(&url);
            }
            GhosttyRuntimeActionEvent::RingBell => {
                let state = osc_states.entry(runtime_session_id).or_default();
                state.bell_count = state.bell_count.wrapping_add(1);
                runtime_state_changed = true;
            }
            GhosttyRuntimeActionEvent::SetTitle { title } => {
                osc_states.entry(runtime_session_id).or_default().title = Some(title);
                runtime_state_changed = true;
            }
            GhosttyRuntimeActionEvent::Pwd { pwd } => {
                osc_states.entry(runtime_session_id).or_default().pwd = Some(pwd);
                runtime_state_changed = true;
            }
            GhosttyRuntimeActionEvent::MouseOverLink { url } => {
                let state = osc_states.entry(runtime_session_id).or_default();
                if state.hovered_link_url != url {
                    state.hovered_link_url = url;
                    runtime_state_changed = true;
                }
            }
            GhosttyRuntimeActionEvent::StartSearch { needle } => {
                let state = osc_states.entry(runtime_session_id).or_default();
                match (&mut state.search, needle) {
                    (Some(search), Some(needle)) => search.needle = needle,
                    (Some(_), None) => {}
                    (search @ None, needle) => {
                        *search = Some(GpuiTerminalSearchState {
                            needle: needle.unwrap_or_default(),
                            ..GpuiTerminalSearchState::default()
                        });
                    }
                }
                runtime_state_changed = true;
            }
            GhosttyRuntimeActionEvent::EndSearch => {
                let state = osc_states.entry(runtime_session_id).or_default();
                if state.search.take().is_some() {
                    runtime_state_changed = true;
                }
            }
            GhosttyRuntimeActionEvent::SearchTotal { total } => {
                let state = osc_states.entry(runtime_session_id).or_default();
                if let Some(search) = &mut state.search {
                    if search.total != total {
                        search.total = total;
                        runtime_state_changed = true;
                    }
                }
            }
            GhosttyRuntimeActionEvent::SearchSelected { selected } => {
                let state = osc_states.entry(runtime_session_id).or_default();
                if let Some(search) = &mut state.search {
                    if search.selected != selected {
                        search.selected = selected;
                        runtime_state_changed = true;
                    }
                }
            }
        }
    }
    runtime_state_changed
}

fn gpui_open_path(path: &Path) -> Result<(), String> {
    gpui_spawn_os_open(path.as_os_str())
}

