#[derive(Clone, Debug, PartialEq, Eq)]
struct GpuiOpenTarget {
    id: String,
    label: String,
    launch: GpuiOpenTargetLaunch,
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum GpuiOpenTargetLaunch {
    Finder,
    BuiltIn {
        default_command: Option<&'static str>,
        base_args: &'static [&'static str],
        resolved_command: Option<String>,
        resolved_app_name: Option<String>,
    },
    Custom {
        command: String,
        args: Vec<String>,
    },
}

struct GpuiOpenTargetAvailability {
    available_ids: HashSet<String>,
    resolved_commands: HashMap<String, String>,
    resolved_app_names: HashMap<String, String>,
}

fn gpui_visible_open_targets_from_current_settings() -> Vec<GpuiOpenTarget> {
    let settings = shared_settings::shared_sidebar_settings_snapshot();
    gpui_visible_open_targets_from_settings(settings.object())
}

fn gpui_visible_open_targets_from_settings(
    settings: &serde_json::Map<String, serde_json::Value>,
) -> Vec<GpuiOpenTarget> {
    /*
    CDXC:GPUITitlebarOpenIn 2026-06-24-12:50:
    GPUI titlebar Open In consumes the same shared Settings fields as React: hidden built-in ids, availability resolved ids/commands/app names, and normalized custom targets. Finder/Open Folder remains always available unless hidden, custom targets follow built-ins, and no project path, command text, URL, stdout/stderr, or user content is logged or persisted here.
    */
    let hidden_ids = gpui_open_target_hidden_ids(settings.get("workspaceOpenTargetHiddenIds"));
    let availability =
        gpui_open_target_availability(settings.get("workspaceOpenTargetAvailability"));
    let mut targets = Vec::new();
    for definition in GPUI_BUILT_IN_OPEN_TARGETS {
        if hidden_ids.contains(definition.id) {
            continue;
        }
        if definition.id != "finder" && !availability.available_ids.contains(definition.id) {
            continue;
        }
        targets.push(GpuiOpenTarget {
            id: definition.id.to_string(),
            label: definition.label.to_string(),
            launch: if definition.id == "finder" {
                GpuiOpenTargetLaunch::Finder
            } else {
                GpuiOpenTargetLaunch::BuiltIn {
                    default_command: definition.commands.first().copied(),
                    base_args: definition.base_args,
                    resolved_command: availability.resolved_commands.get(definition.id).cloned(),
                    resolved_app_name: availability.resolved_app_names.get(definition.id).cloned(),
                }
            },
        });
    }
    targets.extend(gpui_custom_open_targets(
        settings.get("customWorkspaceOpenTargets"),
    ));
    targets
}

fn gpui_open_target_hidden_ids(candidate: Option<&serde_json::Value>) -> HashSet<String> {
    let built_in_ids = gpui_built_in_open_target_ids();
    candidate
        .and_then(serde_json::Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|id| built_in_ids.contains(*id))
        .map(str::to_string)
        .collect()
}

fn gpui_open_target_availability(
    candidate: Option<&serde_json::Value>,
) -> GpuiOpenTargetAvailability {
    let built_in_ids = gpui_built_in_open_target_ids();
    let object = candidate.and_then(serde_json::Value::as_object);
    let mut available_ids = HashSet::from(["finder".to_string()]);
    if let Some(ids) = object
        .and_then(|object| object.get("availableTargetIds"))
        .and_then(serde_json::Value::as_array)
    {
        for id in ids
            .iter()
            .filter_map(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|id| built_in_ids.contains(*id))
        {
            available_ids.insert(id.to_string());
        }
    }
    let resolved_commands = gpui_open_target_resolution_map(
        object.and_then(|object| object.get("resolvedCommands")),
        &available_ids,
    );
    let resolved_app_names = gpui_open_target_resolution_map(
        object.and_then(|object| object.get("resolvedAppNames")),
        &available_ids,
    );
    GpuiOpenTargetAvailability {
        available_ids,
        resolved_commands,
        resolved_app_names,
    }
}

fn gpui_open_target_resolution_map(
    candidate: Option<&serde_json::Value>,
    available_ids: &HashSet<String>,
) -> HashMap<String, String> {
    candidate
        .and_then(serde_json::Value::as_object)
        .into_iter()
        .flat_map(|object| object.iter())
        .filter_map(|(target_id, value)| {
            let value = value.as_str()?.trim();
            (available_ids.contains(target_id.as_str()) && !value.is_empty())
                .then(|| (target_id.clone(), value.to_string()))
        })
        .collect()
}

fn gpui_custom_open_targets(candidate: Option<&serde_json::Value>) -> Vec<GpuiOpenTarget> {
    let mut seen_ids = HashSet::new();
    let mut targets = Vec::new();
    let Some(entries) = candidate.and_then(serde_json::Value::as_array) else {
        return targets;
    };
    for entry in entries {
        let Some(object) = entry.as_object() else {
            continue;
        };
        let label = object
            .get("label")
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .unwrap_or_default();
        let command = object
            .get("command")
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .unwrap_or_default();
        if label.is_empty() || command.is_empty() {
            continue;
        }
        let requested_id = object
            .get("id")
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .unwrap_or_default();
        let base_id = if requested_id.starts_with(GPUI_CUSTOM_OPEN_TARGET_ID_PREFIX) {
            requested_id.to_string()
        } else {
            format!(
                "{}{}",
                GPUI_CUSTOM_OPEN_TARGET_ID_PREFIX,
                gpui_open_target_slug(label)
            )
        };
        let mut id = base_id.clone();
        for suffix in 2.. {
            if !seen_ids.contains(&id) {
                break;
            }
            id = format!("{base_id}-{suffix}");
        }
        if !seen_ids.insert(id.clone()) {
            continue;
        }
        let args = object
            .get("args")
            .and_then(serde_json::Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(serde_json::Value::as_str)
            .map(str::to_string)
            .collect();
        targets.push(GpuiOpenTarget {
            id,
            label: label.to_string(),
            launch: GpuiOpenTargetLaunch::Custom {
                command: command.to_string(),
                args,
            },
        });
    }
    targets
}

fn gpui_built_in_open_target_ids() -> HashSet<&'static str> {
    GPUI_BUILT_IN_OPEN_TARGETS
        .iter()
        .map(|target| target.id)
        .collect()
}

fn gpui_open_target_slug(label: &str) -> String {
    let mut slug = String::new();
    let mut previous_dash = false;
    for character in label.trim().chars() {
        if character.is_ascii_alphanumeric() {
            slug.push(character.to_ascii_lowercase());
            previous_dash = false;
        } else if !previous_dash {
            slug.push('-');
            previous_dash = true;
        }
    }
    let slug = slug.trim_matches('-');
    if slug.is_empty() {
        "target".to_string()
    } else {
        slug.to_string()
    }
}

fn gpui_launch_open_target(target: &GpuiOpenTarget, project_path: &Path) -> Result<(), String> {
    /*
    CDXC:GPUITitlebarOpenIn 2026-06-24-12:50:
    Open In launch is bounded native process behavior: Finder/Open Folder uses the fixed OS opener, command targets use `/usr/bin/env` argv without shell splitting, macOS app-name launches use `/usr/bin/open -a`, child stdio is suppressed, and user paths/commands/errors are not copied into notifications or logs.
    */
    match &target.launch {
        GpuiOpenTargetLaunch::Finder => gpui_open_path(project_path)
            .map_err(|_| "Could not open the active project folder.".to_string()),
        GpuiOpenTargetLaunch::BuiltIn {
            default_command,
            base_args,
            resolved_command,
            resolved_app_name,
        } => {
            if let Some(command) = resolved_command
                .as_deref()
                .filter(|command| !command.trim().is_empty())
            {
                return gpui_spawn_open_target_command(command, *base_args, &[], project_path);
            }
            if let Some(app_name) = resolved_app_name
                .as_deref()
                .filter(|app_name| !app_name.trim().is_empty())
            {
                return gpui_spawn_open_target_app_name(app_name, project_path);
            }
            if let Some(command) = *default_command {
                return gpui_spawn_open_target_command(command, *base_args, &[], project_path);
            }
            Err("Could not launch the selected Open In target.".to_string())
        }
        GpuiOpenTargetLaunch::Custom { command, args } => {
            gpui_spawn_open_target_command(command, &[], args, project_path)
        }
    }
}

fn gpui_spawn_open_target_command(
    command: &str,
    base_args: &[&str],
    custom_args: &[String],
    project_path: &Path,
) -> Result<(), String> {
    let mut process = std::process::Command::new("/usr/bin/env");
    process.arg(command);
    for arg in base_args {
        process.arg(arg);
    }
    for arg in custom_args {
        process.arg(arg);
    }
    process
        .arg(project_path)
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn()
        .map(|_| ())
        .map_err(|_| "Could not launch the selected Open In target.".to_string())
}

struct GpuiDetectedOpenTargetAvailability {
    // Catalog-ordered, always contains "finder", never duplicates.
    available_target_ids: Vec<String>,
    resolved_commands: HashMap<String, String>,
    resolved_app_names: HashMap<String, String>,
}

const GPUI_OPEN_TARGET_DETECTION_TIMEOUT: Duration = Duration::from_secs(45);

fn gpui_workspace_open_target_detection_script() -> String {
    // Same probe script macOS builds in createWorkspaceOpenTargetDetectionScript
    // (native/sidebar/native-sidebar.tsx): a login shell resolves the user's
    // real PATH for `command -v`, and app bundles are checked by directory
    // before falling back to one mdfind query per name.
    let mut lines = vec![
        "set +e".to_string(),
        "ghostex_app_exists() {".to_string(),
        "  local app_name=\"$1\"".to_string(),
        "  local app_bundle=\"${app_name}.app\"".to_string(),
        "  local base".to_string(),
        "  for base in /Applications \"$HOME/Applications\" /System/Applications; do".to_string(),
        "    if [ -d \"$base/$app_bundle\" ]; then return 0; fi".to_string(),
        "  done".to_string(),
        "  local found".to_string(),
        "  found=$(/usr/bin/mdfind \"kMDItemFSName == '$app_bundle'cd && kMDItemContentType == 'com.apple.application-bundle'\" 2>/dev/null | /usr/bin/head -n 1)".to_string(),
        "  [ -n \"$found\" ]".to_string(),
        "}".to_string(),
    ];
    for definition in GPUI_BUILT_IN_OPEN_TARGETS {
        for command in definition.commands {
            lines.push(format!(
                "if command -v {} >/dev/null 2>&1; then printf 'command\\t%s\\t%s\\n' {} {}; fi",
                gpui_shell_single_quote(command),
                gpui_shell_single_quote(definition.id),
                gpui_shell_single_quote(command),
            ));
        }
    }
    for definition in GPUI_BUILT_IN_OPEN_TARGETS {
        for app_name in definition.macos_app_names {
            lines.push(format!(
                "if ghostex_app_exists {} ; then printf 'app\\t%s\\t%s\\n' {} {}; fi",
                gpui_shell_single_quote(app_name),
                gpui_shell_single_quote(definition.id),
                gpui_shell_single_quote(app_name),
            ));
        }
    }
    lines.join("\n")
}

fn gpui_detect_workspace_open_target_availability() -> Option<GpuiDetectedOpenTargetAvailability> {
    // None mirrors the macOS catch path (spawn failure or timeout: keep the
    // stored availability). A scan that ran but failed still returns the
    // finder-only result, exactly like the exitCode gate on macOS.
    let mut child = Command::new("/bin/zsh")
        .arg("-lc")
        .arg(gpui_workspace_open_target_detection_script())
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .ok()?;
    let deadline = Instant::now() + GPUI_OPEN_TARGET_DETECTION_TIMEOUT;
    let status = loop {
        match child.try_wait() {
            Ok(Some(status)) => break status,
            Ok(None) if Instant::now() < deadline => thread::sleep(Duration::from_millis(50)),
            _ => {
                let _ = child.kill();
                let _ = child.wait();
                return None;
            }
        }
    };
    let mut stdout = String::new();
    if let Some(mut pipe) = child.stdout.take() {
        let _ = pipe.read_to_string(&mut stdout);
    }

    let built_in_ids = gpui_built_in_open_target_ids();
    let mut available_ids: HashSet<String> = HashSet::from(["finder".to_string()]);
    let mut resolved_commands = HashMap::new();
    let mut resolved_app_names = HashMap::new();
    if status.code() == Some(0) {
        for line in stdout.split('\n') {
            let mut parts = line.split('\t');
            let (Some(kind), Some(target_id), Some(value)) =
                (parts.next(), parts.next(), parts.next())
            else {
                continue;
            };
            if target_id.is_empty() || value.is_empty() || !built_in_ids.contains(target_id) {
                continue;
            }
            available_ids.insert(target_id.to_string());
            if kind == "command" && !resolved_commands.contains_key(target_id) {
                resolved_commands.insert(target_id.to_string(), value.to_string());
            }
            if kind == "app" && !resolved_app_names.contains_key(target_id) {
                resolved_app_names.insert(target_id.to_string(), value.to_string());
            }
        }
    }
    let available_target_ids = GPUI_BUILT_IN_OPEN_TARGETS
        .iter()
        .filter(|definition| available_ids.contains(definition.id))
        .map(|definition| definition.id.to_string())
        .collect();
    Some(GpuiDetectedOpenTargetAvailability {
        available_target_ids,
        resolved_commands,
        resolved_app_names,
    })
}

fn gpui_detected_open_target_availability_matches_stored(
    detected: &GpuiDetectedOpenTargetAvailability,
    stored: &GpuiOpenTargetAvailability,
) -> bool {
    // checkedAtMs is deliberately outside the comparison, matching
    // workspaceOpenTargetAvailabilityEquals on macOS, so an unchanged machine
    // never rewrites settings at startup.
    detected.available_target_ids.len() == stored.available_ids.len()
        && detected
            .available_target_ids
            .iter()
            .all(|id| stored.available_ids.contains(id))
        && detected.resolved_commands == stored.resolved_commands
        && detected.resolved_app_names == stored.resolved_app_names
}

fn gpui_workspace_open_target_availability_settings_value(
    detected: &GpuiDetectedOpenTargetAvailability,
) -> serde_json::Value {
    let checked_at_ms = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_millis() as u64)
        .unwrap_or(0);
    let mut resolved_commands = serde_json::Map::new();
    let mut resolved_app_names = serde_json::Map::new();
    for definition in GPUI_BUILT_IN_OPEN_TARGETS {
        if let Some(command) = detected.resolved_commands.get(definition.id) {
            resolved_commands.insert(definition.id.to_string(), serde_json::json!(command));
        }
        if let Some(app_name) = detected.resolved_app_names.get(definition.id) {
            resolved_app_names.insert(definition.id.to_string(), serde_json::json!(app_name));
        }
    }
    serde_json::json!({
        "availableTargetIds": detected.available_target_ids,
        "checkedAtMs": checked_at_ms,
        "resolvedAppNames": resolved_app_names,
        "resolvedCommands": resolved_commands,
    })
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct GpuiKeepAwakePowerSnapshot {
    battery_percent: Option<f64>,
    external_display_connected: bool,
    low_power_mode: Option<bool>,
}

#[cfg(target_os = "macos")]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct GpuiKeepAwakePowerProbeOptions {
    include_battery: bool,
    include_external_display: bool,
    include_low_power_mode: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct GpuiKeepAwakeWorkingSessionGraceState {
    previous_working_session_count: usize,
    grace_until: Option<Instant>,
}

fn gpui_keep_awake_agents_working_session_count(workspace: &WorkspaceModel) -> usize {
    workspace
        .terminal_sessions
        .iter()
        .filter(|session| {
            session.presentation_state == TerminalSessionPresentationState::Running
                && session.activity == AgentTerminalActivity::Working
        })
        .count()
}

fn gpui_keep_awake_command_working_session_count(command_pane: &CommandPaneModel) -> usize {
    command_pane
        .flat_tab_ids()
        .into_iter()
        .filter(|(_group_id, session_id)| {
            command_pane.session(*session_id).is_some_and(|session| {
                !session.is_sleeping && session.activity == CommandTerminalActivity::Working
            })
        })
        .count()
}

fn gpui_keep_awake_command_delayed_send_session_count(command_pane: &CommandPaneModel) -> usize {
    /*
    CDXC:GPUITitlebarKeepAwake 2026-06-27-01:05:
    Native `createTitlebarKeepAwakeSessionState` treats projected Delayed Send remaining-time fields as a Keep Awake hold input only for non-sleeping terminal sessions. Agents `delayed_send_active` is semantic tab chrome in GPUI, unlike native projected remaining-time fields, so only command tabs with timer-owned runtime Delayed Send state can start the titlebar power hold.
    */
    command_pane
        .flat_tab_ids()
        .into_iter()
        .filter(|(_group_id, session_id)| {
            command_pane.session(*session_id).is_some_and(|session| {
                !session.is_sleeping
                    && session.delayed_send_active
                    && session.delayed_send_timer_owned
            })
        })
        .count()
}

fn gpui_keep_awake_working_session_count(
    workspace: &WorkspaceModel,
    command_pane: &CommandPaneModel,
) -> usize {
    /*
    CDXC:GPUITitlebarKeepAwake 2026-06-26-00:29:
    GPUI `keepAwakeWhileWorkingSessions` counts only real local terminal model facts equivalent to the macOS titlebar projection: Running Agents with `AgentTerminalActivity::Working` plus live command-tab sessions that are not sleeping and have `CommandTerminalActivity::Working`. Do not infer work from titles, command text, paths, status-file contents, terminal output, gxserver ids, or persisted private metadata.
    */
    gpui_keep_awake_agents_working_session_count(workspace)
        + gpui_keep_awake_command_working_session_count(command_pane)
}

fn gpui_keep_awake_refresh_working_session_grace_state(
    enabled: bool,
    previous_working_session_count: usize,
    current_working_session_count: usize,
    grace_until: Option<Instant>,
    now: Instant,
) -> GpuiKeepAwakeWorkingSessionGraceState {
    if !enabled {
        return GpuiKeepAwakeWorkingSessionGraceState {
            previous_working_session_count: 0,
            grace_until: None,
        };
    }

    let active_grace_until = grace_until.filter(|deadline| *deadline > now);
    let grace_until = if previous_working_session_count > 0 && current_working_session_count == 0 {
        now.checked_add(GPUI_KEEP_AWAKE_WORKING_SESSION_GRACE)
            .or(active_grace_until)
    } else {
        active_grace_until
    };

    GpuiKeepAwakeWorkingSessionGraceState {
        previous_working_session_count: current_working_session_count,
        grace_until,
    }
}

fn gpui_keep_awake_working_session_hold_active(
    settings: shared_settings::SharedKeepAwakeTitlebarSettings,
    observed_working_session_count: usize,
    grace_until: Option<Instant>,
    now: Instant,
) -> bool {
    settings.while_working_sessions
        && (observed_working_session_count > 0
            || grace_until.is_some_and(|deadline| now < deadline))
}

fn gpui_keep_awake_fire_at(
    started_at: Instant,
    duration_minutes: shared_settings::SharedKeepAwakeDurationMinutes,
) -> Option<Instant> {
    (duration_minutes.minutes() > 0)
        .then(|| started_at + Duration::from_secs(duration_minutes.minutes() * 60))
}

#[cfg(target_os = "macos")]
fn gpui_read_keep_awake_power_snapshot(
    options: GpuiKeepAwakePowerProbeOptions,
) -> Result<GpuiKeepAwakePowerSnapshot, String> {
    /*
    CDXC:GPUITitlebarKeepAwake 2026-06-25-23:49:
    Power automation probes must use fixed macOS command paths and only when the corresponding Settings rule can act. Parse stdout in memory into battery percent, Low Power Mode boolean, and display count; never log or persist command output, display names, paths, URLs, commands, settings payloads, or private terminal content.
    */
    let battery_output = if options.include_battery {
        Some(gpui_keep_awake_fixed_command_stdout(
            "/usr/bin/pmset",
            &["-g", "batt"],
        )?)
    } else {
        None
    };
    let low_power_output = if options.include_low_power_mode {
        Some(gpui_keep_awake_fixed_command_stdout(
            "/usr/bin/pmset",
            &["-g"],
        )?)
    } else {
        None
    };
    let display_output = if options.include_external_display {
        Some(gpui_keep_awake_fixed_command_stdout(
            "/usr/sbin/system_profiler",
            &["SPDisplaysDataType"],
        )?)
    } else {
        None
    };
    Ok(gpui_parse_keep_awake_power_snapshot(
        battery_output.as_deref(),
        low_power_output.as_deref(),
        display_output.as_deref(),
    ))
}

#[cfg(target_os = "macos")]
fn gpui_keep_awake_fixed_command_stdout(path: &str, args: &[&str]) -> Result<String, String> {
    let output = Command::new(path)
        .args(args)
        .stdin(Stdio::null())
        .stderr(Stdio::null())
        .output()
        .map_err(|_| "power probe failed".to_string())?;
    if !output.status.success() {
        return Err("power probe failed".to_string());
    }
    Ok(String::from_utf8_lossy(&output.stdout).into_owned())
}

fn gpui_parse_keep_awake_power_snapshot(
    battery_output: Option<&str>,
    low_power_output: Option<&str>,
    display_output: Option<&str>,
) -> GpuiKeepAwakePowerSnapshot {
    GpuiKeepAwakePowerSnapshot {
        battery_percent: battery_output.and_then(gpui_parse_pmset_battery_percent),
        external_display_connected: display_output
            .map(gpui_system_profiler_external_display_connected)
            .unwrap_or(false),
        low_power_mode: low_power_output.and_then(gpui_parse_pmset_low_power_mode),
    }
}

fn gpui_parse_pmset_battery_percent(output: &str) -> Option<f64> {
    for line in output.lines() {
        let Some(percent_index) = line.find('%') else {
            continue;
        };
        let before_percent = &line[..percent_index];
        let digits_reversed: String = before_percent
            .chars()
            .rev()
            .skip_while(|ch| ch.is_ascii_whitespace())
            .take_while(|ch| ch.is_ascii_digit() || *ch == '.')
            .collect();
        if digits_reversed.is_empty() {
            continue;
        }
        let digits: String = digits_reversed.chars().rev().collect();
        let Ok(percent) = digits.parse::<f64>() else {
            continue;
        };
        if percent.is_finite() {
            return Some(percent);
        }
    }
    None
}

fn gpui_parse_pmset_low_power_mode(output: &str) -> Option<bool> {
    output.lines().find_map(|line| {
        let mut parts = line.split_whitespace();
        (parts.next() == Some("lowpowermode")).then(|| parts.next() == Some("1"))
    })
}

fn gpui_system_profiler_external_display_connected(output: &str) -> bool {
    output
        .lines()
        .filter(|line| line.trim_start().starts_with("Resolution:"))
        .count()
        > 1
}

#[cfg(target_os = "macos")]
fn gpui_spawn_keep_awake_caffeinate(
    duration_minutes: shared_settings::SharedKeepAwakeDurationMinutes,
    allow_display_sleep: bool,
) -> Result<std::process::Child, String> {
    /*
    CDXC:GPUITitlebarKeepAwake 2026-06-24-13:16:
    GPUI Keep Awake must start macOS caffeinate directly with fixed argv and suppressed stdio. Use `-dis` for normal display+idle sleep prevention, `-is` when Settings allows display sleep, and add bounded `-t` seconds only for the 2-hour and 5-hour shared durations.
    */
    let mut command = std::process::Command::new("/usr/bin/caffeinate");
    command.arg(if allow_display_sleep { "-is" } else { "-dis" });
    if duration_minutes.minutes() > 0 {
        command
            .arg("-t")
            .arg((duration_minutes.minutes() * 60).to_string());
    }
    command
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn()
        .map_err(|_| "caffeinate spawn failed".to_string())
}

