fn gpui_remote_attach_session_reference_from_project_id(
    project_id: &str,
) -> Option<GpuiRemoteAttachSessionReference> {
    let rest = project_id.strip_prefix("remote:")?;
    let (remote_machine_id, rest) = rest.split_once(":session:")?;
    let (project_id, session_id) = rest.split_once(':')?;
    let remote_machine_id = gpui_normalize_remote_machine_id(remote_machine_id)?;
    if !gpui_remote_sidebar_project_id_allowed(project_id)
        || !gpui_remote_sidebar_session_id_allowed(session_id)
    {
        return None;
    }
    Some(GpuiRemoteAttachSessionReference {
        remote_machine_id,
        project_id: project_id.to_string(),
        session_id: session_id.to_string(),
    })
}

fn gpui_remote_scoped_session_id(
    remote_machine_id: &str,
    project_id: &str,
    session_id: &str,
) -> String {
    format!("remote:{remote_machine_id}:session:{project_id}:{session_id}")
}

fn gpui_remote_project_reference_from_project_id(
    project_id: &str,
) -> Option<GpuiRemoteProjectReference> {
    let rest = project_id.strip_prefix("remote:")?;
    let (remote_machine_id, project_id) = rest.split_once(":project:")?;
    let remote_machine_id = gpui_normalize_remote_machine_id(remote_machine_id)?;
    if !gpui_remote_sidebar_project_id_allowed(project_id) {
        return None;
    }
    Some(GpuiRemoteProjectReference {
        remote_machine_id,
        project_id: project_id.to_string(),
    })
}

fn gpui_remote_sidebar_session_id_allowed(value: &str) -> bool {
    !value.is_empty()
        && value.chars().count() <= GPUI_PROJECT_CONTRACT_STRING_MAX_CHARS
        && !value.contains('/')
        && !value.contains('\\')
        && !value.contains(':')
        && !value.contains('\0')
        && !value.chars().any(char::is_control)
}

fn gpui_prepare_remote_attach_terminal_plan(
    config: &GpuiRemoteMachineConfig,
    target: &GpuiRemoteGxserverRequestTarget,
    reference: &GpuiRemoteAttachSessionReference,
    wake_session: bool,
) -> Result<GpuiRemoteAttachTerminalPlan, String> {
    /*
    CDXC:GPUIRemoteAttach 2026-06-24-19:06:
    Remote attach validates session/project ownership through the Rust-owned gxserver tunnel before creating a GPUI terminal. The interactive pane runs a fresh SSH `ghostex attach` command built from saved Settings and exact ids; renderer text, gxserver bearer tokens, attach metadata commands, remote paths, stdout/stderr, and daemon bodies are never logged or copied to CEF.
    */
    let path = if wake_session {
        "/api/wakeSession"
    } else {
        "/api/attachSessionMetadata"
    };
    let result = gpui_remote_gxserver_rpc_result(
        target,
        path,
        &serde_json::json!({
            "projectId": reference.project_id.as_str(),
            "sessionId": reference.session_id.as_str(),
        }),
        Duration::from_secs(15),
    )?;
    gpui_validate_remote_attach_metadata(&result)?;
    let clipboard_command = gpui_remote_ghostex_attach_ssh_command(config, reference);
    let terminal_command = gpui_remote_attach_terminal_process_command(&clipboard_command);
    Ok(GpuiRemoteAttachTerminalPlan {
        clipboard_command,
        terminal_command,
        title: "Remote Attach".to_string(),
    })
}

fn gpui_prepare_local_workspace_attach_terminal_plan(
    reference: &GpuiLocalWorkspaceSessionKey,
) -> Result<GpuiLocalWorkspaceAttachTerminalPlan, String> {
    /*
    CDXC:GPUIWorkspaceSessionFocus 2026-06-26-06:08:
    Local GPUI sidebar session clicks follow macOS zmx attach sequencing: Rust asks localhost gxserver for wake/attach metadata, starts a missing zmx provider only when gxserver returns queued startup text for provider ownership, then opens an awake Agents Running tab whose exact mount slot consumes the daemon-built attach command. CEF cannot provide commands, cwd, titles, paths, daemon bodies, tokens, stdout/stderr, or terminal content.
    */
    let attach_params = gpui_local_workspace_attach_rpc_params(reference, Some(""));
    let mut result =
        gpui_gxserver_rpc_result("/api/wakeSession", &attach_params, Duration::from_secs(15))?;
    let mut attach = gpui_local_workspace_attach_object(&result)?;
    gpui_validate_local_workspace_attach_not_restore_blocked(attach)?;

    if should_start_local_zmx_provider_before_gpui_attach(attach) {
        let startup_text = gpui_local_workspace_attach_startup_text(attach)
            .ok_or_else(|| "Session provider startup is unavailable.".to_string())?
            .to_string();
        let provider_params =
            gpui_local_workspace_attach_rpc_params(reference, Some(startup_text.as_str()));
        gpui_gxserver_rpc_result(
            "/api/startSessionProvider",
            &provider_params,
            Duration::from_secs(30),
        )?;
        result = gpui_gxserver_rpc_result(
            "/api/attachSessionMetadata",
            &attach_params,
            Duration::from_secs(15),
        )?;
        attach = gpui_local_workspace_attach_object(&result)?;
        gpui_validate_local_workspace_attach_not_restore_blocked(attach)?;
    }

    gpui_validate_local_workspace_attach_metadata(attach)?;
    let attach_command = gpui_local_workspace_attach_string(attach, "attachCommand")
        .ok_or_else(|| "Session attach metadata is unavailable.".to_string())?
        .to_string();
    let title = gpui_local_workspace_attach_title(attach);
    let working_directory = gpui_local_workspace_attach_string(attach, "cwd").map(str::to_string);

    Ok(GpuiLocalWorkspaceAttachTerminalPlan {
        attach_command,
        title,
        working_directory,
    })
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct GpuiLocalT3SessionRouteMetadata {
    created_at: Option<String>,
    project_id: String,
    server_origin: String,
    thread_id: Option<String>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct GpuiCreatedLocalT3Session {
    project_id: String,
    session_id: String,
    url: String,
}

const GPUI_T3_LOCAL_SERVER_ORIGIN: &str = "http://127.0.0.1:3774";

fn gpui_create_local_t3_session(project_id: &str) -> Result<GpuiCreatedLocalT3Session, String> {
    /*
    CDXC:GPUIT3SessionCreate 2026-06-29-01:22:
    Creating T3 Code from the GPUI sidebar must create a durable gxserver `kind: "t3"` session and open a T3 draft route for the selected project. Resolve T3 project metadata with the persisted local owner bearer in Rust; the sidebar renderer may pass only the bounded gxserver project id and must never provide commands, paths, URLs, tokens, stdout/stderr, or daemon responses.
    */
    if !gpui_remote_sidebar_project_id_allowed(project_id) {
        return Err("T3 project id is invalid.".to_string());
    }
    let status = gpui_gxserver_rpc_result(
        "/api/readProjectStatus",
        &serde_json::json!({
            "projectId": project_id,
        }),
        Duration::from_secs(10),
    )?;
    let project = status
        .get("project")
        .and_then(serde_json::Value::as_object)
        .ok_or_else(|| "gxserver project metadata is unavailable.".to_string())?;
    let workspace_root = gpui_trimmed_json_string_field(project, "path")
        .ok_or_else(|| "T3 Code needs a project workspace path.".to_string())?;
    let server_origin = GPUI_T3_LOCAL_SERVER_ORIGIN.to_string();
    let environment_id = gpui_read_t3_environment_id(&server_origin)?;
    let owner_bearer = gpui_read_t3_owner_bearer_token()?;
    let snapshot = gpui_t3_loopback_json_request(
        &server_origin,
        "GET",
        "/api/orchestration/snapshot",
        Some(owner_bearer.as_str()),
        None,
        Duration::from_secs(10),
    )?;
    let t3_project_id = gpui_ensure_t3_project_for_workspace(
        &server_origin,
        owner_bearer.as_str(),
        &snapshot,
        workspace_root,
    )?;
    let create_result = gpui_gxserver_rpc_result(
        "/api/createSession",
        &serde_json::json!({
            "cwd": workspace_root,
            "kind": "t3",
            "lifecycleState": "running",
            "projectId": project_id,
            "providerState": gpui_t3_session_provider_state(
                &t3_project_id,
                &server_origin,
                None,
                workspace_root,
            ),
            "runtimeSettings": gpui_t3_session_runtime_settings(
                project_id,
                None,
                &t3_project_id,
                &server_origin,
                None,
                workspace_root,
                "placeholder",
                Some(environment_id.as_str()),
                None,
            ),
            "surface": "workspace",
            "title": "T3 Code",
        }),
        Duration::from_secs(10),
    )?;
    let session = create_result
        .get("session")
        .and_then(serde_json::Value::as_object)
        .ok_or_else(|| "gxserver did not create a T3 session.".to_string())?;
    let session_id = gpui_trimmed_json_string_field(session, "sessionId")
        .ok_or_else(|| "gxserver did not return a T3 session id.".to_string())?
        .to_string();
    let created_at = gpui_trimmed_json_string_field(session, "createdAt").map(str::to_string);
    let thread_id = gpui_stable_t3_draft_thread_id(&session_id);
    gpui_gxserver_rpc_result(
        "/api/updateSession",
        &serde_json::json!({
            "kind": "t3",
            "lifecycleState": "running",
            "projectId": project_id,
            "providerState": gpui_t3_session_provider_state(
                &t3_project_id,
                &server_origin,
                Some(thread_id.as_str()),
                workspace_root,
            ),
            "runtimeSettings": gpui_t3_session_runtime_settings(
                project_id,
                Some(session_id.as_str()),
                &t3_project_id,
                &server_origin,
                Some(thread_id.as_str()),
                workspace_root,
                "placeholder",
                Some(environment_id.as_str()),
                created_at.as_deref(),
            ),
            "sessionId": session_id.as_str(),
            "title": "T3 Code",
        }),
        Duration::from_secs(10),
    )?;
    let reference = GpuiLocalWorkspaceSessionKey {
        project_id: project_id.to_string(),
        session_id: session_id.clone(),
    };
    let metadata = GpuiLocalT3SessionRouteMetadata {
        created_at,
        project_id: t3_project_id,
        server_origin,
        thread_id: Some(thread_id),
    };
    let url = gpui_local_t3_session_route_url(&reference, &metadata, &environment_id)?;
    Ok(GpuiCreatedLocalT3Session {
        project_id: project_id.to_string(),
        session_id,
        url,
    })
}

fn gpui_prepare_local_t3_session_route(
    reference: &GpuiLocalWorkspaceSessionKey,
) -> Result<String, String> {
    /*
    CDXC:GPUIT3SessionFocus 2026-06-28-22:27:
    T3 session activation resolves the route from durable gxserver T3 metadata and the local T3 environment descriptor. Use draft routes for Ghostex-owned placeholder thread ids so users land in a usable composer, and use direct thread routes only for real T3 thread ids.
    */
    let result = gpui_gxserver_rpc_result(
        "/api/readProjectStatus",
        &serde_json::json!({
            "projectId": reference.project_id.as_str(),
        }),
        Duration::from_secs(10),
    )?;
    let sessions = result
        .get("sessions")
        .and_then(serde_json::Value::as_array)
        .ok_or_else(|| "gxserver returned invalid T3 session metadata.".to_string())?;
    let session = sessions
        .iter()
        .filter_map(serde_json::Value::as_object)
        .find(|session| {
            json_string_field(session, "projectId") == Some(reference.project_id.as_str())
                && json_string_field(session, "sessionId") == Some(reference.session_id.as_str())
                && json_string_field(session, "kind") == Some("t3")
        })
        .ok_or_else(|| "T3 session metadata was not found.".to_string())?;
    let metadata = gpui_local_t3_session_route_metadata_from_session(session)?;
    let environment_id = gpui_read_t3_environment_id(&metadata.server_origin)?;
    gpui_local_t3_session_route_url(reference, &metadata, &environment_id)
}

fn gpui_local_t3_session_route_metadata_from_session(
    session: &serde_json::Map<String, serde_json::Value>,
) -> Result<GpuiLocalT3SessionRouteMetadata, String> {
    let runtime_settings = session
        .get("runtimeSettings")
        .and_then(serde_json::Value::as_object)
        .ok_or_else(|| "T3 session runtime metadata is unavailable.".to_string())?;
    if json_string_field(runtime_settings, "provider") != Some("t3code") {
        return Err("T3 session provider metadata is unavailable.".to_string());
    }
    let t3 = runtime_settings
        .get("t3")
        .and_then(serde_json::Value::as_object)
        .ok_or_else(|| "T3 session route metadata is unavailable.".to_string())?;
    let server_origin = json_string_field(t3, "serverOrigin")
        .and_then(gpui_normalized_t3_loopback_origin)
        .ok_or_else(|| "T3 session origin is unavailable.".to_string())?;
    let project_id = gpui_trimmed_json_string_field(t3, "projectId")
        .ok_or_else(|| "T3 project metadata is unavailable.".to_string())?
        .to_string();
    let thread_id = gpui_trimmed_json_string_field(t3, "boundThreadId")
        .or_else(|| gpui_trimmed_json_string_field(t3, "threadId"))
        .map(str::to_string);
    let created_at = gpui_trimmed_json_string_field(t3, "createdAt")
        .or_else(|| gpui_trimmed_json_string_field(session, "createdAt"))
        .map(str::to_string);
    Ok(GpuiLocalT3SessionRouteMetadata {
        created_at,
        project_id,
        server_origin,
        thread_id,
    })
}

fn gpui_ensure_t3_project_for_workspace(
    server_origin: &str,
    owner_bearer: &str,
    snapshot: &serde_json::Value,
    workspace_root: &str,
) -> Result<String, String> {
    if let Some(project_id) = gpui_t3_snapshot_project_id_for_workspace(snapshot, workspace_root) {
        return Ok(project_id);
    }
    gpui_create_t3_project(server_origin, owner_bearer, workspace_root)
}

fn gpui_t3_snapshot_project_id_for_workspace(
    snapshot: &serde_json::Value,
    workspace_root: &str,
) -> Option<String> {
    snapshot
        .get("projects")
        .and_then(serde_json::Value::as_array)?
        .iter()
        .filter_map(serde_json::Value::as_object)
        .find(|project| {
            json_string_field(project, "workspaceRoot") == Some(workspace_root)
                && !gpui_t3_snapshot_record_is_deleted(project)
        })
        .and_then(|project| gpui_trimmed_json_string_field(project, "id"))
        .map(str::to_string)
}

fn gpui_t3_snapshot_record_is_deleted(record: &serde_json::Map<String, serde_json::Value>) -> bool {
    !matches!(
        record.get("deletedAt"),
        None | Some(serde_json::Value::Null)
    )
}

fn gpui_create_t3_project(
    server_origin: &str,
    owner_bearer: &str,
    workspace_root: &str,
) -> Result<String, String> {
    let project_id = gpui_random_uuid_string()?;
    let now = gpui_status_generated_at();
    let title = gpui_t3_project_title_from_workspace_root(workspace_root);
    gpui_t3_loopback_json_request(
        server_origin,
        "POST",
        "/api/orchestration/dispatch",
        Some(owner_bearer),
        Some(&serde_json::json!({
            "commandId": gpui_random_uuid_string()?,
            "createdAt": now,
            "defaultModelSelection": {
                "model": "gpt-5-codex",
                "provider": "codex",
            },
            "projectId": project_id,
            "title": title,
            "type": "project.create",
            "workspaceRoot": workspace_root,
        })),
        Duration::from_secs(10),
    )?;
    Ok(project_id)
}

fn gpui_t3_project_title_from_workspace_root(workspace_root: &str) -> String {
    Path::new(workspace_root)
        .file_name()
        .map(|name| name.to_string_lossy().trim().to_string())
        .filter(|name| !name.is_empty())
        .unwrap_or_else(|| "project".to_string())
        .chars()
        .filter(|ch| !ch.is_control())
        .take(120)
        .collect()
}

fn gpui_t3_session_runtime_settings(
    ghostex_project_id: &str,
    ghostex_session_id: Option<&str>,
    t3_project_id: &str,
    server_origin: &str,
    thread_id: Option<&str>,
    workspace_root: &str,
    title_source: &str,
    environment_id: Option<&str>,
    created_at: Option<&str>,
) -> serde_json::Value {
    let mut t3 = serde_json::Map::new();
    t3.insert(
        "ghostexProjectId".to_string(),
        serde_json::Value::String(ghostex_project_id.to_string()),
    );
    if let Some(ghostex_session_id) = ghostex_session_id {
        t3.insert(
            "ghostexSessionId".to_string(),
            serde_json::Value::String(ghostex_session_id.to_string()),
        );
    }
    t3.insert(
        "projectId".to_string(),
        serde_json::Value::String(t3_project_id.to_string()),
    );
    t3.insert(
        "serverOrigin".to_string(),
        serde_json::Value::String(server_origin.to_string()),
    );
    if let Some(environment_id) = environment_id {
        t3.insert(
            "environmentId".to_string(),
            serde_json::Value::String(environment_id.to_string()),
        );
    }
    if let Some(thread_id) = thread_id {
        t3.insert(
            "boundThreadId".to_string(),
            serde_json::Value::String(thread_id.to_string()),
        );
        t3.insert(
            "threadId".to_string(),
            serde_json::Value::String(thread_id.to_string()),
        );
    }
    t3.insert(
        "workspaceRoot".to_string(),
        serde_json::Value::String(workspace_root.to_string()),
    );
    if let Some(created_at) = created_at {
        t3.insert(
            "createdAt".to_string(),
            serde_json::Value::String(created_at.to_string()),
        );
    }
    t3.insert(
        "createdBy".to_string(),
        serde_json::Value::String("ghostex-embedded".to_string()),
    );
    t3.insert(
        "t3SidebarMode".to_string(),
        serde_json::Value::String("collapsed".to_string()),
    );
    serde_json::json!({
        "provider": "t3code",
        "t3": serde_json::Value::Object(t3),
        "titleSource": title_source,
    })
}

fn gpui_t3_session_provider_state(
    t3_project_id: &str,
    server_origin: &str,
    thread_id: Option<&str>,
    workspace_root: &str,
) -> serde_json::Value {
    let mut t3 = serde_json::Map::new();
    t3.insert(
        "projectId".to_string(),
        serde_json::Value::String(t3_project_id.to_string()),
    );
    t3.insert(
        "serverOrigin".to_string(),
        serde_json::Value::String(server_origin.to_string()),
    );
    if let Some(thread_id) = thread_id {
        t3.insert(
            "boundThreadId".to_string(),
            serde_json::Value::String(thread_id.to_string()),
        );
        t3.insert(
            "threadId".to_string(),
            serde_json::Value::String(thread_id.to_string()),
        );
    }
    t3.insert(
        "workspaceRoot".to_string(),
        serde_json::Value::String(workspace_root.to_string()),
    );
    serde_json::json!({
        "lifecycleState": "unknown",
        "provider": "t3code",
        "t3": serde_json::Value::Object(t3),
    })
}

fn gpui_issue_t3_browser_access_link() -> Result<GpuiT3BrowserAccessLink, String> {
    /*
    macOS chain parity: owner bearer from the persisted T3 auth state, one
    pairing-token POST against the loopback T3 server, then the same
    tailscale > local-network > local-only address resolution with the
    macOS note strings. No runtime start happens here (Decision #7).
    */
    let owner_bearer = gpui_read_t3_owner_bearer_token()
        .map_err(|_| "T3 Code is not running. Open a T3 Code session first, then try Remote Access again.".to_string())?;
    let response = gpui_t3_loopback_json_request(
        GPUI_T3_LOCAL_SERVER_ORIGIN,
        "POST",
        "/api/auth/pairing-token",
        Some(owner_bearer.as_str()),
        Some(&serde_json::json!({ "label": GPUI_T3_BROWSER_ACCESS_PAIRING_LABEL })),
        Duration::from_secs(5),
    )
    .map_err(|error| format!("Could not create the T3 pairing link: {error}"))?;
    let credential = response
        .get("credential")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|credential| !credential.is_empty())
        .ok_or_else(|| "T3 pairing link response did not include a credential.".to_string())?;

    let local_url = gpui_t3_pairing_url_for_host(None, credential)?;
    let tailscale_host = gpui_detect_tailscale_ipv4();
    let local_network_host = gpui_detect_local_network_ipv4();
    let local_network_url = match local_network_host.as_deref() {
        Some(host) => Some(gpui_t3_pairing_url_for_host(Some(host), credential)?),
        None => None,
    };

    if let Some(host) = tailscale_host.as_deref() {
        let endpoint_url = gpui_t3_pairing_url_for_host(Some(host), credential)?;
        return Ok(GpuiT3BrowserAccessLink {
            endpoint_url,
            note: if local_network_url.is_some() {
                "QR code and Copy link use your machine's Tailscale address. Open link uses your machine's local network address."
            } else {
                "QR code and Copy link use your machine's Tailscale address. No local network address was detected, so Open link falls back to this machine only."
            },
            local_url: local_network_url.unwrap_or(local_url),
            mode: "tailscale",
            tailscale_enabled: true,
        });
    }

    if let Some(local_network_url) = local_network_url {
        return Ok(GpuiT3BrowserAccessLink {
            endpoint_url: local_network_url.clone(),
            local_url: local_network_url,
            mode: "local-network",
            note: "Tailscale is not connected, so QR code, Copy link, and Open link all use your machine's local network address.",
            tailscale_enabled: false,
        });
    }

    Ok(GpuiT3BrowserAccessLink {
        endpoint_url: local_url.clone(),
        local_url,
        mode: "local-only",
        note: "No Tailscale or local network address was detected, so QR code, Copy link, and Open link only work on this machine for now.",
        tailscale_enabled: false,
    })
}

fn gpui_t3_pairing_url_for_host(host: Option<&str>, credential: &str) -> Result<String, String> {
    // macOS `buildT3PairingUrl` + `replaceT3AccessUrlHost`: the /pair route on
    // the fixed T3 origin, with the credential in the fragment and only the
    // hostname swapped for network-reachable variants (port preserved).
    let mut url = gpui::http_client::Url::parse(GPUI_T3_LOCAL_SERVER_ORIGIN)
        .map_err(|_| "T3 server origin is invalid.".to_string())?;
    if let Some(host) = host {
        url.set_host(Some(host))
            .map_err(|_| "T3 access address is invalid.".to_string())?;
    }
    url.set_path("/pair");
    url.set_fragment(Some(&format!(
        "token={}",
        gpui_encode_uri_component(credential)
    )));
    Ok(url.to_string())
}

fn gpui_encode_uri_component(value: &str) -> String {
    // JavaScript encodeURIComponent equivalent (unreserved set kept).
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut encoded = String::with_capacity(value.len());
    for byte in value.bytes() {
        match byte {
            b'A'..=b'Z'
            | b'a'..=b'z'
            | b'0'..=b'9'
            | b'-'
            | b'_'
            | b'.'
            | b'~'
            | b'!'
            | b'*'
            | b'\''
            | b'('
            | b')' => encoded.push(byte as char),
            _ => {
                encoded.push('%');
                encoded.push(HEX[(byte >> 4) as usize] as char);
                encoded.push(HEX[(byte & 0x0f) as usize] as char);
            }
        }
    }
    encoded
}

fn gpui_detect_tailscale_ipv4() -> Option<String> {
    let output = std::process::Command::new("/usr/bin/env")
        .args(["tailscale", "ip", "-4"])
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    String::from_utf8_lossy(&output.stdout)
        .lines()
        .map(str::trim)
        .find(|line| gpui_is_ipv4_host(line))
        .map(str::to_string)
}

fn gpui_detect_local_network_ipv4() -> Option<String> {
    // Same probe as macOS `detectNativeLocalNetworkIpv4`: default-route
    // interface first, then the common en0/en1 fallbacks.
    let script = concat!(
        "iface=\"$(/sbin/route get default 2>/dev/null | /usr/bin/awk '/interface:/{print $2; exit}')\"; ",
        "if [ -n \"$iface\" ]; then /usr/sbin/ipconfig getifaddr \"$iface\" 2>/dev/null && exit 0; fi; ",
        "for fallback in en0 en1; do /usr/sbin/ipconfig getifaddr \"$fallback\" 2>/dev/null && exit 0; done; ",
        "exit 1"
    );
    let output = std::process::Command::new("/bin/sh")
        .args(["-lc", script])
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    String::from_utf8_lossy(&output.stdout)
        .lines()
        .map(str::trim)
        .find(|line| gpui_is_ipv4_host(line))
        .map(str::to_string)
}

fn gpui_is_ipv4_host(value: &str) -> bool {
    let parts: Vec<&str> = value.split('.').collect();
    parts.len() == 4
        && parts.iter().all(|part| {
            !part.is_empty()
                && part.len() <= 3
                && part.bytes().all(|byte| byte.is_ascii_digit())
                && part.parse::<u16>().is_ok_and(|number| number <= 255)
        })
}

fn gpui_read_t3_owner_bearer_token() -> Result<String, String> {
    let token_path = home_dir()
        .join(".ghostex")
        .join("t3-runtime")
        .join("auth-state.json");
    let text = fs::read_to_string(token_path)
        .map_err(|_| "T3 owner authorization is unavailable.".to_string())?;
    let value = serde_json::from_str::<serde_json::Value>(&text)
        .map_err(|_| "T3 owner authorization is invalid.".to_string())?;
    let object = value
        .as_object()
        .ok_or_else(|| "T3 owner authorization is invalid.".to_string())?;
    if json_string_field(object, "provider") != Some("t3code") {
        return Err("T3 owner authorization is invalid.".to_string());
    }
    let token = gpui_trimmed_json_string_field(object, "ownerBearerToken")
        .ok_or_else(|| "T3 owner authorization is unavailable.".to_string())?;
    if token.chars().count() > 16 * 1024 || token.chars().any(char::is_control) {
        return Err("T3 owner authorization is invalid.".to_string());
    }
    Ok(token.to_string())
}

fn gpui_random_uuid_string() -> Result<String, String> {
    let mut bytes = [0_u8; 16];
    let mut file = fs::File::open("/dev/urandom")
        .map_err(|_| "Could not generate T3 project identity.".to_string())?;
    file.read_exact(&mut bytes)
        .map_err(|_| "Could not generate T3 project identity.".to_string())?;
    bytes[6] = (bytes[6] & 0x0f) | 0x40;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    Ok(format!(
        "{:02X}{:02X}{:02X}{:02X}-{:02X}{:02X}-{:02X}{:02X}-{:02X}{:02X}-{:02X}{:02X}{:02X}{:02X}{:02X}{:02X}",
        bytes[0],
        bytes[1],
        bytes[2],
        bytes[3],
        bytes[4],
        bytes[5],
        bytes[6],
        bytes[7],
        bytes[8],
        bytes[9],
        bytes[10],
        bytes[11],
        bytes[12],
        bytes[13],
        bytes[14],
        bytes[15]
    ))
}

fn gpui_normalized_t3_loopback_origin(value: &str) -> Option<String> {
    let parsed = gpui::http_client::Url::parse(value.trim()).ok()?;
    if parsed.scheme() != "http" || !parsed.username().is_empty() || parsed.password().is_some() {
        return None;
    }
    let host = parsed.host_str()?;
    if !matches!(host, "127.0.0.1" | "localhost" | "::1" | "[::1]") {
        return None;
    }
    let port = parsed.port()?;
    if host == "::1" || host == "[::1]" {
        Some(format!("http://[::1]:{port}"))
    } else {
        Some(format!("http://{host}:{port}"))
    }
}

fn gpui_read_t3_environment_id(server_origin: &str) -> Result<String, String> {
    let payload = gpui_t3_loopback_json_get(
        server_origin,
        "/.well-known/t3/environment",
        Duration::from_secs(5),
    )?;
    gpui_trimmed_json_string_field(
        payload
            .as_object()
            .ok_or_else(|| "T3 environment metadata is invalid.".to_string())?,
        "environmentId",
    )
    .map(str::to_string)
    .ok_or_else(|| "T3 environment id is unavailable.".to_string())
}

fn gpui_t3_loopback_json_get(
    server_origin: &str,
    path: &str,
    timeout: Duration,
) -> Result<serde_json::Value, String> {
    gpui_t3_loopback_json_request(server_origin, "GET", path, None, None, timeout)
}

fn gpui_t3_loopback_json_request(
    server_origin: &str,
    method: &str,
    path: &str,
    owner_bearer: Option<&str>,
    body: Option<&serde_json::Value>,
    timeout: Duration,
) -> Result<serde_json::Value, String> {
    let parsed = gpui::http_client::Url::parse(server_origin)
        .map_err(|_| "T3 session origin is invalid.".to_string())?;
    let host = parsed
        .host_str()
        .filter(|host| matches!(*host, "127.0.0.1" | "localhost" | "::1" | "[::1]"))
        .ok_or_else(|| "T3 session origin is unavailable.".to_string())?;
    let port = parsed
        .port()
        .ok_or_else(|| "T3 session port is unavailable.".to_string())?;
    if !path.starts_with('/')
        || path.contains('\0')
        || path.bytes().any(|byte| byte.is_ascii_control())
    {
        return Err("T3 route request path is invalid.".to_string());
    }
    if !matches!(method, "GET" | "POST") {
        return Err("T3 API method is invalid.".to_string());
    }
    if let Some(token) = owner_bearer {
        if token.trim() != token
            || token.is_empty()
            || token.chars().count() > 16 * 1024
            || token.chars().any(char::is_control)
        {
            return Err("T3 owner authorization is invalid.".to_string());
        }
    }
    let address = if host == "::1" || host == "[::1]" {
        format!("[::1]:{port}")
    } else {
        format!("{host}:{port}")
    };
    let mut stream = TcpStream::connect(&address)
        .map_err(|_| "T3 Code runtime is not reachable on localhost.".to_string())?;
    stream
        .set_read_timeout(Some(timeout))
        .map_err(|_| "Could not configure T3 read timeout.".to_string())?;
    stream
        .set_write_timeout(Some(timeout))
        .map_err(|_| "Could not configure T3 write timeout.".to_string())?;
    let body_text = body.map(serde_json::Value::to_string);
    let mut request = format!(
        "{method} {path} HTTP/1.1\r\nHost: {address}\r\nConnection: close\r\nAccept: application/json\r\n"
    );
    if let Some(token) = owner_bearer {
        request.push_str("Authorization: Bearer ");
        request.push_str(token);
        request.push_str("\r\n");
    }
    if let Some(body_text) = body_text.as_deref() {
        request.push_str("Content-Type: application/json\r\n");
        request.push_str(&format!("Content-Length: {}\r\n", body_text.len()));
    }
    request.push_str("\r\n");
    if let Some(body_text) = body_text.as_deref() {
        request.push_str(body_text);
    }
    stream
        .write_all(request.as_bytes())
        .map_err(|_| "Could not send T3 API request.".to_string())?;
    let mut response = String::new();
    stream
        .read_to_string(&mut response)
        .map_err(|_| "Could not read T3 API response.".to_string())?;
    let (headers, body) = response
        .split_once("\r\n\r\n")
        .ok_or_else(|| "T3 runtime returned an invalid HTTP response.".to_string())?;
    let status_code = headers
        .lines()
        .next()
        .and_then(|line| line.split_whitespace().nth(1))
        .and_then(|status| status.parse::<u16>().ok())
        .ok_or_else(|| "T3 runtime returned an invalid HTTP status.".to_string())?;
    if !(200..300).contains(&status_code) {
        return Err(format!("T3 API request failed with HTTP {status_code}."));
    }
    let body = gxserver_http_response_body(headers, body)?;
    if body.trim().is_empty() {
        return Ok(serde_json::Value::Null);
    }
    serde_json::from_str::<serde_json::Value>(&body)
        .map_err(|_| "T3 API metadata is invalid.".to_string())
}

fn gpui_local_t3_session_route_url(
    reference: &GpuiLocalWorkspaceSessionKey,
    metadata: &GpuiLocalT3SessionRouteMetadata,
    environment_id: &str,
) -> Result<String, String> {
    let mut url = gpui::http_client::Url::parse(&metadata.server_origin)
        .map_err(|_| "T3 session origin is invalid.".to_string())?;
    let thread_id = metadata.thread_id.as_deref();
    if let Some(thread_id) =
        thread_id.filter(|thread_id| gpui_t3_thread_id_is_server_thread(thread_id))
    {
        let environment_segment = gpui_t3_route_path_segment(environment_id)
            .ok_or_else(|| "T3 environment route segment is invalid.".to_string())?;
        let thread_segment = gpui_t3_route_path_segment(thread_id)
            .ok_or_else(|| "T3 thread route segment is invalid.".to_string())?;
        url.set_path(&format!("/{environment_segment}/{thread_segment}"));
        url.set_fragment(None);
        {
            /*
            CDXC:GPUIT3SessionFocus 2026-07-01-02:17:
            Real T3 thread routes still need the Ghostex embedded launch descriptor. Draft promotion can replace the URL path after first send, so keep `ghostexProjectId` and `ghostexSessionId` in the query for host title/activity sync and sidebar-collapse ownership.
            */
            let mut query = url.query_pairs_mut();
            query.clear();
            query.append_pair("ghostexEmbedded", "1");
            query.append_pair("ghostexProjectId", &reference.project_id);
            query.append_pair("ghostexSessionId", &reference.session_id);
            query.append_pair("environmentId", environment_id);
            query.append_pair("projectId", &metadata.project_id);
            query.append_pair("threadId", thread_id);
            if let Some(created_at) = metadata.created_at.as_deref() {
                query.append_pair("createdAt", created_at);
            }
            query.append_pair("t3SidebarMode", "collapsed");
        }
        return Ok(url.to_string());
    }

    let draft_id = gpui_stable_t3_draft_id(&reference.session_id);
    let draft_thread_id = thread_id
        .filter(|thread_id| thread_id.starts_with("ghostex-thread-"))
        .map(str::to_string)
        .unwrap_or_else(|| gpui_stable_t3_draft_thread_id(&reference.session_id));
    let draft_segment = gpui_t3_route_path_segment(&draft_id)
        .ok_or_else(|| "T3 draft route segment is invalid.".to_string())?;
    let created_at = metadata
        .created_at
        .clone()
        .unwrap_or_else(gpui_status_generated_at);
    url.set_path(&format!("/draft/{draft_segment}"));
    url.set_fragment(None);
    {
        let mut query = url.query_pairs_mut();
        query.clear();
        query.append_pair("ghostexEmbedded", "1");
        query.append_pair("ghostexProjectId", &reference.project_id);
        query.append_pair("ghostexSessionId", &reference.session_id);
        query.append_pair("ghostexDraft", "1");
        query.append_pair("environmentId", environment_id);
        query.append_pair("projectId", &metadata.project_id);
        query.append_pair("threadId", &draft_thread_id);
        query.append_pair("createdAt", &created_at);
        query.append_pair("t3SidebarMode", "collapsed");
    }
    Ok(url.to_string())
}

fn gpui_t3_thread_id_is_server_thread(thread_id: &str) -> bool {
    let normalized = thread_id.trim();
    !normalized.is_empty()
        && !normalized.starts_with("ghostex-thread-")
        && !normalized.starts_with("ghostex-draft-")
        && !normalized.starts_with("pending-")
}

fn gpui_t3_route_path_segment(value: &str) -> Option<&str> {
    let value = value.trim();
    (!value.is_empty()
        && value.chars().count() <= 512
        && !value.bytes().any(|byte| byte.is_ascii_control())
        && !value.contains(['/', '?', '#', '\\']))
    .then_some(value)
}

fn gpui_stable_t3_draft_id(session_id: &str) -> String {
    format!(
        "ghostex-draft-{}",
        gpui_stable_t3_identity_component(session_id)
    )
}

fn gpui_stable_t3_draft_thread_id(session_id: &str) -> String {
    format!(
        "ghostex-thread-{}",
        gpui_stable_t3_identity_component(session_id)
    )
}

fn gpui_stable_t3_identity_component(session_id: &str) -> String {
    let normalized = session_id
        .chars()
        .map(|ch| {
            let lower = ch.to_ascii_lowercase();
            if lower.is_ascii_alphanumeric() {
                lower
            } else {
                '-'
            }
        })
        .collect::<String>();
    let trimmed = normalized.trim_matches('-');
    if trimmed.is_empty() {
        "session".to_string()
    } else {
        trimmed.to_string()
    }
}

fn gpui_local_workspace_attach_rpc_params(
    reference: &GpuiLocalWorkspaceSessionKey,
    startup_text: Option<&str>,
) -> serde_json::Value {
    let mut params = serde_json::Map::new();
    params.insert(
        "projectId".to_string(),
        serde_json::Value::String(reference.project_id.clone()),
    );
    params.insert(
        "sessionId".to_string(),
        serde_json::Value::String(reference.session_id.clone()),
    );
    if let Some(startup_text) = startup_text {
        params.insert(
            "startupText".to_string(),
            serde_json::Value::String(startup_text.to_string()),
        );
    }
    if gpui_current_zmx_prompt_editor_attach_mode_is_monaco() {
        params.insert(
            "promptEditor".to_string(),
            serde_json::Value::String("monaco".to_string()),
        );
    }
    serde_json::Value::Object(params)
}

fn gpui_local_workspace_attach_object(
    result: &serde_json::Value,
) -> Result<&serde_json::Map<String, serde_json::Value>, String> {
    result
        .get("attach")
        .and_then(serde_json::Value::as_object)
        .ok_or_else(|| "Session attach metadata is unavailable.".to_string())
}

fn gpui_validate_local_workspace_attach_metadata(
    attach: &serde_json::Map<String, serde_json::Value>,
) -> Result<(), String> {
    gpui_validate_local_workspace_attach_not_restore_blocked(attach)?;
    if gpui_local_workspace_attach_string(attach, "attachCommand").is_none() {
        return Err("Session attach metadata is unavailable.".to_string());
    }
    if attach
        .get("startupTextDisposition")
        .and_then(serde_json::Value::as_str)
        == Some("queueAfterTerminalReady")
        && gpui_local_workspace_attach_startup_text(attach).is_some()
    {
        return Err(
            "gxserver did not confirm the session provider started before terminal attach."
                .to_string(),
        );
    }
    Ok(())
}

fn gpui_validate_local_workspace_attach_not_restore_blocked(
    attach: &serde_json::Map<String, serde_json::Value>,
) -> Result<(), String> {
    if attach.get("restoreBlocked").is_some() {
        return Err(
            "Session restore is blocked because its working directory is unavailable.".to_string(),
        );
    }
    Ok(())
}

fn should_start_local_zmx_provider_before_gpui_attach(
    attach: &serde_json::Map<String, serde_json::Value>,
) -> bool {
    attach.get("provider").and_then(serde_json::Value::as_str) == Some("zmx")
        && attach
            .get("providerState")
            .and_then(|provider| provider.get("lifecycleState"))
            .and_then(serde_json::Value::as_str)
            == Some("missing")
        && attach
            .get("startupTextDisposition")
            .and_then(serde_json::Value::as_str)
            == Some("queueAfterTerminalReady")
        && gpui_local_workspace_attach_startup_text(attach).is_some()
}

fn gpui_local_workspace_attach_startup_text(
    attach: &serde_json::Map<String, serde_json::Value>,
) -> Option<&str> {
    attach
        .get("startupText")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn gpui_local_workspace_attach_string<'a>(
    attach: &'a serde_json::Map<String, serde_json::Value>,
    key: &str,
) -> Option<&'a str> {
    attach
        .get(key)
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty() && !value.contains('\0'))
}

fn gpui_local_workspace_attach_title(
    attach: &serde_json::Map<String, serde_json::Value>,
) -> String {
    attach
        .get("session")
        .and_then(|session| session.get("title"))
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|title| {
            !title.is_empty()
                && title.chars().count() <= GPUI_PROJECT_CONTRACT_STRING_MAX_CHARS
                && !title.contains('\0')
                && !title.chars().any(char::is_control)
        })
        .unwrap_or("Terminal")
        .to_string()
}

fn insert_gpui_local_workspace_attach_terminal(
    workspace: &mut WorkspaceModel,
    runtime_sessions: &mut AgentsTerminalRuntimeSessionRegistry,
    launch_payload_source: &mut AgentsTerminalLaunchPayloadSource,
    local_workspace_session_mappings: &mut HashMap<GpuiLocalWorkspaceSessionKey, TerminalSessionId>,
    local_app_shot_session_mappings: &mut HashMap<String, TerminalSessionId>,
    requested_pane_id: WorkspacePaneId,
    key: GpuiLocalWorkspaceSessionKey,
    plan: GpuiLocalWorkspaceAttachTerminalPlan,
) -> Result<(WorkspacePaneId, TerminalSessionId), &'static str> {
    let GpuiLocalWorkspaceAttachTerminalPlan {
        attach_command,
        title,
        working_directory,
    } = plan;
    let payload = AgentsTerminalExplicitLaunchPayload {
        working_directory,
        command: Some(attach_command),
        env_vars: Vec::new(),
        initial_input: None,
        wait_after_command: false,
    };
    payload
        .to_ghostty_launch_payload()
        .map_err(|_| "GPUI could not prepare the session attach terminal command.")?;

    if workspace.find_leaf(requested_pane_id).is_none() {
        return Err("GPUI could not find the target pane for the session.");
    }
    let Some((pane_id, session_id)) =
        workspace.add_running_session_to_pane(requested_pane_id, title)
    else {
        return Err("GPUI could not create a terminal tab for the session.");
    };
    let runtime_session_id = runtime_sessions.ensure_runtime_session_id(session_id);
    let mount_slot_id = AgentsTerminalBodyMountSlotId {
        pane_id,
        session_id,
    };
    launch_payload_source.insert_explicit_payload_for_mount_slot(
        runtime_session_id,
        mount_slot_id,
        payload,
    );
    let gxserver_session_id = key.session_id.clone();
    local_workspace_session_mappings.insert(key, session_id);
    local_app_shot_session_mappings.insert(gxserver_session_id, session_id);
    Ok((pane_id, session_id))
}

fn gpui_validate_remote_attach_metadata(result: &serde_json::Value) -> Result<(), String> {
    let attach = result
        .get("attach")
        .ok_or_else(|| "Remote attach metadata is unavailable.".to_string())?;
    if attach.get("restoreBlocked").is_some() {
        return Err("Remote session restore is blocked on the remote machine.".to_string());
    }
    let attach_command = attach
        .get("attachCommand")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .unwrap_or_default();
    if attach_command.is_empty() {
        return Err("Remote attach metadata is unavailable.".to_string());
    }
    Ok(())
}

fn gpui_prepare_remote_resume_clipboard_command(
    config: &GpuiRemoteMachineConfig,
    target: &GpuiRemoteGxserverRequestTarget,
    reference: &GpuiRemoteAttachSessionReference,
) -> Result<String, String> {
    /*
    CDXC:GPUIRemoteAttach 2026-06-24-19:06:
    Copy Remote Resume asks the owning remote gxserver for its agent resume plan and wraps only the returned copy command in a saved-machine SSH command. The renderer supplies no command text or cwd, and Rust must not log the plan, cwd, SSH target, stdout/stderr, token, or daemon body.
    */
    let result = gpui_remote_gxserver_rpc_result(
        target,
        "/api/readAgentResumePlan",
        &serde_json::json!({
            "projectId": reference.project_id.as_str(),
            "sessionId": reference.session_id.as_str(),
        }),
        Duration::from_secs(15),
    )?;
    let resume_command = result
        .get("plan")
        .and_then(|plan| plan.get("copyCommand"))
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|command| !command.is_empty())
        .ok_or_else(|| "No resume command is available for that remote session.".to_string())?;
    let cwd = result
        .get("session")
        .and_then(|session| session.get("cwd"))
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|cwd| !cwd.is_empty());
    let remote_command = cwd
        .map(|cwd| format!("cd {} && {resume_command}", gpui_shell_single_quote(cwd)))
        .unwrap_or_else(|| resume_command.to_string());
    Ok(gpui_remote_ssh_shell_command(
        config,
        remote_command.as_str(),
        false,
    ))
}

fn gpui_remote_ghostex_attach_ssh_command(
    config: &GpuiRemoteMachineConfig,
    reference: &GpuiRemoteAttachSessionReference,
) -> String {
    gpui_remote_ssh_shell_command(
        config,
        gpui_remote_ghostex_attach_command(reference).as_str(),
        true,
    )
}

fn gpui_remote_ssh_shell_command(
    config: &GpuiRemoteMachineConfig,
    remote_command: &str,
    force_tty: bool,
) -> String {
    let mut arguments = vec!["ssh".to_string()];
    if force_tty {
        arguments.push("-tt".to_string());
    }
    arguments.extend(gpui_remote_ssh_target_arguments(config));
    arguments.push(gpui_login_shell_remote_command(remote_command));
    arguments
        .iter()
        .map(|argument| gpui_remote_shell_command_arg(argument))
        .collect::<Vec<_>>()
        .join(" ")
}

fn gpui_remote_ghostex_attach_command(reference: &GpuiRemoteAttachSessionReference) -> String {
    let mut parts = vec![
        "attach".to_string(),
        "--session-id".to_string(),
        gpui_shell_single_quote(reference.session_id.as_str()),
        "--project-id".to_string(),
        gpui_shell_single_quote(reference.project_id.as_str()),
    ];
    if gpui_current_zmx_prompt_editor_attach_mode_is_monaco() {
        parts.extend(["--prompt-editor".to_string(), "monaco".to_string()]);
    }
    [
        "remote_ghostex=\"$HOME/.ghostex/gxserver/package/bin/ghostex\"".to_string(),
        "if [ ! -x \"$remote_ghostex\" ]; then if [ -x \"$HOME/.local/bin/ghostex\" ]; then remote_ghostex=\"$HOME/.local/bin/ghostex\"; else remote_ghostex=\"ghostex\"; fi; fi".to_string(),
        format!("\"$remote_ghostex\" {}", parts.join(" ")),
    ]
    .join("; ")
}

fn gpui_current_zmx_prompt_editor_attach_mode_is_monaco() -> bool {
    // Monaco capability is only advertised at attach while this app actually
    // owns the CLI bridge; otherwise Ctrl+G would route to a host that cannot
    // open the editor and the CLI would fall back after a timeout instead of
    // selecting the machine editor up front.
    cli_bridge::gpui_cli_bridge_is_running()
        && shared_settings::shared_sidebar_settings_snapshot()
            .object()
            .get("promptEditorBackend")
            .and_then(serde_json::Value::as_str)
            == Some("monaco")
}

fn gpui_remote_shell_command_arg(value: &str) -> String {
    if value
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || "_/:=@%+.,-".contains(ch))
    {
        value.to_string()
    } else {
        gpui_shell_single_quote(value)
    }
}

fn gpui_remote_attach_terminal_process_command(ssh_command: &str) -> String {
    let body = [
        ssh_command,
        "__ghostex_remote_attach_exit=$?",
        "printf \"\\nRemote attach ended with exit code %s.\\n\" \"$__ghostex_remote_attach_exit\"",
        "exec /bin/zsh -l",
    ]
    .join("\n");
    format!("/bin/zsh -lic {}", gpui_shell_single_quote(body.as_str()))
}

#[cfg(target_os = "macos")]
fn gpui_remote_ssh_askpass_script(
    config: &GpuiRemoteMachineConfig,
) -> Result<Option<GpuiRemoteAskpassScript>, String> {
    if !config.has_saved_password {
        return Ok(None);
    }
    let unique_id = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    let directory = env::temp_dir().join(format!(
        "ghostex-gpui-ssh-askpass-{}-{unique_id}",
        std::process::id()
    ));
    let script = directory.join("askpass.sh");
    fs::create_dir_all(&directory)
        .map_err(|_| "Could not prepare SSH password helper.".to_string())?;
    let contents = format!(
        "#!/bin/sh\nexec /usr/bin/security find-generic-password -s {} -a {} -w\n",
        gpui_shell_single_quote(GPUI_REMOTE_SSH_PASSWORD_KEYCHAIN_SERVICE),
        gpui_shell_single_quote(config.remote_machine_id.as_str())
    );
    fs::write(&script, contents)
        .map_err(|_| "Could not prepare SSH password helper.".to_string())?;
    fs::set_permissions(&directory, fs::Permissions::from_mode(0o700))
        .map_err(|_| "Could not prepare SSH password helper.".to_string())?;
    fs::set_permissions(&script, fs::Permissions::from_mode(0o700))
        .map_err(|_| "Could not prepare SSH password helper.".to_string())?;
    Ok(Some(GpuiRemoteAskpassScript { directory, script }))
}

#[cfg(target_os = "macos")]
fn gpui_remote_ssh_askpass_environment(
    askpass: Option<&GpuiRemoteAskpassScript>,
) -> Option<HashMap<String, String>> {
    let askpass = askpass?;
    let mut environment: HashMap<String, String> = env::vars().collect();
    environment
        .entry("DISPLAY".to_string())
        .or_insert_with(|| "localhost:0".to_string());
    environment.insert(
        "SSH_ASKPASS".to_string(),
        gpui_path_string(askpass.script.as_path()),
    );
    environment.insert("SSH_ASKPASS_REQUIRE".to_string(), "force".to_string());
    Some(environment)
}

#[cfg(target_os = "macos")]
fn gpui_run_remote_process(
    executable: &str,
    arguments: &[String],
    environment: Option<HashMap<String, String>>,
    timeout: Duration,
) -> GpuiRemoteProcessResult {
    let mut command = Command::new(executable);
    command
        .args(arguments)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    if let Some(environment) = environment {
        command.envs(environment);
    }
    let mut child = match command.spawn() {
        Ok(child) => child,
        Err(error) => {
            return GpuiRemoteProcessResult {
                exit_code: 127,
                stderr: error.to_string(),
                stdout: String::new(),
            };
        }
    };
    let deadline = Instant::now() + timeout;
    loop {
        match child.try_wait() {
            Ok(Some(status)) => {
                let mut stdout = String::new();
                let mut stderr = String::new();
                if let Some(mut pipe) = child.stdout.take() {
                    let _ = pipe.read_to_string(&mut stdout);
                }
                if let Some(mut pipe) = child.stderr.take() {
                    let _ = pipe.read_to_string(&mut stderr);
                }
                return GpuiRemoteProcessResult {
                    exit_code: status.code().unwrap_or(1),
                    stderr,
                    stdout,
                };
            }
            Ok(None) if Instant::now() < deadline => thread::sleep(Duration::from_millis(50)),
            _ => {
                let _ = child.kill();
                let _ = child.wait();
                return GpuiRemoteProcessResult {
                    exit_code: 124,
                    stderr: "Remote SSH command timed out.".to_string(),
                    stdout: String::new(),
                };
            }
        }
    }
}

#[cfg(target_os = "macos")]
fn gpui_open_remote_gxserver_tunnel(
    config: &GpuiRemoteMachineConfig,
    token: &str,
) -> Result<GpuiRemoteGxserverConnection, String> {
    for local_port in gpui_remote_gxserver_candidate_ports() {
        let mut tunnel = match gpui_spawn_remote_gxserver_tunnel(config, local_port) {
            Ok(tunnel) => tunnel,
            Err(_) => continue,
        };
        if gpui_wait_for_remote_authenticated_health(local_port, token) {
            return Ok(GpuiRemoteGxserverConnection {
                _base_url: format!("http://127.0.0.1:{local_port}"),
                local_port,
                presentation_stream_cancel: None,
                presentation_stream_generation: None,
                token: token.to_string(),
                child: tunnel.child,
            });
        }
        let _ = tunnel.child.kill();
        let _ = tunnel.child.wait();
    }
    Err("Could not open an authenticated SSH tunnel to remote gxserver.".to_string())
}

#[cfg(target_os = "macos")]
fn gpui_spawn_remote_gxserver_tunnel(
    config: &GpuiRemoteMachineConfig,
    local_port: u16,
) -> Result<GpuiRemoteSpawnedTunnel, String> {
    let askpass = gpui_remote_ssh_askpass_script(config)?;
    let mut arguments = vec!["-N".to_string()];
    arguments.extend(gpui_remote_ssh_client_options(config.has_saved_password));
    arguments.extend([
        "-o".to_string(),
        "ExitOnForwardFailure=yes".to_string(),
        "-L".to_string(),
        format!("{local_port}:127.0.0.1:{GPUI_GXSERVER_LOCAL_API_PORT}"),
    ]);
    arguments.extend(gpui_remote_ssh_target_arguments(config));
    let mut command = Command::new("/usr/bin/ssh");
    command
        .args(arguments)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null());
    if let Some(environment) = gpui_remote_ssh_askpass_environment(askpass.as_ref()) {
        command.envs(environment);
    }
    let mut child = command
        .spawn()
        .map_err(|_| "Could not start the SSH tunnel.".to_string())?;
    thread::sleep(GPUI_REMOTE_GXSERVER_TUNNEL_STARTUP_DELAY);
    if child
        .try_wait()
        .map_err(|_| "Could not check the SSH tunnel process.".to_string())?
        .is_some()
    {
        return Err("SSH tunnel exited before remote gxserver became reachable.".to_string());
    }
    Ok(GpuiRemoteSpawnedTunnel {
        child,
        _askpass: askpass,
    })
}

fn gpui_remote_gxserver_candidate_ports() -> Vec<u16> {
    let range =
        u64::from(GPUI_REMOTE_GXSERVER_TUNNEL_PORT_MAX - GPUI_REMOTE_GXSERVER_TUNNEL_PORT_MIN + 1);
    let seed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos() as u64
        ^ u64::from(std::process::id());
    let mut ports = Vec::with_capacity(GPUI_REMOTE_GXSERVER_TUNNEL_ATTEMPTS);
    let mut seen = HashSet::new();
    for attempt in 0..(GPUI_REMOTE_GXSERVER_TUNNEL_ATTEMPTS * 2) {
        let offset = seed
            .wrapping_add((attempt as u64).wrapping_mul(7_919))
            .wrapping_rem(range);
        let port = GPUI_REMOTE_GXSERVER_TUNNEL_PORT_MIN + offset as u16;
        if seen.insert(port) {
            ports.push(port);
        }
        if ports.len() == GPUI_REMOTE_GXSERVER_TUNNEL_ATTEMPTS {
            break;
        }
    }
    ports
}

#[cfg(target_os = "macos")]
fn gpui_wait_for_remote_authenticated_health(local_port: u16, token: &str) -> bool {
    let deadline = Instant::now() + GPUI_REMOTE_GXSERVER_HEALTH_DEADLINE;
    while Instant::now() < deadline {
        if gpui_remote_authenticated_health(local_port, token) {
            return true;
        }
        thread::sleep(GPUI_REMOTE_GXSERVER_TUNNEL_RETRY_DELAY);
    }
    false
}

#[cfg(target_os = "macos")]
fn gpui_remote_authenticated_health(local_port: u16, token: &str) -> bool {
    let address = format!("127.0.0.1:{local_port}");
    let Ok(mut stream) = TcpStream::connect(address.as_str()) else {
        return false;
    };
    if stream
        .set_read_timeout(Some(GPUI_REMOTE_GXSERVER_HEALTH_TIMEOUT))
        .is_err()
        || stream
            .set_write_timeout(Some(GPUI_REMOTE_GXSERVER_HEALTH_TIMEOUT))
            .is_err()
    {
        return false;
    }
    let request = format!(
        "GET /api/health/server HTTP/1.1\r\nHost: {address}\r\nConnection: close\r\nAuthorization: Bearer {token}\r\n{GPUI_GXSERVER_PROTOCOL_HEADER}: {GPUI_GXSERVER_PROTOCOL_VERSION}\r\n\r\n",
    );
    if stream.write_all(request.as_bytes()).is_err() {
        return false;
    }
    let mut response = String::new();
    if stream.read_to_string(&mut response).is_err() {
        return false;
    }
    response
        .lines()
        .next()
        .and_then(|line| line.split_whitespace().nth(1))
        .and_then(|status| status.parse::<u16>().ok())
        .is_some_and(|status| (200..300).contains(&status))
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum GpuiRemoteSshPasswordKeychainResult {
    Unsupported,
    Failed,
    Success,
}

fn gpui_remote_machine_password_failure_title(has_password: bool) -> &'static str {
    if has_password {
        "SSH password not saved"
    } else {
        "SSH password not removed"
    }
}

fn gpui_normalize_remote_machine_id(input: &str) -> Option<String> {
    let id = input.trim();
    if id.is_empty() || id.chars().count() > GPUI_REMOTE_MACHINE_ID_MAX_CHARS {
        return None;
    }
    let prefix_len = "remote-".len();
    if id.len() <= prefix_len
        || !id
            .get(..prefix_len)
            .is_some_and(|prefix| prefix.eq_ignore_ascii_case("remote-"))
    {
        return None;
    }
    let Some(suffix) = id.get(prefix_len..) else {
        return None;
    };
    if suffix
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || ch == '_' || ch == '-')
    {
        return Some(id.to_string());
    }
    None
}

fn gpui_remote_machine_id_from_value(value: &serde_json::Value) -> Option<String> {
    value
        .as_object()
        .and_then(|machine| machine.get("id"))
        .and_then(serde_json::Value::as_str)
        .and_then(gpui_normalize_remote_machine_id)
}

fn gpui_settings_object_has_remote_machine_id(
    object: &serde_json::Map<String, serde_json::Value>,
    remote_machine_id: &str,
) -> bool {
    object
        .get("remoteMachines")
        .and_then(serde_json::Value::as_array)
        .is_some_and(|machines| {
            machines.iter().any(|machine| {
                gpui_remote_machine_id_from_value(machine).as_deref() == Some(remote_machine_id)
            })
        })
}

fn gpui_set_remote_machine_password_marker(
    object: &mut serde_json::Map<String, serde_json::Value>,
    remote_machine_id: &str,
    has_password: bool,
) -> bool {
    let Some(machines) = object
        .get_mut("remoteMachines")
        .and_then(serde_json::Value::as_array_mut)
    else {
        return false;
    };
    for machine in machines {
        let Some(machine_object) = machine.as_object_mut() else {
            continue;
        };
        if machine_object
            .get("id")
            .and_then(serde_json::Value::as_str)
            .and_then(gpui_normalize_remote_machine_id)
            .as_deref()
            != Some(remote_machine_id)
        {
            continue;
        }
        if has_password {
            machine_object.insert(
                "sshPasswordSaved".to_string(),
                serde_json::Value::Bool(true),
            );
        } else {
            machine_object.remove("sshPasswordSaved");
        }
        return true;
    }
    false
}

fn gpui_removed_remote_machine_password_ids(
    previous_settings: &serde_json::Map<String, serde_json::Value>,
    next_settings: &serde_json::Map<String, serde_json::Value>,
) -> Vec<String> {
    let next_ids: HashSet<String> = next_settings
        .get("remoteMachines")
        .and_then(serde_json::Value::as_array)
        .map(|machines| {
            machines
                .iter()
                .filter_map(gpui_remote_machine_id_from_value)
                .collect()
        })
        .unwrap_or_default();
    let Some(previous_machines) = previous_settings
        .get("remoteMachines")
        .and_then(serde_json::Value::as_array)
    else {
        return Vec::new();
    };
    let mut seen = HashSet::new();
    let mut removed = Vec::new();
    for machine in previous_machines {
        let Some(machine_object) = machine.as_object() else {
            continue;
        };
        if machine_object
            .get("sshPasswordSaved")
            .and_then(serde_json::Value::as_bool)
            != Some(true)
        {
            continue;
        }
        let Some(remote_machine_id) = gpui_remote_machine_id_from_value(machine) else {
            continue;
        };
        if !next_ids.contains(&remote_machine_id) && seen.insert(remote_machine_id.clone()) {
            removed.push(remote_machine_id);
        }
    }
    removed
}

#[cfg(target_os = "macos")]
fn gpui_save_remote_machine_password_to_keychain(
    remote_machine_id: &str,
    password: &str,
) -> GpuiRemoteSshPasswordKeychainResult {
    let Ok(remote_machine_id) = std::ffi::CString::new(remote_machine_id) else {
        return GpuiRemoteSshPasswordKeychainResult::Failed;
    };
    let password_bytes = password.as_bytes();
    match unsafe {
        GhostexGpuiSaveRemoteSshPassword(
            remote_machine_id.as_ptr(),
            password_bytes.as_ptr(),
            password_bytes.len(),
        )
    } {
        1 => GpuiRemoteSshPasswordKeychainResult::Success,
        -1 => GpuiRemoteSshPasswordKeychainResult::Unsupported,
        _ => GpuiRemoteSshPasswordKeychainResult::Failed,
    }
}

