fn gpui_save_remote_machine_password_to_keychain(
    _remote_machine_id: &str,
    _password: &str,
) -> GpuiRemoteSshPasswordKeychainResult {
    GpuiRemoteSshPasswordKeychainResult::Unsupported
}

