#[derive(Clone, Debug)]
struct GpuiSidebarHudButtons {
    agents: serde_json::Value,
    commands: serde_json::Value,
}

fn gpui_sidebar_hud_from_gxserver(
    timeout: Duration,
    active_project_id: Option<&str>,
) -> Result<GpuiSidebarHudButtons, String> {
    /*
    CDXC:SidebarHudContract 2026-06-24-20:34:
    GPUI Settings/app-modal and titlebar reads must use gxserver's normalized sidebar HUD contract instead of recreating custom agent/action projection in host Rust. If the endpoint is unavailable, callers leave those read rows empty rather than falling back to a second custom metadata normalizer.
    */
    let mut params = serde_json::Map::new();
    if let Some(active_project_id) =
        active_project_id.and_then(|value| gpui_trimmed_nonempty_str(Some(value)))
    {
        params.insert(
            "activeProjectId".to_string(),
            serde_json::Value::String(active_project_id.to_string()),
        );
    }
    let result = gpui_gxserver_rpc_result(
        "/api/readSidebarHud",
        &serde_json::Value::Object(params),
        timeout,
    )?;
    Ok(GpuiSidebarHudButtons {
        agents: gpui_sidebar_hud_array_field(&result, "agents")?,
        commands: gpui_sidebar_hud_array_field(&result, "commands")?,
    })
}

fn gpui_sidebar_hud_array_field(
    result: &serde_json::Value,
    key: &str,
) -> Result<serde_json::Value, String> {
    result
        .get(key)
        .and_then(serde_json::Value::as_array)
        .cloned()
        .map(serde_json::Value::Array)
        .ok_or_else(|| GPUI_SIDEBAR_METADATA_GENERIC_ERROR.to_string())
}

fn gpui_sidebar_agent_state_from_domain_projects(
    domain_projects: &[serde_json::Value],
) -> (Vec<GpuiStoredSidebarAgent>, Vec<String>) {
    let source_project = domain_projects.iter().find(|project| {
        let Some(project) = project.as_object() else {
            return false;
        };
        gpui_json_array_field_is_nonempty(project, "customAgents")
            || gpui_json_array_field_is_nonempty(project, "customAgentOrder")
    });
    let source_project = source_project.and_then(serde_json::Value::as_object);
    let stored_agents = gpui_normalized_stored_sidebar_agents(
        source_project.and_then(|project| project.get("customAgents")),
    );
    let stored_order = gpui_normalized_string_order(
        source_project.and_then(|project| project.get("customAgentOrder")),
    );
    (stored_agents, stored_order)
}

fn gpui_sidebar_agent_buttons_from_state(
    stored_agents: &[GpuiStoredSidebarAgent],
    stored_order: &[String],
) -> serde_json::Value {
    let mut buttons = Vec::<(String, serde_json::Value)>::new();
    for default_agent in GPUI_DEFAULT_SIDEBAR_AGENTS {
        let stored_agent = stored_agents
            .iter()
            .find(|agent| agent.agent_id == default_agent.agent_id);
        if stored_agent.is_none() && default_agent.hidden_by_default {
            continue;
        }
        if stored_agent.map(|agent| agent.hidden).unwrap_or(false) {
            continue;
        }

        let button = match stored_agent {
            Some(stored_agent) => {
                let name =
                    gpui_default_sidebar_agent_name(default_agent.agent_id, &stored_agent.name);
                gpui_sidebar_agent_button_value(
                    Some(stored_agent),
                    stored_agent.agent_id.as_str(),
                    stored_agent.command.as_str(),
                    stored_agent.icon.as_deref().unwrap_or(default_agent.icon),
                    true,
                    &name,
                )
            }
            None => gpui_sidebar_agent_button_value(
                None,
                default_agent.agent_id,
                default_agent.command,
                default_agent.icon,
                true,
                default_agent.name,
            ),
        };
        buttons.push((default_agent.agent_id.to_string(), button));
    }

    for stored_agent in stored_agents {
        if gpui_is_default_sidebar_agent_id(&stored_agent.agent_id) || stored_agent.hidden {
            continue;
        }
        let icon = stored_agent.icon.as_deref();
        buttons.push((
            stored_agent.agent_id.clone(),
            gpui_sidebar_agent_button_value(
                Some(stored_agent),
                &stored_agent.agent_id,
                &stored_agent.command,
                icon.unwrap_or(""),
                false,
                &stored_agent.name,
            ),
        ));
    }

    gpui_order_json_buttons(buttons, stored_order, "agentId")
}

fn gpui_sidebar_agent_button_value(
    stored_agent: Option<&GpuiStoredSidebarAgent>,
    agent_id: &str,
    command: &str,
    icon: &str,
    is_default: bool,
    name: &str,
) -> serde_json::Value {
    let mut button = serde_json::Map::new();
    if let Some(accept_all_mode) = stored_agent.and_then(|agent| agent.accept_all_mode.as_ref()) {
        button.insert(
            "acceptAllMode".to_string(),
            serde_json::Value::String(accept_all_mode.clone()),
        );
    }
    button.insert(
        "agentId".to_string(),
        serde_json::Value::String(agent_id.to_string()),
    );
    button.insert(
        "command".to_string(),
        serde_json::Value::String(command.to_string()),
    );
    if !icon.is_empty() {
        button.insert(
            "icon".to_string(),
            serde_json::Value::String(icon.to_string()),
        );
    }
    button.insert("isDefault".to_string(), serde_json::Value::Bool(is_default));
    button.insert(
        "name".to_string(),
        serde_json::Value::String(name.to_string()),
    );
    serde_json::Value::Object(button)
}

fn gpui_sidebar_command_state_for_active_project(
    domain_projects: &[serde_json::Value],
    active_project_id: &str,
) -> Result<
    (
        String,
        Vec<GpuiStoredSidebarCommand>,
        Vec<String>,
        Vec<String>,
    ),
    String,
> {
    let active_project = domain_projects
        .iter()
        .filter_map(serde_json::Value::as_object)
        .find(|project| {
            gpui_trimmed_json_string_field(project, "projectId") == Some(active_project_id)
        })
        .ok_or_else(|| GPUI_SIDEBAR_METADATA_GENERIC_ERROR.to_string())?;
    let active_project_id = gpui_trimmed_json_string_field(active_project, "projectId")
        .ok_or_else(|| GPUI_SIDEBAR_METADATA_GENERIC_ERROR.to_string())?;
    let owner_project_id = active_project
        .get("worktree")
        .and_then(serde_json::Value::as_object)
        .and_then(|worktree| gpui_trimmed_json_string_field(worktree, "parentProjectId"))
        .unwrap_or(active_project_id);
    let owner_project = domain_projects
        .iter()
        .filter_map(serde_json::Value::as_object)
        .find(|project| {
            gpui_trimmed_json_string_field(project, "projectId") == Some(owner_project_id)
        })
        .ok_or_else(|| GPUI_SIDEBAR_METADATA_GENERIC_ERROR.to_string())?;
    Ok((
        owner_project_id.to_string(),
        gpui_normalized_stored_sidebar_commands(owner_project.get("customCommands")),
        gpui_normalized_string_order(owner_project.get("customCommandOrder")),
        gpui_normalized_string_order(owner_project.get("deletedDefaultCommandIds")),
    ))
}

fn gpui_sidebar_command_buttons_from_state(
    stored_commands: &[GpuiStoredSidebarCommand],
    stored_order: &[String],
    deleted_default_command_ids: &[String],
) -> serde_json::Value {
    let deleted_default_command_ids = deleted_default_command_ids
        .iter()
        .map(String::as_str)
        .collect::<HashSet<_>>();
    let mut buttons = Vec::<(String, serde_json::Value)>::new();

    for default_command in GPUI_DEFAULT_SIDEBAR_COMMANDS {
        if deleted_default_command_ids.contains(default_command.command_id) {
            continue;
        }
        let button = stored_commands
            .iter()
            .find(|command| command.command_id == default_command.command_id)
            .map(gpui_sidebar_command_button_value)
            .unwrap_or_else(|| gpui_default_sidebar_command_button_value(default_command));
        buttons.push((default_command.command_id.to_string(), button));
    }

    for stored_command in stored_commands {
        if gpui_is_default_sidebar_command_id(&stored_command.command_id) {
            continue;
        }
        buttons.push((
            stored_command.command_id.clone(),
            gpui_sidebar_command_button_value(stored_command),
        ));
    }

    gpui_order_json_buttons(buttons, stored_order, "commandId")
}

fn gpui_default_sidebar_command_button_value(
    command: &GpuiDefaultSidebarCommand,
) -> serde_json::Value {
    serde_json::json!({
        "actionType": "terminal",
        "closeTerminalOnExit": false,
        "commandId": command.command_id,
        "isDefault": true,
        "name": command.name,
        "playCompletionSound": true,
    })
}

fn gpui_sidebar_command_button_value(command: &GpuiStoredSidebarCommand) -> serde_json::Value {
    let mut button = serde_json::Map::new();
    button.insert(
        "actionType".to_string(),
        serde_json::Value::String(command.action_type.to_string()),
    );
    button.insert(
        "closeTerminalOnExit".to_string(),
        serde_json::Value::Bool(command.close_terminal_on_exit),
    );
    if let Some(command_text) = command.command.as_ref() {
        button.insert(
            "command".to_string(),
            serde_json::Value::String(command_text.clone()),
        );
    }
    button.insert(
        "commandId".to_string(),
        serde_json::Value::String(command.command_id.clone()),
    );
    if let Some(icon) = command.icon.as_ref() {
        button.insert("icon".to_string(), serde_json::Value::String(icon.clone()));
    }
    button.insert(
        "isDefault".to_string(),
        serde_json::Value::Bool(command.is_default),
    );
    button.insert(
        "name".to_string(),
        serde_json::Value::String(command.name.clone()),
    );
    button.insert(
        "playCompletionSound".to_string(),
        serde_json::Value::Bool(command.play_completion_sound),
    );
    if let Some(url) = command.url.as_ref() {
        button.insert("url".to_string(), serde_json::Value::String(url.clone()));
    }
    serde_json::Value::Object(button)
}

fn gpui_titlebar_actions_for_active_project_id(
    active_project_id: Option<&str>,
) -> Vec<GpuiTitlebarAction> {
    /*
    CDXC:GPUITitlebarActions 2026-06-24-14:24:
    The visible GPUI titlebar Actions control must run the same sidebar/gxserver-projected command definitions that Settings and the SidebarApp expose. Read only the shared `hud.commands` contract shape from gxserver-derived project metadata, keep command text and URLs in memory for immediate Browser/command-terminal routing, and never infer actions from paths, git state, labels, env, terminal titles, or filesystem probes.

    CDXC:SidebarHudContract 2026-06-24-20:34:
    Titlebar Actions consume `/api/readSidebarHud` so active-project command scoping comes from the production gxserver contract rather than the GPUI app-modal Rust mirror.
    */
    let commands = gpui_sidebar_hud_from_gxserver(Duration::from_secs(2), active_project_id)
        .map(|hud| hud.commands)
        .unwrap_or_else(|_| serde_json::Value::Array(Vec::new()));
    gpui_titlebar_actions_from_sidebar_command_buttons(&commands)
}

fn gpui_titlebar_actions_from_sidebar_command_buttons(
    buttons: &serde_json::Value,
) -> Vec<GpuiTitlebarAction> {
    let Some(items) = buttons.as_array() else {
        return Vec::new();
    };
    items
        .iter()
        .filter_map(gpui_titlebar_action_from_sidebar_command_button)
        .collect()
}

fn gpui_titlebar_action_from_sidebar_command_button(
    value: &serde_json::Value,
) -> Option<GpuiTitlebarAction> {
    let object = value.as_object()?;
    let command_id = gpui_trimmed_json_string_field(object, "commandId")?.to_string();
    let action_type = match object.get("actionType").and_then(serde_json::Value::as_str) {
        Some("browser") => GpuiTitlebarActionType::Browser,
        Some("terminal") | None => GpuiTitlebarActionType::Terminal,
        _ => return None,
    };
    let name = object
        .get("name")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .unwrap_or_default()
        .to_string();
    let command = object
        .get("command")
        .and_then(serde_json::Value::as_str)
        .and_then(|command| gpui_trimmed_nonempty_str(Some(command)))
        .map(str::to_string);
    let url = object
        .get("url")
        .and_then(serde_json::Value::as_str)
        .and_then(|url| gpui_trimmed_nonempty_str(Some(url)))
        .map(str::to_string);
    Some(GpuiTitlebarAction {
        action_type,
        close_terminal_on_exit: action_type == GpuiTitlebarActionType::Terminal
            && object
                .get("closeTerminalOnExit")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false),
        command,
        command_id,
        name,
        play_completion_sound: action_type == GpuiTitlebarActionType::Terminal
            && object
                .get("playCompletionSound")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(true),
        run_mode: GpuiTitlebarActionRunMode::Default,
        url,
    })
}

fn gpui_normalized_stored_sidebar_agents(
    candidate: Option<&serde_json::Value>,
) -> Vec<GpuiStoredSidebarAgent> {
    let Some(items) = candidate.and_then(serde_json::Value::as_array) else {
        return Vec::new();
    };
    let mut agents = Vec::new();
    let mut seen_agent_ids = HashSet::new();
    for item in items {
        let Some(item) = item.as_object() else {
            continue;
        };
        let Some(agent_id) = gpui_trimmed_json_string_field(item, "agentId") else {
            continue;
        };
        if seen_agent_ids.contains(agent_id) {
            continue;
        }
        let Some(name) = gpui_trimmed_json_string_field(item, "name") else {
            continue;
        };
        let Some(command) = gpui_trimmed_json_string_field(item, "command") else {
            continue;
        };
        agents.push(GpuiStoredSidebarAgent {
            accept_all_mode: item
                .get("acceptAllMode")
                .and_then(serde_json::Value::as_str)
                .filter(|mode| matches!(*mode, "inherit" | "enabled" | "disabled"))
                .map(str::to_string),
            agent_id: agent_id.to_string(),
            command: command.to_string(),
            hidden: item
                .get("hidden")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false),
            icon: item
                .get("icon")
                .and_then(serde_json::Value::as_str)
                .and_then(gpui_strict_sidebar_agent_icon)
                .map(str::to_string),
            name: name.to_string(),
        });
        seen_agent_ids.insert(agent_id.to_string());
    }
    agents
}

fn gpui_normalized_stored_sidebar_commands(
    candidate: Option<&serde_json::Value>,
) -> Vec<GpuiStoredSidebarCommand> {
    let Some(items) = candidate.and_then(serde_json::Value::as_array) else {
        return Vec::new();
    };
    let mut commands = Vec::new();
    let mut seen_command_ids = HashSet::new();
    for item in items {
        let Some(item) = item.as_object() else {
            continue;
        };
        let Some(command_id) = gpui_trimmed_json_string_field(item, "commandId") else {
            continue;
        };
        if seen_command_ids.contains(command_id) {
            continue;
        }
        let url = item
            .get("url")
            .and_then(serde_json::Value::as_str)
            .and_then(|url| gpui_trimmed_nonempty_str(Some(url)))
            .map(str::to_string);
        let action_type = match item.get("actionType").and_then(serde_json::Value::as_str) {
            Some("browser") => "browser",
            Some("terminal") => "terminal",
            _ if url.is_some() => "browser",
            _ => "terminal",
        };
        let name = item
            .get("name")
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .unwrap_or("")
            .to_string();
        let icon = item
            .get("icon")
            .and_then(serde_json::Value::as_str)
            .and_then(gpui_sidebar_command_icon)
            .map(str::to_string);
        let is_default = item
            .get("isDefault")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false)
            || gpui_is_default_sidebar_command_id(command_id);

        if action_type == "browser" {
            let Some(url) = url else {
                continue;
            };
            commands.push(GpuiStoredSidebarCommand {
                action_type,
                close_terminal_on_exit: false,
                command: None,
                command_id: command_id.to_string(),
                icon,
                is_default,
                name,
                play_completion_sound: false,
                url: Some(url),
            });
            seen_command_ids.insert(command_id.to_string());
            continue;
        }

        let Some(command_text) = item
            .get("command")
            .and_then(serde_json::Value::as_str)
            .and_then(|command| gpui_trimmed_nonempty_str(Some(command)))
        else {
            continue;
        };
        commands.push(GpuiStoredSidebarCommand {
            action_type,
            close_terminal_on_exit: item
                .get("closeTerminalOnExit")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false),
            command: Some(command_text.to_string()),
            command_id: command_id.to_string(),
            icon,
            is_default,
            name,
            play_completion_sound: item
                .get("playCompletionSound")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(true),
            url: None,
        });
        seen_command_ids.insert(command_id.to_string());
    }
    commands
}

fn gpui_normalized_string_order(candidate: Option<&serde_json::Value>) -> Vec<String> {
    let Some(items) = candidate.and_then(serde_json::Value::as_array) else {
        return Vec::new();
    };
    gpui_normalized_string_order_from_values(items)
}

fn gpui_normalized_string_order_from_values(items: &[serde_json::Value]) -> Vec<String> {
    let mut order = Vec::new();
    let mut seen_ids = HashSet::new();
    for item in items {
        let Some(item) = item
            .as_str()
            .and_then(|value| gpui_trimmed_nonempty_str(Some(value)))
        else {
            continue;
        };
        if seen_ids.insert(item.to_string()) {
            order.push(item.to_string());
        }
    }
    order
}

fn gpui_sidebar_agent_metadata_write_from_command(
    command: &serde_json::Map<String, serde_json::Value>,
) -> Result<GpuiSidebarAgentMetadataWrite, String> {
    match command.get("type").and_then(serde_json::Value::as_str) {
        Some("saveSidebarAgent") => {
            let name = gpui_trimmed_json_string_field(command, "name")
                .ok_or_else(|| GPUI_SIDEBAR_METADATA_GENERIC_ERROR.to_string())?
                .to_string();
            let command_text = gpui_trimmed_json_string_field(command, "command")
                .ok_or_else(|| GPUI_SIDEBAR_METADATA_GENERIC_ERROR.to_string())?
                .to_string();
            let agent_id = command
                .get("agentId")
                .and_then(serde_json::Value::as_str)
                .and_then(|value| gpui_trimmed_nonempty_str(Some(value)))
                .map(str::to_string);
            let icon = command
                .get("icon")
                .and_then(serde_json::Value::as_str)
                .and_then(gpui_strict_sidebar_agent_icon)
                .map(str::to_string);
            let accept_all_mode = match command.get("acceptAllMode") {
                None => GpuiAgentAcceptAllModeUpdate::Preserve,
                Some(value) => match value.as_str() {
                    Some("inherit") => GpuiAgentAcceptAllModeUpdate::Set(None),
                    Some("enabled") | Some("disabled") => {
                        GpuiAgentAcceptAllModeUpdate::Set(value.as_str().map(str::to_string))
                    }
                    _ => return Err(GPUI_SIDEBAR_METADATA_GENERIC_ERROR.to_string()),
                },
            };
            Ok(GpuiSidebarAgentMetadataWrite::Save {
                accept_all_mode,
                agent_id,
                command: command_text,
                icon,
                name,
            })
        }
        Some("deleteSidebarAgent") => {
            let agent_id = gpui_trimmed_json_string_field(command, "agentId")
                .ok_or_else(|| GPUI_SIDEBAR_METADATA_GENERIC_ERROR.to_string())?
                .to_string();
            Ok(GpuiSidebarAgentMetadataWrite::Delete { agent_id })
        }
        Some("syncSidebarAgentOrder") => {
            let request_id = command
                .get("requestId")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default()
                .to_string();
            let agent_ids = command
                .get("agentIds")
                .and_then(serde_json::Value::as_array)
                .map(|items| gpui_normalized_string_order_from_values(items))
                .unwrap_or_default();
            Ok(GpuiSidebarAgentMetadataWrite::SyncOrder {
                agent_ids,
                request_id,
            })
        }
        _ => Err(GPUI_SIDEBAR_METADATA_GENERIC_ERROR.to_string()),
    }
}

fn gpui_sidebar_command_metadata_write_from_command(
    command: &serde_json::Map<String, serde_json::Value>,
    active_project_id: Option<String>,
) -> Result<GpuiSidebarCommandMetadataWrite, String> {
    let active_project_id = active_project_id.unwrap_or_default();
    match command.get("type").and_then(serde_json::Value::as_str) {
        Some("saveSidebarCommand") => {
            let name = command
                .get("name")
                .and_then(serde_json::Value::as_str)
                .map(str::trim)
                .unwrap_or_default()
                .to_string();
            let icon = command
                .get("icon")
                .and_then(serde_json::Value::as_str)
                .and_then(gpui_sidebar_command_icon)
                .map(str::to_string);
            if name.is_empty() && icon.is_none() {
                return Err(GPUI_SIDEBAR_METADATA_GENERIC_ERROR.to_string());
            }
            let action_type = match command
                .get("actionType")
                .and_then(serde_json::Value::as_str)
            {
                Some("browser") => "browser",
                Some("terminal") => "terminal",
                _ => return Err(GPUI_SIDEBAR_METADATA_GENERIC_ERROR.to_string()),
            };
            let terminal_command = command
                .get("command")
                .and_then(serde_json::Value::as_str)
                .and_then(|value| gpui_trimmed_nonempty_str(Some(value)))
                .map(str::to_string);
            let url = command
                .get("url")
                .and_then(serde_json::Value::as_str)
                .and_then(|value| gpui_trimmed_nonempty_str(Some(value)))
                .map(str::to_string);
            if action_type == "browser" && url.is_none() {
                return Err(GPUI_SIDEBAR_METADATA_GENERIC_ERROR.to_string());
            }
            if action_type == "terminal" && terminal_command.is_none() {
                return Err(GPUI_SIDEBAR_METADATA_GENERIC_ERROR.to_string());
            }
            Ok(GpuiSidebarCommandMetadataWrite::Save {
                action_type,
                active_project_id,
                close_terminal_on_exit: action_type == "terminal"
                    && command
                        .get("closeTerminalOnExit")
                        .and_then(serde_json::Value::as_bool)
                        .unwrap_or(false),
                command: (action_type == "terminal")
                    .then_some(terminal_command)
                    .flatten(),
                command_id: command
                    .get("commandId")
                    .and_then(serde_json::Value::as_str)
                    .and_then(|value| gpui_trimmed_nonempty_str(Some(value)))
                    .map(str::to_string),
                icon,
                name,
                play_completion_sound: action_type == "terminal"
                    && command
                        .get("playCompletionSound")
                        .and_then(serde_json::Value::as_bool)
                        .unwrap_or(true),
                url: (action_type == "browser").then_some(url).flatten(),
            })
        }
        Some("deleteSidebarCommand") => {
            let command_id = gpui_trimmed_json_string_field(command, "commandId")
                .ok_or_else(|| GPUI_SIDEBAR_METADATA_GENERIC_ERROR.to_string())?
                .to_string();
            Ok(GpuiSidebarCommandMetadataWrite::Delete {
                active_project_id,
                command_id,
            })
        }
        Some("syncSidebarCommandOrder") => {
            let request_id = command
                .get("requestId")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default()
                .to_string();
            let command_ids = command
                .get("commandIds")
                .and_then(serde_json::Value::as_array)
                .map(|items| gpui_normalized_string_order_from_values(items))
                .unwrap_or_default();
            Ok(GpuiSidebarCommandMetadataWrite::SyncOrder {
                active_project_id,
                command_ids,
                request_id,
            })
        }
        _ => Err(GPUI_SIDEBAR_METADATA_GENERIC_ERROR.to_string()),
    }
}

fn gpui_sidebar_agent_mutation_params(
    write: &GpuiSidebarAgentMetadataWrite,
    active_project_id: Option<String>,
) -> serde_json::Value {
    let mut params = serde_json::Map::new();
    params.insert(
        "target".to_string(),
        serde_json::Value::String("agent".to_string()),
    );
    if let Some(active_project_id) = active_project_id
        .as_deref()
        .and_then(|value| gpui_trimmed_nonempty_str(Some(value)))
    {
        params.insert(
            "activeProjectId".to_string(),
            serde_json::Value::String(active_project_id.to_string()),
        );
    }
    match write {
        GpuiSidebarAgentMetadataWrite::Save {
            accept_all_mode,
            agent_id,
            command,
            icon,
            name,
        } => {
            params.insert(
                "operation".to_string(),
                serde_json::Value::String("save".to_string()),
            );
            gpui_insert_optional_nonempty_string(&mut params, "agentId", agent_id.as_deref());
            params.insert(
                "command".to_string(),
                serde_json::Value::String(command.clone()),
            );
            gpui_insert_optional_nonempty_string(&mut params, "icon", icon.as_deref());
            params.insert("name".to_string(), serde_json::Value::String(name.clone()));
            match accept_all_mode {
                GpuiAgentAcceptAllModeUpdate::Preserve => {}
                GpuiAgentAcceptAllModeUpdate::Set(None) => {
                    params.insert(
                        "acceptAllMode".to_string(),
                        serde_json::Value::String("inherit".to_string()),
                    );
                }
                GpuiAgentAcceptAllModeUpdate::Set(Some(mode)) => {
                    params.insert(
                        "acceptAllMode".to_string(),
                        serde_json::Value::String(mode.clone()),
                    );
                }
            }
        }
        GpuiSidebarAgentMetadataWrite::Delete { agent_id } => {
            params.insert(
                "operation".to_string(),
                serde_json::Value::String("delete".to_string()),
            );
            params.insert(
                "agentId".to_string(),
                serde_json::Value::String(agent_id.clone()),
            );
        }
        GpuiSidebarAgentMetadataWrite::SyncOrder { agent_ids, .. } => {
            params.insert(
                "operation".to_string(),
                serde_json::Value::String("order".to_string()),
            );
            params.insert("agentIds".to_string(), gpui_string_array_value(agent_ids));
        }
    }
    serde_json::Value::Object(params)
}

fn gpui_sidebar_command_mutation_params(
    write: &GpuiSidebarCommandMetadataWrite,
) -> serde_json::Value {
    let mut params = serde_json::Map::new();
    params.insert(
        "target".to_string(),
        serde_json::Value::String("command".to_string()),
    );
    match write {
        GpuiSidebarCommandMetadataWrite::Save {
            action_type,
            active_project_id,
            close_terminal_on_exit,
            command,
            command_id,
            icon,
            name,
            play_completion_sound,
            url,
        } => {
            params.insert(
                "operation".to_string(),
                serde_json::Value::String("save".to_string()),
            );
            params.insert(
                "actionType".to_string(),
                serde_json::Value::String((*action_type).to_string()),
            );
            params.insert(
                "activeProjectId".to_string(),
                serde_json::Value::String(active_project_id.clone()),
            );
            params.insert(
                "closeTerminalOnExit".to_string(),
                serde_json::Value::Bool(*close_terminal_on_exit),
            );
            gpui_insert_optional_nonempty_string(&mut params, "command", command.as_deref());
            gpui_insert_optional_nonempty_string(&mut params, "commandId", command_id.as_deref());
            gpui_insert_optional_nonempty_string(&mut params, "icon", icon.as_deref());
            params.insert("name".to_string(), serde_json::Value::String(name.clone()));
            params.insert(
                "playCompletionSound".to_string(),
                serde_json::Value::Bool(*play_completion_sound),
            );
            gpui_insert_optional_nonempty_string(&mut params, "url", url.as_deref());
        }
        GpuiSidebarCommandMetadataWrite::Delete {
            active_project_id,
            command_id,
        } => {
            params.insert(
                "operation".to_string(),
                serde_json::Value::String("delete".to_string()),
            );
            params.insert(
                "activeProjectId".to_string(),
                serde_json::Value::String(active_project_id.clone()),
            );
            params.insert(
                "commandId".to_string(),
                serde_json::Value::String(command_id.clone()),
            );
        }
        GpuiSidebarCommandMetadataWrite::SyncOrder {
            active_project_id,
            command_ids,
            ..
        } => {
            params.insert(
                "operation".to_string(),
                serde_json::Value::String("order".to_string()),
            );
            params.insert(
                "activeProjectId".to_string(),
                serde_json::Value::String(active_project_id.clone()),
            );
            params.insert(
                "commandIds".to_string(),
                gpui_string_array_value(command_ids),
            );
        }
    }
    serde_json::Value::Object(params)
}

fn gpui_sidebar_metadata_mutation_item_ids(result: &serde_json::Value) -> Vec<String> {
    result
        .get("itemIds")
        .and_then(serde_json::Value::as_array)
        .map(|items| gpui_normalized_string_order_from_values(items))
        .unwrap_or_default()
}

fn gpui_apply_sidebar_agent_metadata_write(
    write: GpuiSidebarAgentMetadataWrite,
    active_project_id: Option<String>,
) -> Result<Option<serde_json::Value>, String> {
    let params = gpui_sidebar_agent_mutation_params(&write, active_project_id);
    let result = gpui_gxserver_rpc_result(
        "/api/mutateSidebarHudSettings",
        &params,
        Duration::from_secs(10),
    )?;
    let item_ids = gpui_sidebar_metadata_mutation_item_ids(&result);
    Ok(match write {
        GpuiSidebarAgentMetadataWrite::SyncOrder { request_id, .. } => Some(
            gpui_sidebar_order_sync_result_message("agent", &request_id, "success", item_ids),
        ),
        _ => None,
    })
}

fn gpui_next_sidebar_agent_metadata_state(
    stored_agents: Vec<GpuiStoredSidebarAgent>,
    stored_order: Vec<String>,
    write: GpuiSidebarAgentMetadataWrite,
) -> Result<
    (
        Vec<GpuiStoredSidebarAgent>,
        Vec<String>,
        Option<serde_json::Value>,
    ),
    String,
> {
    match write {
        GpuiSidebarAgentMetadataWrite::Save {
            accept_all_mode,
            agent_id,
            command,
            icon,
            name,
        } => {
            let current_agent_ids = gpui_sidebar_button_ids(
                &gpui_sidebar_agent_buttons_from_state(&stored_agents, &stored_order),
                "agentId",
            );
            let selected_default_agent_id = icon
                .as_deref()
                .and_then(gpui_default_sidebar_agent_by_icon)
                .map(|agent| agent.agent_id);
            let should_restore_hidden_default = agent_id.is_none()
                && selected_default_agent_id
                    .map(|agent_id| !gpui_is_sidebar_agent_visible(&stored_agents, agent_id))
                    .unwrap_or(false);
            let next_agent_id = agent_id
                .or_else(|| {
                    should_restore_hidden_default
                        .then_some(selected_default_agent_id)
                        .flatten()
                        .map(str::to_string)
                })
                .unwrap_or_else(|| gpui_create_custom_sidebar_agent_id(&name));
            let existing_index = stored_agents
                .iter()
                .position(|agent| agent.agent_id == next_agent_id);
            let previous_agent = existing_index.and_then(|index| stored_agents.get(index));
            let default_agent = gpui_default_sidebar_agent_by_id(&next_agent_id);
            let next_agent = GpuiStoredSidebarAgent {
                accept_all_mode: match accept_all_mode {
                    GpuiAgentAcceptAllModeUpdate::Preserve => previous_agent
                        .and_then(|agent| agent.accept_all_mode.as_ref())
                        .cloned(),
                    GpuiAgentAcceptAllModeUpdate::Set(mode) => mode,
                },
                agent_id: next_agent_id.clone(),
                command,
                hidden: false,
                icon: icon
                    .or_else(|| {
                        previous_agent
                            .and_then(|agent| agent.icon.as_ref())
                            .cloned()
                    })
                    .or_else(|| default_agent.map(|agent| agent.icon.to_string())),
                name,
            };
            let mut next_agents = stored_agents.clone();
            if let Some(existing_index) = existing_index {
                next_agents[existing_index] = next_agent;
            } else {
                next_agents.push(next_agent);
            }
            let next_order = if existing_index.is_some()
                || stored_order
                    .iter()
                    .any(|candidate| candidate == &next_agent_id)
                || gpui_is_default_sidebar_agent_id(&next_agent_id)
            {
                stored_order
            } else {
                let mut next_order = current_agent_ids;
                next_order.push(next_agent_id);
                next_order
            };
            Ok((next_agents, next_order, None))
        }
        GpuiSidebarAgentMetadataWrite::Delete { agent_id } => {
            if !gpui_is_default_sidebar_agent_id(&agent_id) {
                let next_agents = stored_agents
                    .into_iter()
                    .filter(|agent| agent.agent_id != agent_id)
                    .collect::<Vec<_>>();
                let next_order = stored_order
                    .into_iter()
                    .filter(|candidate| candidate != &agent_id)
                    .collect::<Vec<_>>();
                return Ok((next_agents, next_order, None));
            }
            let Some(default_agent) = gpui_default_sidebar_agent_by_id(&agent_id) else {
                return Ok((stored_agents, stored_order, None));
            };
            let existing_index = stored_agents
                .iter()
                .position(|agent| agent.agent_id == agent_id);
            let previous_agent = existing_index.and_then(|index| stored_agents.get(index));
            let next_agent = GpuiStoredSidebarAgent {
                accept_all_mode: None,
                agent_id: default_agent.agent_id.to_string(),
                command: previous_agent
                    .map(|agent| agent.command.clone())
                    .unwrap_or_else(|| default_agent.command.to_string()),
                hidden: true,
                icon: previous_agent
                    .and_then(|agent| agent.icon.as_ref())
                    .cloned()
                    .or_else(|| Some(default_agent.icon.to_string())),
                name: previous_agent
                    .map(|agent| agent.name.clone())
                    .unwrap_or_else(|| default_agent.name.to_string()),
            };
            let mut next_agents = stored_agents.clone();
            if let Some(existing_index) = existing_index {
                next_agents[existing_index] = next_agent;
            } else {
                next_agents.push(next_agent);
            }
            let next_order = stored_order
                .into_iter()
                .filter(|candidate| candidate != &agent_id)
                .collect::<Vec<_>>();
            Ok((next_agents, next_order, None))
        }
        GpuiSidebarAgentMetadataWrite::SyncOrder {
            agent_ids,
            request_id,
        } => {
            let current_agent_ids = gpui_sidebar_button_ids(
                &gpui_sidebar_agent_buttons_from_state(&stored_agents, &stored_order),
                "agentId",
            );
            let mut next_order = agent_ids
                .into_iter()
                .filter(|agent_id| {
                    current_agent_ids
                        .iter()
                        .any(|candidate| candidate == agent_id)
                })
                .collect::<Vec<_>>();
            for agent_id in current_agent_ids {
                if !next_order.iter().any(|candidate| candidate == &agent_id) {
                    next_order.push(agent_id);
                }
            }
            let item_ids = gpui_sidebar_button_ids(
                &gpui_sidebar_agent_buttons_from_state(&stored_agents, &next_order),
                "agentId",
            );
            Ok((
                stored_agents,
                next_order,
                Some(gpui_sidebar_order_sync_result_message(
                    "agent",
                    &request_id,
                    "success",
                    item_ids,
                )),
            ))
        }
    }
}

fn gpui_apply_sidebar_command_metadata_write(
    write: GpuiSidebarCommandMetadataWrite,
) -> Result<Option<serde_json::Value>, String> {
    let params = gpui_sidebar_command_mutation_params(&write);
    let result = gpui_gxserver_rpc_result(
        "/api/mutateSidebarHudSettings",
        &params,
        Duration::from_secs(10),
    )?;
    let item_ids = gpui_sidebar_metadata_mutation_item_ids(&result);
    Ok(match write {
        GpuiSidebarCommandMetadataWrite::SyncOrder { request_id, .. } => Some(
            gpui_sidebar_order_sync_result_message("command", &request_id, "success", item_ids),
        ),
        _ => None,
    })
}

fn gpui_sidebar_command_write_active_project_id(write: &GpuiSidebarCommandMetadataWrite) -> &str {
    match write {
        GpuiSidebarCommandMetadataWrite::Save {
            active_project_id, ..
        }
        | GpuiSidebarCommandMetadataWrite::Delete {
            active_project_id, ..
        }
        | GpuiSidebarCommandMetadataWrite::SyncOrder {
            active_project_id, ..
        } => active_project_id,
    }
}

fn gpui_next_sidebar_command_metadata_state(
    stored_commands: Vec<GpuiStoredSidebarCommand>,
    stored_order: Vec<String>,
    deleted_default_command_ids: Vec<String>,
    write: GpuiSidebarCommandMetadataWrite,
) -> Result<
    (
        Vec<GpuiStoredSidebarCommand>,
        Vec<String>,
        Vec<String>,
        Option<serde_json::Value>,
    ),
    String,
> {
    match write {
        GpuiSidebarCommandMetadataWrite::Save {
            action_type,
            close_terminal_on_exit,
            command,
            command_id,
            icon,
            name,
            play_completion_sound,
            url,
            ..
        } => {
            let current_command_ids = gpui_sidebar_button_ids(
                &gpui_sidebar_command_buttons_from_state(
                    &stored_commands,
                    &stored_order,
                    &deleted_default_command_ids,
                ),
                "commandId",
            );
            let next_command_id = command_id.unwrap_or_else(gpui_create_custom_sidebar_command_id);
            let next_command = GpuiStoredSidebarCommand {
                action_type,
                close_terminal_on_exit: action_type == "terminal" && close_terminal_on_exit,
                command: (action_type == "terminal").then_some(command).flatten(),
                command_id: next_command_id.clone(),
                icon,
                is_default: gpui_is_default_sidebar_command_id(&next_command_id),
                name,
                play_completion_sound: action_type == "terminal" && play_completion_sound,
                url: (action_type == "browser").then_some(url).flatten(),
            };
            gpui_reject_duplicate_sidebar_command_title(
                &next_command,
                &stored_commands,
                &stored_order,
                &deleted_default_command_ids,
            )?;
            let existing_index = stored_commands
                .iter()
                .position(|command| command.command_id == next_command_id);
            let mut next_commands = stored_commands.clone();
            if let Some(existing_index) = existing_index {
                next_commands[existing_index] = next_command;
            } else {
                next_commands.push(next_command);
            }
            let next_order = if existing_index.is_some()
                || stored_order
                    .iter()
                    .any(|candidate| candidate == &next_command_id)
                || gpui_is_default_sidebar_command_id(&next_command_id)
            {
                stored_order
            } else if current_command_ids
                .iter()
                .any(|candidate| candidate == &next_command_id)
            {
                current_command_ids
            } else {
                let mut next_order = current_command_ids;
                next_order.push(next_command_id.clone());
                next_order
            };
            let next_deleted_default_ids = if gpui_is_default_sidebar_command_id(&next_command_id) {
                deleted_default_command_ids
                    .into_iter()
                    .filter(|candidate| candidate != &next_command_id)
                    .collect::<Vec<_>>()
            } else {
                deleted_default_command_ids
            };
            Ok((next_commands, next_order, next_deleted_default_ids, None))
        }
        GpuiSidebarCommandMetadataWrite::Delete { command_id, .. } => {
            let next_commands = stored_commands
                .into_iter()
                .filter(|command| command.command_id != command_id)
                .collect::<Vec<_>>();
            let next_order = stored_order
                .into_iter()
                .filter(|candidate| candidate != &command_id)
                .collect::<Vec<_>>();
            let mut next_deleted_default_ids = deleted_default_command_ids;
            if gpui_is_default_sidebar_command_id(&command_id)
                && !next_deleted_default_ids
                    .iter()
                    .any(|candidate| candidate == &command_id)
            {
                next_deleted_default_ids.push(command_id);
            }
            Ok((next_commands, next_order, next_deleted_default_ids, None))
        }
        GpuiSidebarCommandMetadataWrite::SyncOrder {
            command_ids,
            request_id,
            ..
        } => {
            let current_command_ids = gpui_sidebar_button_ids(
                &gpui_sidebar_command_buttons_from_state(
                    &stored_commands,
                    &stored_order,
                    &deleted_default_command_ids,
                ),
                "commandId",
            );
            let mut next_order = command_ids
                .into_iter()
                .filter(|command_id| {
                    current_command_ids
                        .iter()
                        .any(|candidate| candidate == command_id)
                })
                .collect::<Vec<_>>();
            for command_id in current_command_ids {
                if !next_order.iter().any(|candidate| candidate == &command_id) {
                    next_order.push(command_id);
                }
            }
            let item_ids = gpui_sidebar_button_ids(
                &gpui_sidebar_command_buttons_from_state(
                    &stored_commands,
                    &next_order,
                    &deleted_default_command_ids,
                ),
                "commandId",
            );
            Ok((
                stored_commands,
                next_order,
                deleted_default_command_ids,
                Some(gpui_sidebar_order_sync_result_message(
                    "command",
                    &request_id,
                    "success",
                    item_ids,
                )),
            ))
        }
    }
}

fn gpui_persist_sidebar_agents_to_gxserver_projects(
    domain_projects: &[serde_json::Value],
    agents: &[GpuiStoredSidebarAgent],
    agent_order: &[String],
) -> Result<(), String> {
    let mut updated_any = false;
    for project in domain_projects
        .iter()
        .filter_map(serde_json::Value::as_object)
    {
        let Some(project_id) = gpui_trimmed_json_string_field(project, "projectId") else {
            continue;
        };
        let mut params = serde_json::Map::new();
        params.insert(
            "projectId".to_string(),
            serde_json::Value::String(project_id.to_string()),
        );
        params.insert(
            "customAgents".to_string(),
            gpui_stored_sidebar_agents_value(agents),
        );
        params.insert(
            "customAgentOrder".to_string(),
            gpui_string_array_value(agent_order),
        );
        let result = gpui_gxserver_rpc_result(
            "/api/updateProject",
            &serde_json::Value::Object(params),
            Duration::from_secs(10),
        )?;
        if result
            .get("project")
            .and_then(serde_json::Value::as_object)
            .is_none()
        {
            return Err(GPUI_SIDEBAR_METADATA_GENERIC_ERROR.to_string());
        }
        updated_any = true;
    }
    if updated_any {
        Ok(())
    } else {
        Err(GPUI_SIDEBAR_METADATA_GENERIC_ERROR.to_string())
    }
}

fn gpui_reject_duplicate_sidebar_command_title(
    next_command: &GpuiStoredSidebarCommand,
    stored_commands: &[GpuiStoredSidebarCommand],
    stored_order: &[String],
    deleted_default_command_ids: &[String],
) -> Result<(), String> {
    let next_title_key = gpui_sidebar_command_title_key(
        &next_command.name,
        next_command.command.as_deref(),
        next_command.url.as_deref(),
    );
    let buttons = gpui_sidebar_command_buttons_from_state(
        stored_commands,
        stored_order,
        deleted_default_command_ids,
    );
    let duplicate = buttons
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(serde_json::Value::as_object)
        .any(|candidate| {
            gpui_trimmed_json_string_field(candidate, "commandId")
                .map(|command_id| command_id != next_command.command_id)
                .unwrap_or(false)
                && gpui_sidebar_command_title_key(
                    candidate
                        .get("name")
                        .and_then(serde_json::Value::as_str)
                        .unwrap_or_default(),
                    candidate.get("command").and_then(serde_json::Value::as_str),
                    candidate.get("url").and_then(serde_json::Value::as_str),
                ) == next_title_key
        });
    if duplicate {
        Err(GPUI_SIDEBAR_DUPLICATE_ACTION_TITLE_ERROR.to_string())
    } else {
        Ok(())
    }
}

fn gpui_sidebar_command_title_key(name: &str, command: Option<&str>, url: Option<&str>) -> String {
    let title = gpui_normalized_sidebar_command_title(Some(name))
        .or_else(|| {
            gpui_normalized_sidebar_command_title(command.or(url))
                .map(gpui_sidebar_command_short_title)
        })
        .unwrap_or_default();
    title.to_lowercase()
}

fn gpui_sidebar_command_short_title(value: String) -> String {
    value.chars().take(20).collect()
}

fn gpui_normalized_sidebar_command_title(value: Option<&str>) -> Option<String> {
    let normalized = value?.split_whitespace().collect::<Vec<_>>().join(" ");
    (!normalized.is_empty()).then_some(normalized)
}

fn gpui_sidebar_button_ids(buttons: &serde_json::Value, id_key: &str) -> Vec<String> {
    buttons
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(serde_json::Value::as_object)
        .filter_map(|button| gpui_trimmed_json_string_field(button, id_key))
        .map(str::to_string)
        .collect()
}

fn gpui_sidebar_order_sync_result_message(
    kind: &'static str,
    request_id: &str,
    status: &'static str,
    item_ids: Vec<String>,
) -> serde_json::Value {
    serde_json::json!({
        "itemIds": item_ids,
        "kind": kind,
        "requestId": request_id,
        "status": status,
        "type": "sidebarOrderSyncResult",
    })
}

fn gpui_is_sidebar_agent_visible(agents: &[GpuiStoredSidebarAgent], agent_id: &str) -> bool {
    agents
        .iter()
        .find(|agent| agent.agent_id == agent_id)
        .map(|agent| !agent.hidden)
        .unwrap_or(true)
}

fn gpui_default_sidebar_agent_by_id(agent_id: &str) -> Option<&'static GpuiDefaultSidebarAgent> {
    GPUI_DEFAULT_SIDEBAR_AGENTS
        .iter()
        .find(|agent| agent.agent_id == agent_id)
}

fn gpui_default_sidebar_agent_by_icon(icon: &str) -> Option<&'static GpuiDefaultSidebarAgent> {
    if icon == "browser" {
        return None;
    }
    GPUI_DEFAULT_SIDEBAR_AGENTS
        .iter()
        .find(|agent| agent.icon == icon)
}

fn gpui_create_custom_sidebar_agent_id(name: &str) -> String {
    let slug = name
        .trim()
        .to_lowercase()
        .chars()
        .map(|ch| if ch.is_ascii_alphanumeric() { ch } else { '-' })
        .collect::<String>()
        .split('-')
        .filter(|segment| !segment.is_empty())
        .collect::<Vec<_>>()
        .join("-");
    let slug = if slug.is_empty() {
        "agent".to_string()
    } else {
        slug.chars().take(24).collect::<String>()
    };
    format!("custom-{slug}-{}", gpui_generated_sidebar_metadata_suffix())
}

fn gpui_create_custom_sidebar_command_id() -> String {
    format!("custom-{}", gpui_generated_sidebar_metadata_suffix())
}

fn gpui_generated_sidebar_metadata_suffix() -> String {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or_default();
    format!(
        "{}-{}",
        gpui_base36(nanos),
        gpui_base36(std::process::id() as u128)
    )
}

fn gpui_base36(mut value: u128) -> String {
    const DIGITS: &[u8; 36] = b"0123456789abcdefghijklmnopqrstuvwxyz";
    if value == 0 {
        return "0".to_string();
    }
    let mut output = Vec::new();
    while value > 0 {
        let digit = (value % 36) as usize;
        output.push(DIGITS[digit] as char);
        value /= 36;
    }
    output.iter().rev().collect()
}

fn gpui_stored_sidebar_agents_value(agents: &[GpuiStoredSidebarAgent]) -> serde_json::Value {
    serde_json::Value::Array(
        agents
            .iter()
            .map(|agent| {
                let mut item = serde_json::Map::new();
                if let Some(accept_all_mode) = agent.accept_all_mode.as_ref() {
                    item.insert(
                        "acceptAllMode".to_string(),
                        serde_json::Value::String(accept_all_mode.clone()),
                    );
                }
                item.insert(
                    "agentId".to_string(),
                    serde_json::Value::String(agent.agent_id.clone()),
                );
                item.insert(
                    "command".to_string(),
                    serde_json::Value::String(agent.command.clone()),
                );
                item.insert("hidden".to_string(), serde_json::Value::Bool(agent.hidden));
                if let Some(icon) = agent.icon.as_ref() {
                    item.insert("icon".to_string(), serde_json::Value::String(icon.clone()));
                }
                item.insert(
                    "isDefault".to_string(),
                    serde_json::Value::Bool(gpui_is_default_sidebar_agent_id(&agent.agent_id)),
                );
                item.insert(
                    "name".to_string(),
                    serde_json::Value::String(agent.name.clone()),
                );
                serde_json::Value::Object(item)
            })
            .collect(),
    )
}

fn gpui_stored_sidebar_commands_value(commands: &[GpuiStoredSidebarCommand]) -> serde_json::Value {
    serde_json::Value::Array(
        commands
            .iter()
            .map(|command| {
                let mut item = serde_json::Map::new();
                item.insert(
                    "actionType".to_string(),
                    serde_json::Value::String(command.action_type.to_string()),
                );
                item.insert(
                    "closeTerminalOnExit".to_string(),
                    serde_json::Value::Bool(command.close_terminal_on_exit),
                );
                if let Some(command_text) = command.command.as_ref() {
                    item.insert(
                        "command".to_string(),
                        serde_json::Value::String(command_text.clone()),
                    );
                }
                item.insert(
                    "commandId".to_string(),
                    serde_json::Value::String(command.command_id.clone()),
                );
                if let Some(icon) = command.icon.as_ref() {
                    item.insert("icon".to_string(), serde_json::Value::String(icon.clone()));
                }
                item.insert(
                    "isDefault".to_string(),
                    serde_json::Value::Bool(command.is_default),
                );
                item.insert(
                    "name".to_string(),
                    serde_json::Value::String(command.name.clone()),
                );
                item.insert(
                    "playCompletionSound".to_string(),
                    serde_json::Value::Bool(command.play_completion_sound),
                );
                if let Some(url) = command.url.as_ref() {
                    item.insert("url".to_string(), serde_json::Value::String(url.clone()));
                }
                serde_json::Value::Object(item)
            })
            .collect(),
    )
}

fn gpui_string_array_value(items: &[String]) -> serde_json::Value {
    serde_json::Value::Array(
        items
            .iter()
            .map(|item| serde_json::Value::String(item.clone()))
            .collect(),
    )
}

fn gpui_order_json_buttons(
    buttons: Vec<(String, serde_json::Value)>,
    stored_order: &[String],
    id_key: &str,
) -> serde_json::Value {
    let mut ordered_buttons = Vec::new();
    let mut used_ids = HashSet::new();
    for item_id in stored_order {
        if let Some((_, button)) = buttons.iter().find(|(button_id, _)| button_id == item_id) {
            ordered_buttons.push(button.clone());
            used_ids.insert(item_id.clone());
        }
    }
    for (button_id, button) in buttons {
        let actual_id = button
            .get(id_key)
            .and_then(serde_json::Value::as_str)
            .unwrap_or(button_id.as_str());
        if used_ids.insert(actual_id.to_string()) {
            ordered_buttons.push(button);
        }
    }
    serde_json::Value::Array(ordered_buttons)
}

fn gpui_json_array_field_is_nonempty(
    object: &serde_json::Map<String, serde_json::Value>,
    key: &str,
) -> bool {
    object
        .get(key)
        .and_then(serde_json::Value::as_array)
        .map(|items| !items.is_empty())
        .unwrap_or(false)
}

fn gpui_is_default_sidebar_agent_id(agent_id: &str) -> bool {
    GPUI_DEFAULT_SIDEBAR_AGENTS
        .iter()
        .any(|agent| agent.agent_id == agent_id)
}

fn gpui_default_sidebar_agent_name(agent_id: &str, stored_name: &str) -> String {
    let default_name = GPUI_DEFAULT_SIDEBAR_AGENTS
        .iter()
        .find(|agent| agent.agent_id == agent_id)
        .map(|agent| agent.name);
    let Some(default_name) = default_name else {
        return stored_name.to_string();
    };
    let normalized = stored_name.trim().to_ascii_lowercase();
    if (agent_id == "codex" && normalized == "codex cli")
        || (agent_id == "claude" && normalized == "claude code")
        || (agent_id == "cursor" && normalized == "cursor")
        || (agent_id == "pi" && normalized == "pi")
    {
        default_name.to_string()
    } else {
        stored_name.to_string()
    }
}

fn gpui_is_default_sidebar_command_id(command_id: &str) -> bool {
    GPUI_DEFAULT_SIDEBAR_COMMANDS
        .iter()
        .any(|command| command.command_id == command_id)
}

fn gpui_strict_sidebar_agent_icon(candidate: &str) -> Option<&str> {
    if candidate == "browser" {
        return Some(candidate);
    }
    GPUI_DEFAULT_SIDEBAR_AGENTS
        .iter()
        .any(|agent| agent.icon == candidate)
        .then_some(candidate)
}

fn gpui_sidebar_command_icon(candidate: &str) -> Option<&str> {
    GPUI_SIDEBAR_COMMAND_ICON_IDS
        .iter()
        .any(|icon| *icon == candidate)
        .then_some(candidate)
}

#[derive(Clone, Debug)]
struct GpuiT3RuntimeStatus {
    detail: String,
    installed: bool,
    source: &'static str,
}

fn gpui_settings_command_ordered_agent_ids(
    command: &serde_json::Map<String, serde_json::Value>,
) -> Option<Vec<String>> {
    let agent_ids = command.get("agentIds")?.as_array()?;
    let mut seen = HashSet::new();
    let normalized = agent_ids
        .iter()
        .filter_map(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|agent_id| !agent_id.is_empty())
        .map(str::to_string)
        .filter(|agent_id| seen.insert(agent_id.clone()))
        .collect::<Vec<_>>();
    (!normalized.is_empty()).then_some(normalized)
}

fn gpui_settings_command_agent_ids(
    command: &serde_json::Map<String, serde_json::Value>,
) -> Option<HashSet<String>> {
    let agent_ids = command.get("agentIds")?.as_array()?;
    let normalized = agent_ids
        .iter()
        .filter_map(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|agent_id| !agent_id.is_empty())
        .map(str::to_string)
        .collect::<HashSet<_>>();
    (!normalized.is_empty()).then_some(normalized)
}

fn gpui_home_dir() -> PathBuf {
    env::var_os("HOME")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("/Users/Shared"))
}

fn gpui_which_command(command: &str) -> Option<PathBuf> {
    if command.contains('/') || command.trim().is_empty() {
        return None;
    }
    env::var_os("PATH")
        .into_iter()
        .flat_map(|path_value| env::split_paths(&path_value).collect::<Vec<_>>())
        .map(|directory| directory.join(command))
        .find(|candidate| gpui_is_executable_file(candidate))
}

fn gpui_is_probably_ghostex_command(path: &Path, command: &str) -> bool {
    /*
    CDXC:GPUISettingsAgentSkills 2026-06-24-13:08:
    This predicate feeds both read-only CLI status and Settings skill execution. Keep it strict enough for execution: only marked wrappers or app-owned command realpaths count as Ghostex-owned, not broad file text such as "Ghostex CLI".
    */
    if gpui_is_marked_ghostex_wrapper_file(path) {
        return true;
    }
    let realpath = gpui_realpath_or_self(path);
    if gpui_is_ghostex_app_owned_command_realpath(command, &realpath) {
        return true;
    }
    gpui_current_bundle_cli_dir_for_ownership_probe()
        .as_ref()
        .map(|cli_dir| gpui_path_is_relative_to(&realpath, cli_dir))
        .unwrap_or(false)
}

fn gpui_file_contains_ghostex_cli_wrapper_marker(path: &Path) -> bool {
    gpui_is_marked_ghostex_wrapper_file(path)
}

fn gpui_current_bundle_cli_dir_for_ownership_probe() -> Option<PathBuf> {
    let executable = env::current_exe().ok()?;
    let bundle_root = find_app_bundle_root(&executable)?;
    let cli_dir = bundle_root.join("Contents/Resources/CLI");
    gpui_is_dir(&cli_dir).then_some(cli_dir)
}

fn gpui_marked_ghostex_wrapper_content(content: &str) -> bool {
    content.contains(GPUI_GHOSTEX_CLI_WRAPPER_MARKER) && content.contains("ghostex-cli.mjs")
}

fn gpui_t3_runtime_status() -> GpuiT3RuntimeStatus {
    let bundled = gpui_t3_bundled_entrypoint();
    if bundled
        .as_ref()
        .map(|path| gpui_is_file(path))
        .unwrap_or(false)
    {
        return GpuiT3RuntimeStatus {
            detail: "T3 Code runtime is bundled with this app.".to_string(),
            installed: true,
            source: "bundled",
        };
    }

    let configured_root = env::var_os("VSMUX_T3CODE_REPO_ROOT")
        .or_else(|| env::var_os("ghostex_T3CODE_REPO_ROOT"))
        .map(PathBuf::from);
    let configured_entrypoint = configured_root
        .as_ref()
        .map(|root| root.join("apps/server/src/bin.ts"));
    if configured_entrypoint
        .as_ref()
        .map(|path| gpui_is_file(path))
        .unwrap_or(false)
    {
        return GpuiT3RuntimeStatus {
            detail: "T3 Code is using an explicit development checkout.".to_string(),
            installed: true,
            source: "development",
        };
    }

    GpuiT3RuntimeStatus {
        detail:
            "T3 Code runtime was not found in the GPUI bundle or a configured development checkout."
                .to_string(),
        installed: false,
        source: "missing",
    }
}

fn gpui_t3_bundled_entrypoint() -> Option<PathBuf> {
    let executable = env::current_exe().ok();
    if let Some(bundle_root) = executable
        .as_ref()
        .and_then(|path| find_app_bundle_root(path))
    {
        let bundled = bundle_root.join("Contents/Resources/sidebar/t3code-server/dist/bin.mjs");
        if bundled.exists() {
            return Some(bundled);
        }
    }
    Some(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("dist/sidebar/t3code-server/dist/bin.mjs"))
}

fn gpui_is_file(path: &Path) -> bool {
    fs::metadata(path)
        .map(|metadata| metadata.is_file())
        .unwrap_or(false)
}

fn gpui_is_dir(path: &Path) -> bool {
    fs::metadata(path)
        .map(|metadata| metadata.is_dir())
        .unwrap_or(false)
}

fn gpui_is_executable_file(path: &Path) -> bool {
    let Ok(metadata) = fs::metadata(path) else {
        return false;
    };
    if !metadata.is_file() {
        return false;
    }
    #[cfg(unix)]
    {
        metadata.permissions().mode() & 0o111 != 0
    }
    #[cfg(not(unix))]
    {
        true
    }
}

fn gpui_directory_size_bytes(path: &Path) -> u64 {
    let Ok(metadata) = fs::symlink_metadata(path) else {
        return 0;
    };
    if metadata.is_file() {
        return metadata.len();
    }
    if !metadata.is_dir() {
        return 0;
    }
    fs::read_dir(path)
        .map(|children| {
            children
                .filter_map(Result::ok)
                .map(|child| gpui_directory_size_bytes(&child.path()))
                .sum()
        })
        .unwrap_or(0)
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct GpuiAppModalProductState {
    pinned_prompts: Vec<GpuiPinnedPrompt>,
    scratch_pad_content: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct GpuiPinnedPrompt {
    content: String,
    created_at: String,
    prompt_id: String,
    title: String,
    updated_at: String,
}

fn gpui_read_gxserver_app_user_data(timeout: Duration) -> GpuiAppModalProductState {
    /*
    CDXC:GxserverAppUserData 2026-06-24-13:30:
    GPUI app-modal hydrate reads Scratch Pad and Pinned Prompts from gxserver's
    shared app-user-data snapshot instead of the old GPUI product-state file.
    Parse only the shared React contract fields and silently drop malformed
    prompt rows without logging note or prompt content.
    */
    gpui_gxserver_rpc_result("/api/readAppUserData", &serde_json::json!({}), timeout)
        .ok()
        .and_then(|value| gpui_app_modal_product_state_from_value(&value))
        .unwrap_or_default()
}

fn gpui_save_gxserver_scratch_pad(content: &str) -> Result<(), String> {
    gpui_gxserver_rpc_result(
        "/api/saveScratchPad",
        &serde_json::json!({ "content": content }),
        Duration::from_secs(5),
    )
    .map(|_| ())
}

fn gpui_save_gxserver_pinned_prompt(
    content: &str,
    title: &str,
    prompt_id: Option<&str>,
) -> Result<(), String> {
    let mut params = serde_json::Map::new();
    params.insert(
        "content".to_string(),
        serde_json::Value::String(content.to_string()),
    );
    params.insert(
        "title".to_string(),
        serde_json::Value::String(title.to_string()),
    );
    if let Some(prompt_id) = prompt_id {
        params.insert(
            "promptId".to_string(),
            serde_json::Value::String(prompt_id.to_string()),
        );
    }
    gpui_gxserver_rpc_result(
        "/api/savePinnedPrompt",
        &serde_json::Value::Object(params),
        Duration::from_secs(5),
    )
    .map(|_| ())
}

fn gpui_app_modal_product_state_from_value(
    value: &serde_json::Value,
) -> Option<GpuiAppModalProductState> {
    let object = value.as_object()?;
    Some(GpuiAppModalProductState {
        pinned_prompts: gpui_pinned_prompts_from_value(object.get("pinnedPrompts")),
        scratch_pad_content: object
            .get("scratchPadContent")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("")
            .to_string(),
    })
}

fn gpui_pinned_prompts_from_value(value: Option<&serde_json::Value>) -> Vec<GpuiPinnedPrompt> {
    let Some(items) = value.and_then(serde_json::Value::as_array) else {
        return Vec::new();
    };
    gpui_normalize_pinned_prompts(
        items
            .iter()
            .filter_map(gpui_pinned_prompt_from_value)
            .collect::<Vec<_>>(),
    )
}

fn gpui_pinned_prompt_from_value(value: &serde_json::Value) -> Option<GpuiPinnedPrompt> {
    let object = value.as_object()?;
    let prompt_id = object.get("promptId")?.as_str()?.trim().to_string();
    let content = object.get("content")?.as_str()?.to_string();
    let created_at = object.get("createdAt")?.as_str()?.to_string();
    let title = object
        .get("title")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("");
    let updated_at = object.get("updatedAt")?.as_str()?.to_string();
    if prompt_id.is_empty() || content.is_empty() || created_at.is_empty() || updated_at.is_empty()
    {
        return None;
    }
    Some(GpuiPinnedPrompt {
        title: gpui_normalize_pinned_prompt_title(title, &content),
        content,
        created_at,
        prompt_id,
        updated_at,
    })
}

fn gpui_normalize_pinned_prompts(mut prompts: Vec<GpuiPinnedPrompt>) -> Vec<GpuiPinnedPrompt> {
    prompts.retain(|prompt| {
        !prompt.prompt_id.is_empty()
            && !prompt.content.is_empty()
            && !prompt.created_at.is_empty()
            && !prompt.updated_at.is_empty()
    });
    prompts.sort_by(|left, right| right.updated_at.cmp(&left.updated_at));
    prompts
}

fn gpui_pinned_prompt_value(prompt: &GpuiPinnedPrompt) -> serde_json::Value {
    serde_json::json!({
        "content": prompt.content.clone(),
        "createdAt": prompt.created_at.clone(),
        "promptId": prompt.prompt_id.clone(),
        "title": prompt.title.clone(),
        "updatedAt": prompt.updated_at.clone(),
    })
}

fn gpui_normalize_pinned_prompt_title(title: &str, content: &str) -> String {
    let trimmed_title = title.trim();
    if !trimmed_title.is_empty() {
        return trimmed_title.to_string();
    }
    content
        .lines()
        .map(str::trim)
        .find(|line| !line.is_empty())
        .map(|line| line.chars().take(80).collect::<String>())
        .filter(|line| !line.is_empty())
        .unwrap_or_else(|| "Untitled Prompt".to_string())
}

fn gpui_active_project_id_from_snapshot(snapshot: Option<&GpuiProjectSnapshot>) -> Option<&str> {
    snapshot
        .and_then(|snapshot| snapshot.active_project_id.as_ref())
        .map(|project_id| project_id.0.as_str())
}

fn gpui_sidebar_command_session_indicators_from_command_pane_sources(
    commands: &serde_json::Value,
    command_pane_sessions: &serde_json::Value,
) -> serde_json::Value {
    /*
    CDXC:GPUICommandSessionHud 2026-06-27-08:45:
    Command-session HUD matching consumes the same external bridge shape emitted by command-pane sources: `sessionId` must be a string accepted by the canonical `G{u64}` parser and `status` must be a known lifecycle value before commandId/title matching runs. Stale legacy numeric, lowercase, malformed, non-string, or invalid-status rows must be invisible to matching so they cannot mask a live canonical row, and emitted indicators must continue to omit command text, paths, URLs, run ids, status files, terminal output, and unknown raw fields.
    */
    let Some(commands) = commands.as_array() else {
        return serde_json::Value::Array(Vec::new());
    };
    let sessions = command_pane_sessions
        .as_array()
        .map(Vec::as_slice)
        .unwrap_or(&[]);
    serde_json::Value::Array(
        commands
            .iter()
            .filter_map(|command| {
                if command
                    .get("actionType")
                    .and_then(serde_json::Value::as_str)
                    != Some("terminal")
                {
                    return None;
                }
                let command_id = command
                    .get("commandId")
                    .and_then(serde_json::Value::as_str)
                    .and_then(gpui_command_pane_sidebar_indicator_text)?;
                let command_title = gpui_sidebar_command_indicator_title_from_command(command)?;
                let command_title_key = gpui_command_pane_sidebar_indicator_key(&command_title);
                if command_title_key.is_empty() {
                    return None;
                }
                let mapped_session = sessions.iter().find(|session| {
                    gpui_sidebar_command_indicator_matchable_session_source(session)
                        && session
                            .get("commandId")
                            .and_then(serde_json::Value::as_str)
                            .is_some_and(|candidate| candidate == command_id.as_str())
                        && gpui_command_pane_sidebar_indicator_key(
                            session
                                .get("title")
                                .and_then(serde_json::Value::as_str)
                                .unwrap_or_default(),
                        ) == command_title_key
                });
                let session = mapped_session.or_else(|| {
                    sessions.iter().find(|session| {
                        gpui_sidebar_command_indicator_matchable_session_source(session)
                            && gpui_command_pane_sidebar_indicator_key(
                                session
                                    .get("title")
                                    .and_then(serde_json::Value::as_str)
                                    .unwrap_or_default(),
                            ) == command_title_key
                    })
                })?;
                let session_id = gpui_sidebar_command_indicator_session_id(session)?;
                let status = gpui_sidebar_command_indicator_status(session)?;
                let title = session
                    .get("title")
                    .and_then(serde_json::Value::as_str)
                    .and_then(gpui_command_pane_sidebar_indicator_text);
                let mut indicator = serde_json::json!({
                    "commandId": command_id,
                    "isActive": session
                        .get("isActive")
                        .and_then(serde_json::Value::as_bool)
                        .unwrap_or(false),
                    "sessionId": session_id,
                    "status": status,
                });
                if let Some(title) = title {
                    indicator["title"] = serde_json::json!(title);
                }
                for key in [
                    "delayedSendDeadlineAt",
                    "delayedSendRemainingLabel",
                    "closeAfterDoneDeadlineAt",
                    "closeAfterDoneRemainingLabel",
                ] {
                    if let Some(value) = session
                        .get(key)
                        .and_then(serde_json::Value::as_str)
                        .and_then(gpui_command_pane_sidebar_indicator_text)
                    {
                        indicator[key] = serde_json::json!(value);
                    }
                }
                for key in ["delayedSendRemainingMs", "closeAfterDoneRemainingMs"] {
                    if let Some(value) = session.get(key).and_then(serde_json::Value::as_u64) {
                        indicator[key] = serde_json::json!(value);
                    }
                }
                if session
                    .get("closeAfterDone")
                    .and_then(serde_json::Value::as_bool)
                    == Some(true)
                {
                    indicator["closeAfterDone"] = serde_json::json!(true);
                }
                Some(indicator)
            })
            .collect(),
    )
}

fn gpui_sidebar_command_indicator_matchable_session_source(session: &serde_json::Value) -> bool {
    gpui_sidebar_command_indicator_session_id(session).is_some()
        && gpui_sidebar_command_indicator_status(session).is_some()
}

fn gpui_sidebar_command_indicator_session_id(session: &serde_json::Value) -> Option<&str> {
    let session_id = session.get("sessionId")?.as_str()?;
    gpui_command_session_id_from_external_id(session_id)?;
    Some(session_id)
}

fn gpui_sidebar_command_indicator_status(session: &serde_json::Value) -> Option<&'static str> {
    match session.get("status").and_then(serde_json::Value::as_str) {
        Some("idle") => Some("idle"),
        Some("running") => Some("running"),
        Some("error") => Some("error"),
        _ => None,
    }
}

fn gpui_sidebar_command_indicator_title_from_command(
    command: &serde_json::Value,
) -> Option<String> {
    if let Some(name) = command
        .get("name")
        .and_then(serde_json::Value::as_str)
        .and_then(gpui_command_pane_sidebar_indicator_text)
    {
        return Some(name);
    }
    let command_text = command
        .get("command")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default()
        .trim()
        .chars()
        .take(20)
        .collect::<String>();
    gpui_command_pane_sidebar_indicator_text(&command_text)
}

fn gpui_command_pane_sidebar_indicator_key(value: &str) -> String {
    gpui_command_pane_sidebar_indicator_text(value)
        .map(|text| text.to_lowercase())
        .unwrap_or_default()
}

