fn next_available_gpui_local_workspace_lifecycle_request_id(
    next_request_id: u64,
    mut is_pending: impl FnMut(u64) -> bool,
) -> Option<(u64, u64)> {
    next_available_gpui_local_workspace_lifecycle_request_id_in_range(
        next_request_id,
        GPUI_SIDEBAR_WORKSPACE_TERMINAL_LIFECYCLE_REQUEST_ID_MAX,
        &mut is_pending,
    )
}

fn next_available_gpui_local_workspace_lifecycle_request_id_in_range(
    next_request_id: u64,
    request_id_max: u64,
    mut is_pending: impl FnMut(u64) -> bool,
) -> Option<(u64, u64)> {
    /*
    CDXC:GPUIWorkspaceLifecycle 2026-06-26-23:44:
    Rust-to-sidebar lifecycle acks are matched only by request id, so id allocation must never overwrite a still-pending close/sleep/wake request after wraparound. Skip live pending ids and fail dispatch only if the bounded id space is exhausted.
    */
    let request_id_max = request_id_max.max(1);
    let first_request_id = next_request_id.clamp(1, request_id_max);
    let mut request_id = first_request_id;
    loop {
        let next_candidate = if request_id >= request_id_max {
            1
        } else {
            request_id + 1
        };
        if !is_pending(request_id) {
            return Some((request_id, next_candidate));
        }
        request_id = next_candidate;
        if request_id == first_request_id {
            return None;
        }
    }
}

fn gpui_gxserver_focus_contract_object(
    value: &serde_json::Value,
) -> Result<
    &serde_json::Map<String, serde_json::Value>,
    GpuiGxserverPresentationFocusStateContractError,
> {
    value
        .as_object()
        .ok_or(GpuiGxserverPresentationFocusStateContractError::ExpectedObject)
}

fn reject_unexpected_gxserver_focus_contract_keys(
    object: &serde_json::Map<String, serde_json::Value>,
    allowed_keys: &[&str],
) -> Result<(), GpuiGxserverPresentationFocusStateContractError> {
    if object
        .keys()
        .any(|key| !allowed_keys.contains(&key.as_str()))
    {
        return Err(GpuiGxserverPresentationFocusStateContractError::UnexpectedKey);
    }
    Ok(())
}

fn optional_gxserver_focus_session_id_field(
    object: &serde_json::Map<String, serde_json::Value>,
    key: &str,
) -> Result<Option<String>, GpuiGxserverPresentationFocusStateContractError> {
    match object.get(key) {
        None | Some(serde_json::Value::Null) => Ok(None),
        Some(value) => gxserver_focus_session_id_string(value).map(Some),
    }
}

fn required_gxserver_visible_session_ids_field(
    object: &serde_json::Map<String, serde_json::Value>,
) -> Result<Vec<String>, GpuiGxserverPresentationFocusStateContractError> {
    let value = object
        .get("visibleSessionIds")
        .ok_or(GpuiGxserverPresentationFocusStateContractError::MissingField)?;
    let array = value
        .as_array()
        .ok_or(GpuiGxserverPresentationFocusStateContractError::MalformedField)?;
    if array.len() > GPUI_SIDEBAR_VISIBLE_SESSION_IDS_MAX {
        return Err(GpuiGxserverPresentationFocusStateContractError::MalformedField);
    }
    let mut seen = HashSet::new();
    let mut session_ids = Vec::with_capacity(array.len());
    for value in array {
        let session_id = gxserver_focus_session_id_string(value)?;
        if seen.insert(session_id.clone()) {
            session_ids.push(session_id);
        }
    }
    Ok(session_ids)
}

